sparql_query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazard
  ?name
  ?type
  ?startDate
  ?endDate
  ?deaths
  ?damageCrops
  ?damageInfrastructure
  ?affectedArea
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?name .
}
ORDER BY ?place

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?place
  ?percentDiabetic
  ?percentObese
  ?percentBelowPovertyLine
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?percentDiabetic . }
  OPTIONAL { ?place kwgl-ont:percentObese ?percentObese . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?percentBelowPovertyLine . }
}
ORDER BY ?place

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event ?count WHERE {
  { SELECT (COUNT(DISTINCT ?e) AS ?count)
    WHERE { ?e a kwgl-ont:Earthquake . }
  }
  ?event a kwgl-ont:Earthquake .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?attribute ?totalCount WHERE {
  {   # list each tornado‑specific datatype property
    SELECT DISTINCT ?attribute WHERE {
      ?attribute rdf:type owl:DatatypeProperty .
      FILTER ( CONTAINS(LCASE(STR(?attribute)), "tornado") )
    }
  }
  UNION
  {   # compute the total number of such attributes
    SELECT (COUNT(DISTINCT ?attr) AS ?totalCount) WHERE {
      ?attr rdf:type owl:DatatypeProperty .
      FILTER ( CONTAINS(LCASE(STR(?attr)), "tornado") )
    }
    BIND ("Total" AS ?attribute)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?earthquake
  ?name
  ?startDate
  ?endDate
  ?hazardType
WHERE {
  ?earthquake rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?earthquake kwgl-ont:hasName ?name . }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasHazardType ?hazardType . }
}
ORDER BY ?earthquake

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazardEvent
  ?name
  ?numberOfDeaths
  ?affectedAreaInAcres
  ?damageToCropsInDollars
  ?damageToInfrastructureInDollars
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
}
ORDER BY ?hazardEvent

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?property ?value ?startDate ?endDate
WHERE {
  ?place a kwgl-ont:Place .
  ?place ?property ?value .
  FILTER(isLiteral(?value))
  FILTER(CONTAINS(LCASE(STR(?property)), "hurricane"))

  OPTIONAL {
    ?event a kwgl-ont:Hurricane ;
           kwgl-ont:impactedBy ?place ;
           kwgl-ont:hasStartDate ?startDate ;
           kwgl-ont:hasEndDate ?endDate .
  }
}
ORDER BY ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?tornadoEvent
  ?place
  ?startDate
  ?endDate
  ?damageToInfrastructure
  ?damageToCrops
  ?dollarDamageOnPlace
WHERE {
  ?tornadoEvent rdf:type kwgl-ont:Tornado .
  OPTIONAL { ?tornadoEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?tornadoEvent kwgl-ont:hasEndDate   ?endDate   . }
  OPTIONAL { ?tornadoEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?tornadoEvent kwgl-ont:damageToCropsInDollars            ?damageToCrops           . }

  ?tornadoEvent kwgl-ont:hasImpacted ?place .

  OPTIONAL {
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageOnPlace .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?name ?type ?startDate ?endDate ?deaths ?cropDamage ?infraDamage ?area
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?name .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name ?percentBelowPovertyLine ?percentDiabetic ?percentObese
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?percentBelowPovertyLine . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?percentDiabetic . }
  OPTIONAL { ?place kwgl-ont:percentObese ?percentObese . }
  FILTER (BOUND(?percentBelowPovertyLine) || BOUND(?percentDiabetic) || BOUND(?percentObese))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name ?population ?households ?povertyRate ?diabeticRate ?obesityRate
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyRate . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabeticRate . }
  OPTIONAL { ?place kwgl-ont:percentObese ?obesityRate . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?earthquakeHazard ?hazardName ?totalCount WHERE {
  # Subquery to compute the total number of earthquake hazards
  {
    SELECT (COUNT(?e) AS ?totalCount)
    WHERE { ?e a kwgl-ont:Earthquake . }
  }

  # Retrieve each individual earthquake hazard and its optional name
  OPTIONAL {
    ?earthquakeHazard a kwgl-ont:Earthquake .
    OPTIONAL { ?earthquakeHazard kwgl-ont:hasName ?hazardName . }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?place ?hazardEvent ?hazardType 
                ?startDate ?endDate ?numberOfDeaths 
                ?damageToCrops ?damageToInfrastructure ?affectedArea
WHERE {
  ?place a kwgl-ont:Place .

  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasImpacted ?place ;
               kwgl-ont:hasHazardType ?hazardType .

  FILTER ( ?hazardType IN (kwglr:hurricane,
                           kwglr:tropicalStorm,
                           kwglr:tropicalDepression,
                           kwglr:stormSurgeTide) )

  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate          ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate            ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths        ?numberOfDeaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres   ?affectedArea . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place 
       ?name
       ?numFloods
       ?numFloods2018 ?numFloods2019 ?numFloods2020 ?numFloods2021 ?numFloods2022
       ?damageFloods
       ?damageFloods2018 ?damageFloods2019 ?damageFloods2020 ?damageFloods2021 ?damageFloods2022
WHERE {
  # all places
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }

  # overall flood count and yearly counts
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?numFloods . }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2018 ?numFloods2018 . }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2019 ?numFloods2019 . }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2020 ?numFloods2020 . }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2021 ?numFloods2021 . }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2022 ?numFloods2022 . }

  # overall flood dollar damage and yearly damages
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damageFloods . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2018 ?damageFloods2018 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2019 ?damageFloods2019 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2020 ?damageFloods2020 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2021 ?damageFloods2021 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2022 ?damageFloods2022 . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?earthquake ?name ?startDate ?endDate ?numDeaths ?affectedArea ?damageCrops ?damageInfrastructure ?hazardType
WHERE {
  ?earthquake a kwgl-ont:Earthquake .
  OPTIONAL { ?earthquake kwgl-ont:hasName ?name . }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?numDeaths . }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  OPTIONAL { ?earthquake kwgl-ont:hasHazardType ?hazardType . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardEvent ?name ?deaths ?cropDamage ?infraDamage
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT 
       ?hurricane ?hName
       ?place ?pName
       ?startDate ?endDate
       ?deaths ?affectedArea
       ?damageCrops ?damageInfra
       ?damageProp ?damageValue
WHERE {
  # Hurricane instances
  ?hurricane a kwgl-ont:Hurricane .
  OPTIONAL { ?hurricane kwgl-ont:hasName               ?hName . }
  OPTIONAL { ?hurricane kwgl-ont:hasStartDate          ?startDate . }
  OPTIONAL { ?hurricane kwgl-ont:hasEndDate            ?endDate . }
  OPTIONAL { ?hurricane kwgl-ont:numberOfDeaths        ?deaths . }
  OPTIONAL { ?hurricane kwgl-ont:affectedAreaInAcres   ?affectedArea . }
  OPTIONAL { ?hurricane kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?hurricane kwgl-ont:damageToInfrastructureInDollars ?damageInfra . }

  # Places impacted by the hurricane
  OPTIONAL {
    ?hurricane kwgl-ont:hasImpacted ?place .
    OPTIONAL { ?place kwgl-ont:hasName ?pName . }

    # Damage impact details on the place (all dollar‑damage properties for hurricanes)
    OPTIONAL {
      ?place ?damageProp ?damageValue .
      ?damageProp rdfs:subPropertyOf* kwgl-ont:dollarDamageOfHurricanesImpactingPlace .
    }
  }
}
ORDER BY ?hurricane ?place ?damageProp

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazardEvent
       ?place
       ?startDate
       ?endDate
       ?damageToCrops
       ?damageToInfrastructure
       ?dollarDamageTornadoes
WHERE {
  # Tornado‑specific hazard events
  ?hazardEvent a kwgl-ont:Tornado ;
               kwgl-ont:hasHazardType kwglr:tornado ;
               kwgl-ont:impactedBy ?place .

  # Temporal extent (if present)
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate   ?endDate   . }

  # Damage details
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars        ?damageToCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageTornadoes . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT 
       ?hazard
       ?hazardName
       ?type
       ?place
       ?placeName
       ?startDate
       ?endDate
       ?damageToCrops
       ?damageToInfrastructure
WHERE {
  # storm‑specific hazard events
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?type ;
          kwgl-ont:hasName ?hazardName ;
          kwgl-ont:hasStartDate ?startDate ;
          kwgl-ont:hasEndDate   ?endDate .

  VALUES ?type {
    kwglr:hurricane
    kwglr:tropicalStorm
    kwglr:tropicalDepression
    kwglr:stormSurgeTide
    kwglr:highWind
    kwglr:strongWind
    kwglr:winterStorm
    kwglr:tornado
  }

  # place impacted by the hazard
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?placeName ;
         kwgl-ont:impactedBy ?hazard .

  # optional damage details attached to the hazard event
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars      ?damageToCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
}
ORDER BY ?startDate ?hazardName

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?hazard ?type ?time ?property ?value
WHERE {
  ?hazard a ?type .
  ?type rdfs:subClassOf* kwg-ont:Hazard .
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time . }
  OPTIONAL {
    ?hazard ?property ?value .
    FILTER(?property != rdf:type && ?property != rdfs:label)
  }
}
ORDER BY ?hazard ?property

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place rdfs:label ?name . }
  OPTIONAL { ?place kwg-ont:hasName ?name . }
}
ORDER BY ?place

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?healthProperty
WHERE {
  ?place a geo:Feature .
  ?obs a sosa:Observation ;
       sosa:observedProperty ?healthProperty ;
       sosa:hasFeatureOfInterest ?place .
  FILTER (
    EXISTS { ?healthProperty rdfs:subClassOf* kwg-ont:PublicHealthObservableProperty } ||
    EXISTS { ?healthProperty rdfs:subClassOf* kwg-ont:ImpactObservableProperty } ||
    EXISTS { ?healthProperty rdfs:subClassOf* kwg-ont:VulnerabilityObservableProperty }
  )
}
ORDER BY ?place ?healthProperty

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?demographicAttribute
WHERE {
  { ?demographicAttribute rdfs:subClassOf kwg-ont:CensusObservableProperty }
  UNION
  { 
    ?obs a kwg-ont:CensusACS5YearEstimatesObservation ;
         sosa:observedProperty ?demographicAttribute .
  }
}
ORDER BY ?demographicAttribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquakeType ?totalCount WHERE {
  # Subquery to compute the total number of earthquake hazard classes
  {
    SELECT (COUNT(DISTINCT ?e) AS ?totalCount)
    WHERE {
      ?e rdfs:subClassOf* kwg-ont:Earthquake .
    }
  }
  # Retrieve each available earthquake hazard class
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
}
ORDER BY ?earthquakeType

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?stormHazard ?attribute ?value ?place
WHERE {
  { ?stormHazard rdfs:subClassOf* kwg-ont:StormTrack . }
  UNION
  { ?stormHazard rdfs:subClassOf* kwg-ont:StormTracklet . }

  OPTIONAL { ?stormHazard ?attribute ?value . }

  OPTIONAL {
    ?stormHazard kwg-ont:sfWithin|kwg-ont:spatialRelation ?place .
    FILTER(?place != ?stormHazard)
  }
}
ORDER BY ?stormHazard ?attribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?hazard ?property ?value
WHERE {
  VALUES ?floodClass { 
    kwg-ont:NOAAFlood 
    kwg-ont:NOAAFlashFlood 
    kwg-ont:NOAALakeshoreFlood 
    kwg-ont:NOAACoastalFlood 
  }
  ?hazard a ?floodClass .
  OPTIONAL { ?hazard ?property ?value . }
}
ORDER BY ?hazard ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?climateAttribute
WHERE {
  ?climateAttribute rdfs:subClassOf* kwg-ont:ClimateObservableProperty .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricane ?attr ?attrValue
               ?impact ?impactProp ?impactVal ?time
WHERE {
  # Hurricane events (subclass of NOAAHurricane)
  ?hurricane a kwg-ont:NOAAHurricane .

  # Hazard attributes related to the hurricane (exclude rdf:type)
  OPTIONAL { 
    ?hurricane ?attr ?attrValue .
    FILTER(?attr != rdf:type) 
  }

  # Damage impact observations linked to this hurricane
  OPTIONAL {
    ?impact a kwg-ont:ImpactObservation ;
            sosa:hasFeatureOfInterest ?hurricane .

    OPTIONAL { ?impact sosa:observedProperty ?impactProp . }
    OPTIONAL { ?impact sosa:hasSimpleResult   ?impactVal . }
    OPTIONAL { ?impact sosa:phenomenonTime   ?time . }
  }
}
ORDER BY ?hurricane ?attr ?impact

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?tornado ?damageProp ?value ?place ?time
WHERE {
  ?obs a kwg-ont:ImpactObservation .
  ?obs sosa:observedProperty ?damageProp .
  ?obs sosa:hasFeatureOfInterest ?tornado .
  ?tornado a kwg-ont:NOAATornado .

  OPTIONAL { ?obs sosa:hasSimpleResult ?value . }

  OPTIONAL {
    ?tornado kwg-ont:spatialRelation ?place .
    FILTER ( ?place a geo:Feature )
  }

  OPTIONAL { ?tornado kwg-ont:hasTemporalScope ?time . }
}
ORDER BY ?tornado ?damageProp

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?doi
WHERE {
  ?publication coresr-ont:hasIdentifier ?doiNode .
  ?doiNode coresr-ont:doiAsString ?doi .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?type
WHERE {
  ?publication coresr-ont:hasPublicationType ?ptype .
  ?ptype coresr-ont:typeAsString ?type .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?publication ?fieldOfStudy
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?city ?college
WHERE {
  ?college a coresr-ont:College ;
           coresr-ont:partOf ?university .

  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .

  ?location coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pub ?title
WHERE {
  {
    ?pub coresr-ont:submittedBy ?author .
    ?agent coresr-ont:performsRole ?author ;
           coresr-ont:associatedWith ?dept .
    OPTIONAL { ?pub coresr-ont:hasTitle ?title . }
  } UNION {
    ?contrib coresr-ont:contributedTo ?pub .
    ?agent coresr-ont:performsRole ?contrib ;
           coresr-ont:associatedWith ?dept .
    OPTIONAL { ?pub coresr-ont:hasTitle ?title . }
  }
}
GROUP BY ?pub ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?typeLabel (AVG(?duration) AS ?avgDuration)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate ;
       coresr-ont:hasPublicationType ?type .
  ?type coresr-ont:typeAsString ?typeLabel .
  BIND(?pubDate - ?subDate AS ?duration)
}
GROUP BY ?typeLabel
ORDER BY DESC(?avgDuration)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author ?advisor ?publication ?field
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
  ?publication coresr-ont:submittedBy ?author ;
               coresr-ont:associatedFieldOfStudy ?field .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?ci .
    ?ci a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)
LIMIT 1

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard 
       ?name 
       ?type 
       ?startDate 
       ?endDate 
       ?deaths 
       ?affectedArea 
       ?cropDamage 
       ?infraDamage
WHERE {
  ?hazard a kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName           ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType    ?type . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate      ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate        ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths   ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars      ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?name .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name ?percentBelowPovertyLine ?percentDiabetic ?percentObese
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?percentBelowPovertyLine . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?percentDiabetic . }
  OPTIONAL { ?place kwgl-ont:percentObese ?percentObese . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?placeName ?attribute ?value
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
  VALUES ?attribute {
    kwgl-ont:hasPopulation
    kwgl-ont:hasNumberOfHouseHolds
    kwgl-ont:percentBelowPovertyLine
    kwgl-ont:percentDiabetic
    kwgl-ont:percentObese
  }
  ?place ?attribute ?value .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?label (COUNT(?event) AS ?eventCount)
WHERE {
  ?hazard a kwgl-ont:HazardType ;
          rdfs:label ?label .
  FILTER regex(str(?hazard), "earthquake", "i")

  OPTIONAL { 
    ?event a kwgl-ont:HazardEvent ;
           kwgl-ont:hasHazardType ?hazard .
  }
}
GROUP BY ?hazard ?label

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?attribute (COUNT(DISTINCT ?place) AS ?placesWithAttribute)
WHERE {
  ?attribute a owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .
  FILTER(CONTAINS(STR(?attribute), "Tornado"))

  ?place a kwgl-ont:Place .
  OPTIONAL { ?place ?attribute ?value }
  FILTER(bound(?value))
}
GROUP BY ?attribute

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?place ?event ?hazardType
       ?eventName ?startDate ?endDate
       ?deaths ?affectedArea
       ?damageCrops ?damageInfra
WHERE {
  # Hazard events impacting places
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:impactedBy ?place ;
         kwgl-ont:hasHazardType ?hazardType .

  # Limit to storm‑related hazard types
  VALUES ?hazardType {
    kwglr:hurricane
    kwglr:tornado
    kwglr:stormSurgeTide
    kwglr:highWind
    kwglr:strongWind
    kwglr:thunderstormWind
    kwglr:marineHighWind
    kwglr:marineStrongWind
    kwglr:marineThunderstormWind
    kwglr:tropicalDepression
    kwglr:tropicalStorm
  }

  # Basic details (optional where available)
  OPTIONAL { ?event kwgl-ont:hasName ?eventName . }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate   ?endDate . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfra . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?place
                ?numFloods            ?damageFloods
                ?numFloods2018       ?damageFloods2018
                ?numFloods2019       ?damageFloods2019
                ?numFloods2020       ?damageFloods2020
                ?numFloods2021       ?damageFloods2021
                ?numFloods2022       ?damageFloods2022
WHERE {
  # Places that have been impacted by a flood hazard event
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType kwglr:flood ;
         kwgl-ont:hasImpacted ?place .

  # Flood‑specific attributes (overall)
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace        ?numFloods . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damageFloods . }

  # Year‑specific flood attributes
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2018   ?numFloods2018 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2018 ?damageFloods2018 . }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2019   ?numFloods2019 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2019 ?damageFloods2019 . }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2020   ?numFloods2020 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2020 ?damageFloods2020 . }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2021   ?numFloods2021 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2021 ?damageFloods2021 . }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2022   ?numFloods2022 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2022 ?damageFloods2022 . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?earthquake
                ?name
                ?startDate
                ?endDate
                ?affectedArea
                ?deaths
                ?damageCrops
                ?damageInfrastructure
                ?hazardTypeLabel
WHERE {
  ?earthquake a kwgl-ont:Earthquake .

  OPTIONAL { ?earthquake kwgl-ont:hasName ?name . }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }

  OPTIONAL {
    ?earthquake kwgl-ont:hasHazardType ?hazardType .
    ?hazardType rdfs:label ?hazardTypeLabel .
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event ?eventName ?hazardType ?damageCrops ?damageInfrastructure ?deaths ?affectedArea
WHERE {
  ?event a kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:hasName ?eventName . }
  OPTIONAL { ?event kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hurricane
       ?hName
       ?place
       ?pName
       ?startDate
       ?endDate
       ?affectedArea
       ?deaths
       ?damageCrops
       ?damageInfra
       ?dollarDamagePlace
       ?year
       ?dollarDamageYear
WHERE {
  # Hurricane events
  ?h a kwgl-ont:Hurricane ;
     kwgl-ont:hasHazardType kwglr:hurricane .

  BIND(?h AS ?hurricane)

  OPTIONAL { ?h kwgl-ont:hasName            ?hName . }
  OPTIONAL { ?h kwgl-ont:hasStartDate       ?startDate . }
  OPTIONAL { ?h kwgl-ont:hasEndDate         ?endDate . }
  OPTIONAL { ?h kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?h kwgl-ont:numberOfDeaths    ?deaths . }
  OPTIONAL { ?h kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?h kwgl-ont:damageToInfrastructureInDollars ?damageInfra . }

  # Places impacted by the hurricane
  OPTIONAL {
    ?h kwgl-ont:hasImpacted ?place .
    OPTIONAL { ?place kwgl-ont:hasName ?pName . }

    # Dollar damage of hurricanes impacting the place (overall)
    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamagePlace . }

    # Year‑specific dollar damage (if available)
    VALUES (?yearProp ?year) {
      (kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 "2018")
      (kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 "2019")
      (kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 "2020")
      (kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 "2021")
      (kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 "2022")
    }
    OPTIONAL { ?place ?yearProp ?dollarDamageYear . }
  }
}
ORDER BY ?hurricane ?place ?year

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazardEvent ?place ?startDate ?endDate
       ?damageToCrops ?damageToInfrastructure ?numberOfDeaths
WHERE {
  ?hazardEvent a               kwgl-ont:HazardEvent ;
                kwgl-ont:hasHazardType kwglr:tornado ;
                kwgl-ont:hasImpacted   ?place ;
                kwgl-ont:hasStartDate  ?startDate ;
                kwgl-ont:hasEndDate    ?endDate .

  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars       ?damageToCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths               ?numberOfDeaths . }
}
ORDER BY ?startDate

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazard ?hazardName ?place ?placeName ?damageToCrops ?damageToInfrastructure ?deaths
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?htype ;
          kwgl-ont:hasImpacted   ?place .

  OPTIONAL { ?hazard kwgl-ont:hasName               ?hazardName . }
  OPTIONAL { ?place  kwgl-ont:hasName               ?placeName  . }

  FILTER ( ?htype IN (kwglr:hurricane,
                      kwglr:tornado,
                      kwglr:stormSurgeTide,
                      kwglr:tropicalStorm,
                      kwglr:tropicalDepression) )

  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars       ?damageToCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths               ?deaths . }

  # Temporal filter (example – adjust dates as needed)
  OPTIONAL {
    ?hazard kwgl-ont:hasStartDate ?start ;
            kwgl-ont:hasEndDate   ?end .
    FILTER ( ?start >= "2020-01-01"^^xsd:date && ?end <= "2022-12-31"^^xsd:date )
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiString WHERE {
  ?publication a coresr-ont:Publication .
  OPTIONAL {
    ?publication coresr-ont:hasIdentifier ?doi .
    ?doi coresr-ont:doiAsString ?doiString .
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?university ?city
WHERE {
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .
  ?location coresr-ont:atState ?state .
  ?state   coresr-ont:inCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author ?advisor
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
  ?advisor a coresr-ont:Advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?title ?type
WHERE {
  ?publication a coresr-ont:Publication .
  OPTIONAL { ?publication coresr-ont:hasTitle ?title . }
  ?publication coresr-ont:hasPublicationType ?ptype .
  ?ptype coresr-ont:typeAsString ?type .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?agent ?department
WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?fieldOfStudy ?fieldLabel ?publication ?pubTitle
WHERE {
  ?publication a coresr-ont:Publication .
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .

  OPTIONAL { ?fieldOfStudy rdfs:label ?fieldLabel . }
  OPTIONAL { ?publication coresr-ont:hasTitle ?pubTitle . }
}
ORDER BY ?fieldOfStudy ?publication

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?cityName ?collegeName
WHERE {
  ?univ a coresr-ont:University ;
        coresr-ont:locatedAt ?loc .
  ?loc coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .

  ?college a coresr-ont:College ;
           coresr-ont:partOf ?univ .

  OPTIONAL { ?city coresr-ont:nameAsString ?cityName . }
  OPTIONAL { ?college coresr-ont:nameAsString ?collegeName . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pub ?title
WHERE {
  ?pub a coresr-ont:Publication .
  OPTIONAL { ?pub coresr-ont:hasTitle ?title . }

  # agents that are authors of the publication
  { 
    ?pub coresr-ont:submittedBy ?authorRole .
    ?authorRole a coresr-ont:Author .
    ?agent coresr-ont:performsRole ?authorRole .
  }
  UNION
  # agents that are contributors to the publication
  {
    ?pub coresr-ont:hasContributor ?contribRole .
    ?contribRole a coresr-ont:Contributor .
    ?agent coresr-ont:performsRole ?contribRole .
  }

  # departments associated with those agents
  ?agent coresr-ont:associatedWith ?dept .
}
GROUP BY ?pub ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?type (AVG(?days) AS ?avgDays)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate ;
       coresr-ont:hasPublicationType ?ptype .
  ?ptype coresr-ont:typeAsString ?type .

  BIND( (xsd:dateTime(?pubDate) - xsd:dateTime(?subDate)) AS ?duration )
  # convert the day‑time duration to a number of days
  BIND( (?duration / "P1D"^^xsd:dayTimeDuration) AS ?days )
}
GROUP BY ?type
ORDER BY DESC(?avgDays)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department (COUNT(DISTINCT ?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?ci .
    ?ci a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)
LIMIT 1

