SELECT DISTINCT ?college ?city
WHERE {
  ?college a coresr-ont:College ;
           coresr-ont:partOf ?univ .
  ?univ a coresr-ont:University ;
        coresr-ont:locatedAt ?loc .
  ?loc coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pub ?title
WHERE {
  ?pub a coresr-ont:Publication .
  OPTIONAL { ?pub coresr-ont:hasTitle ?title . }

  # Authors submitted by the publication
  {
    ?pub coresr-ont:submittedBy ?author .
    ?author a coresr-ont:Author .
    ?agent coresr-ont:performsRole ?author .
  }
  UNION
  # Contributors to the publication
  {
    ?contributor coresr-ont:contributedTo ?pub .
    ?contributor a coresr-ont:Contributor .
    ?agent coresr-ont:performsRole ?contributor .
  }

  ?agent coresr-ont:associatedWith ?dept .
}
GROUP BY ?pub ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?typeString (AVG(?days) AS ?avgDays)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate ;
       coresr-ont:hasPublicationType ?ptype .
  ?ptype coresr-ont:typeAsString ?typeString .
  BIND( (xsd:dateTime(?pubDate) - xsd:dateTime(?subDate)) AS ?duration )
  BIND( (?duration / xsd:dayTimeDuration("P1D")) AS ?days )
}
GROUP BY ?typeString
ORDER BY DESC(?avgDays)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author ?fieldOfStudy
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
  ?advisor a coresr-ont:Advisor .

  ?pub a coresr-ont:Publication ;
       coresr-ont:submittedBy ?author ;
       coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department ?missingFamilyNameCount WHERE {
  # Count agents per department that lack a FamilyName contact information
  {
    SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
    WHERE {
      ?agent a coresr-ont:Agent .
      ?agent coresr-ont:associatedWith ?department .
      FILTER NOT EXISTS {
        ?agent coresr-ont:hasContactInformation ?famInfo .
        ?famInfo a coresr-ont:FamilyName .
      }
    } GROUP BY ?department
  }

  # Determine the maximal count across all departments
  {
    SELECT (MAX(?cnt) AS ?maxCnt)
    WHERE {
      SELECT ?dept (COUNT(?ag) AS ?cnt)
      WHERE {
        ?ag a coresr-ont:Agent .
        ?ag coresr-ont:associatedWith ?dept .
        FILTER NOT EXISTS {
          ?ag coresr-ont:hasContactInformation ?fi .
          ?fi a coresr-ont:FamilyName .
        }
      } GROUP BY ?dept
    }
  }

  # Keep only departments with the maximal count
  FILTER ( ?missingFamilyNameCount = ?maxCnt )
}
ORDER BY DESC(?missingFamilyNameCount)

