PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?attribute ?totalCount WHERE {
  # list all tornado‑specific datatype properties
  { SELECT DISTINCT ?attribute WHERE {
        ?attribute a owl:DatatypeProperty .
        FILTER(CONTAINS(LCASE(STR(?attribute)), "tornado"))
    }
  }
  # compute the total number of such attributes
  { SELECT (COUNT(DISTINCT ?a) AS ?totalCount) WHERE {
        ?a a owl:DatatypeProperty .
        FILTER(CONTAINS(LCASE(STR(?a)), "tornado"))
    }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?place ?placeName ?event ?hazardType ?eventName ?startDate ?endDate ?affectedArea
WHERE {
  # all places
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }

  # hazard events impacting the place
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasImpacted ?place ;
         kwgl-ont:hasHazardType ?hazardType .

  # keep only storm‑related hazard types
  FILTER regex(str(?hazardType), "storm", "i") .

  OPTIONAL { ?event kwgl-ont:hasName       ?eventName . }
  OPTIONAL { ?event kwgl-ont:hasStartDate  ?startDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate    ?endDate . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?place ?placeName
       ?event ?eventName
       ?startDate ?endDate
       ?affectedAreaInAcres
       ?damageToCropsInDollars
       ?damageToInfrastructureInDollars
       ?numberOfDeaths
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType kwglr:flood ;
         kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
  OPTIONAL { ?event kwgl-ont:hasName ?eventName . }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths . }
}
ORDER BY ?place ?event

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?earthquake ?name ?startDate ?endDate ?affectedArea ?damageCrops ?damageInfrastructure ?deaths ?hazardType
WHERE {
