PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?event ?name ?affectedArea ?cropDamage ?infraDamage ?deaths
WHERE {
  ?event rdf:type ?type .
  ?type rdfs:subClassOf* kwgl-ont:HazardEvent .

  OPTIONAL { ?event kwgl-ont:hasName ?name . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazardEvent ?damageCrops ?damageInfrastructure
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  FILTER (BOUND(?damageCrops) || BOUND(?damageInfrastructure))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hurricane
       ?place
       ?startDate
       ?endDate
       ?affectedArea
       ?damageCrops
       ?damageInfrastructure
       ?deaths
       ?dollarDamagePlace
       ?numHurricanesPlace
WHERE {
  ?hurricane a kwgl-ont:Hurricane .

  OPTIONAL { ?hurricane kwgl-ont:hasStartDate            ?startDate . }
  OPTIONAL { ?hurricane kwgl-ont:hasEndDate              ?endDate . }
  OPTIONAL { ?hurricane kwgl-ont:affectedAreaInAcres     ?affectedArea . }
  OPTIONAL { ?hurricane kwgl-ont:damageToCropsInDollars   ?damageCrops . }
  OPTIONAL { ?hurricane kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  OPTIONAL { ?hurricane kwgl-ont:numberOfDeaths          ?deaths . }

  OPTIONAL {
    ?hurricane kwgl-ont:hasImpacted ?place .
    FILTER EXISTS { ?place a kwgl-ont:Place }

    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamagePlace . }
    OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace      ?numHurricanesPlace . }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazard ?place ?damageCrops ?damageInfrastructure ?startDate ?endDate
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType kwglr:tornado ;
          kwgl-ont:hasImpacted ?place ;
          kwgl-ont:hasStartDate ?startDate .

  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
}
ORDER BY ?startDate

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?hazardType ?place ?damageToCrops ?damageToInfrastructure ?startDate ?endDate
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?hazardType ;
          kwgl-ont:hasImpacted ?place ;
          kwgl-ont:hasStartDate ?startDate ;
          kwgl-ont:hasEndDate   ?endDate .

  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars       ?damageToCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }

  # Storm‑specific hazard types
  VALUES ?hazardType {
    kwglr:hurricane
    kwglr:tornado
    kwglr:stormSurgeTide
    kwglr:highWind
    kwglr:strongWind
    kwglr:thunderstormWind
    kwglr:tropicalStorm
    kwglr:tropicalDepression
  }

  # Temporal extent filter (example: year 2020)
  FILTER( ?startDate >= "2020-01-01"^^xsd:date && ?endDate <= "2020-12-31"^^xsd:date )
}

