PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?university ?pubCount WHERE {
  # Count publications per university
  {
    SELECT ?university ?state (COUNT(?pub) AS ?pubCount) WHERE {
      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author a coress-ont:Author .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?dept .
      ?dept coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?university ?state
  }
  # Determine the maximum publication count per state
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt) WHERE {
      SELECT ?state (COUNT(?pub2) AS ?cnt) WHERE {
        ?pub2 a coress-ont:Publication .
        ?pub2 coress-ont:submittedBy ?author2 .
        ?author2 a coress-ont:Author .
        ?author2 coress-ont:isPerformedBy ?agent2 .
        ?agent2 coress-ont:worksInDepartment ?dept2 .
        ?dept2 coress-ont:departmentOf ?college2 .
        ?college2 coress-ont:collegeOf ?university2 .
        ?university2 coress-ont:atState ?state .
      }
      GROUP BY ?state
    }
  }
  FILTER(?pubCount = ?maxCnt)
}
ORDER BY ?state

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?pubType (AVG(?duration) AS ?avgDuration)
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:hasPublicationType ?pubType ;
       coress-ont:dateOfSubmission ?subDate ;
       coress-ont:dateOfPublication ?pubDate .
  BIND ( (?pubDate - ?subDate) AS ?duration )
}
GROUP BY ?pubType
ORDER BY DESC(?avgDuration)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?author ?firstName ?familyName ?advisor ?field
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor .

  OPTIONAL { ?author coress-ont:hasFirstName ?firstName . }
  OPTIONAL { ?author coress-ont:hasFamilyName ?familyName . }

  ?pub a coress-ont:Publication ;
       coress-ont:submittedBy ?author ;
       coress-ont:associatedFieldOfStudy ?field .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department ?missingCount WHERE {
  # Count agents without a family name per department
  {
    SELECT ?department (COUNT(?agent) AS ?missingCount) WHERE {
      ?agent a coress-ont:Agent ;
             coress-ont:worksInDepartment ?department .
      FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
    } GROUP BY ?department
  }

  # Determine the maximum missing‑family‑name count across all departments
  {
    SELECT (MAX(?cnt) AS ?maxCount) WHERE {
      SELECT (COUNT(?a) AS ?cnt) WHERE {
        ?a a coress-ont:Agent ;
           coress-ont:worksInDepartment ?d .
        FILTER NOT EXISTS { ?a coress-ont:hasFamilyName ?fn2 }
      } GROUP BY ?d
    }
  }

  # Keep only departments that achieve the maximum count
  FILTER(?missingCount = ?maxCount)
}
ORDER BY DESC(?missingCount)

