  ?author coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?type
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?type .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?agent ?firstName ?familyName ?department
WHERE {
  ?agent a coress-ont:Agent .
  OPTIONAL { ?agent coress-ont:hasFirstName ?firstName . }
  OPTIONAL { ?agent coress-ont:hasFamilyName ?familyName . }
  ?agent coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT DISTINCT ?field ?publication
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:associatedFieldOfStudy ?field .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT DISTINCT ?city ?college
WHERE {
  ?university a coress-ont:University ;
              coress-ont:atCity ?city .
  ?college a coress-ont:College ;
           coress-ont:collegeOf ?university .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?state ?university (COUNT(DISTINCT ?pub) AS ?publicationCount)
WHERE {
  # Count publications per university
  {
    SELECT ?state ?university (COUNT(DISTINCT ?pub) AS ?cnt)
    WHERE {
      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?dept .
      ?dept coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  # Determine the maximum count per state
  {
    SELECT ?state (MAX(?c) AS ?maxCnt)
    WHERE {
      {
        SELECT ?state ?university (COUNT(DISTINCT ?pub) AS ?c)
        WHERE {
          ?pub a coress-ont:Publication .
          ?pub coress-ont:submittedBy ?author .
          ?author coress-ont:isPerformedBy ?agent .
          ?agent coress-ont:worksInDepartment ?dept .
          ?dept coress-ont:departmentOf ?college .
          ?college coress-ont:collegeOf ?university .
          ?university coress-ont:atState ?state .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  FILTER(?cnt = ?maxCnt)
  BIND(?cnt AS ?publicationCount)
}
GROUP BY ?state ?university ?publicationCount
ORDER BY ?state

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publicationType (AVG(?duration) AS ?averageTime)
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:hasPublicationType ?publicationType ;
       coress-ont:dateOfSubmission ?submissionDate ;
       coress-ont:dateOfPublication ?publicationDate .
  BIND (?publicationDate - ?submissionDate AS ?duration)
}
GROUP BY ?publicationType
ORDER BY DESC(?averageTime)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coress-ont:Agent .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
  ?agent coress-ont:worksInDepartment ?department .
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)
LIMIT 1

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazard
                (GROUP_CONCAT(DISTINCT ?type; SEPARATOR=", ") AS ?hazardType)
                ?label
                ?geom
                ?begin
                ?end
WHERE {
  # any instance that is a Hazard (or subclass thereof)
  ?hazard rdf:type kwg-ont:Hazard .

  # capture more specific type(s) if present
  OPTIONAL { 
    ?hazard rdf:type ?type .
    FILTER(?type != kwg-ont:Hazard)
  }

  # optional human‑readable label
  OPTIONAL { ?hazard rdfs:label ?label . }

  # optional geometry information
  OPTIONAL { ?hazard geo:hasGeometry ?geom . }

  # temporal scope of the hazard
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?temp .

    # if the temporal entity is an interval with explicit beginning/end
    OPTIONAL {
      ?temp time:hasBeginning ?bInst .
      OPTIONAL { ?bInst time:inXSDDateTime ?begin . }
      OPTIONAL { ?bInst time:inXSDDate ?begin . }
    }
    OPTIONAL {
      ?temp time:hasEnd ?eInst .
      OPTIONAL { ?eInst time:inXSDDateTime ?end . }
      OPTIONAL { ?eInst time:inXSDDate ?end . }
    }

    # if the temporal entity is itself an instant
    FILTER NOT EXISTS { ?temp time:hasBeginning [] }
    OPTIONAL {
      ?temp time:inXSDDateTime ?begin .
    }
    OPTIONAL {
      ?temp time:inXSDDate ?begin .
    }
  }
}
GROUP BY ?hazard ?label ?geom ?begin ?end
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place rdfs:label ?name . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?place ?healthAttribute
WHERE {
  # Public health observations
  ?obs a kwg-ont:PublicHealthObservation ;
       sosa:observedProperty ?healthAttribute .

  # Ensure the observed property is a health‑related observable property
  ?healthAttribute rdfs:subClassOf kwg-ont:PublicHealthObservableProperty .

  # Link observations to their collection and the place (geographical feature)
  ?collection a kwg-ont:PublicHealthObservationCollection ;
              sosa:hasMember ?obs ;
              sosa:hasFeatureOfInterest ?place .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?attribute
WHERE {
  ?obs a kwg-ont:CensusACS5YearEstimatesObservation ;
       sosa:observedProperty ?attribute ;
       sosa:hasFeatureOfInterest ?place .

  ?attribute rdfs:subClassOf kwg-ont:CensusObservableProperty .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?earthquake ?totalCount WHERE {
  { SELECT (COUNT(DISTINCT ?e) AS ?totalCount)
    WHERE { ?e a kwg-ont:Earthquake }
  }
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?attribute ?totalCount WHERE {
  # List each distinct tornado‑specific hazard attribute
  {
    SELECT DISTINCT ?attribute WHERE {
      ?obs a kwg-ont:MagnitudeObservation ;
           sosa:observedProperty ?attribute ;
           sosa:hasFeatureOfInterest ?hazard .
      ?hazard a kwg-ont:NOAATornado .
    }
  }
  # Compute the overall number of distinct attributes
  {
    SELECT (COUNT(DISTINCT ?attr) AS ?totalCount) WHERE {
      ?o a kwg-ont:MagnitudeObservation ;
         sosa:observedProperty ?attr ;
         sosa:hasFeatureOfInterest ?h .
      ?h a kwg-ont:NOAATornado .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?attribute ?label
WHERE {
  { 
    ?obs a kwg-ont:StormTrackObservation ;
         sosa:observedProperty ?attribute ;
         sosa:hasFeatureOfInterest ?track .
  }
  UNION
  {
    ?obs a kwg-ont:StormTrackletObservation ;
         sosa:observedProperty ?attribute ;
         sosa:hasFeatureOfInterest ?track .
  }
  ?track a kwg-ont:StormTrack .
  BIND(?track AS ?place)
  OPTIONAL { ?attribute rdfs:label ?label . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?earthquake ?geom ?defaultGeom ?temporalScope
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  OPTIONAL { ?earthquake geo:hasGeometry ?geom . }
  OPTIONAL { ?earthquake geo:hasDefaultGeometry ?defaultGeom . }
  OPTIONAL { ?earthquake kwg-ont:hasTemporalScope ?temporalScope . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazardEvent ?impactProperty ?value
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazardEvent ;
       sosa:observedProperty   ?impactProperty ;
       sosa:hasSimpleResult    ?value .
  ?hazardEvent a kwg-ont:Hazard .  # ensures the feature of interest is a hazard event
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?damageDetail WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?damageDetail ;
       sosa:hasFeatureOfInterest ?hazard .
  ?hazard a kwg-ont:Hazard .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?place ?attribute ?attrTime ?impactDetail ?impactTime
WHERE {
  # Hurricane events and their related places
  ?hazard a kwg-ont:NOAAHurricane ;
          kwg-ont:spatialRelation ?place .

  # Hazard‑specific attributes (observed properties) linked to the hurricane
  OPTIONAL {
    ?attrObs sosa:hasFeatureOfInterest ?hazard ;
             sosa:observedProperty ?attribute .
    OPTIONAL { ?attrObs sosa:phenomenonTime ?attrTime . }
  }

  # Damage impact details and their temporal information
  OPTIONAL {
    ?impactObs a kwg-ont:ImpactObservation ;
               sosa:hasFeatureOfInterest ?hazard ;
               sosa:observedProperty ?impactDetail .
    OPTIONAL { ?impactObs sosa:phenomenonTime ?impactTime . }
  }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?place ?impactProp ?damageValue ?start ?end
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?impactProp ;
       sosa:hasSimpleResult ?damageValue ;
       sosa:hasFeatureOfInterest ?hazard .

  ?hazard a kwg-ont:NOAATornado ;
          kwg-ont:spatialRelation ?place ;
          kwg-ont:hasTemporalScope ?temp .

  OPTIONAL { ?temp time:hasBeginning ?start . }
  OPTIONAL { ?temp time:hasEnd ?end . }

  FILTER(?impactProp IN (
    kwgr:impactObservableProperty.damageCrop,
    kwgr:impactObservableProperty.damageProperty,
    kwgr:impactObservableProperty.deathDirect,
    kwgr:impactObservableProperty.deathIndirect,
    kwgr:impactObservableProperty.injuryDirect,
    kwgr:impactObservableProperty.injuryIndirect
  ))
}

