PREFIX co: <http://example.org/core_scholar_shallow/>

SELECT ?state ?university ?pubCount
WHERE {
  # Count publications per university per state
  {
    SELECT ?state ?university (COUNT(?pub) AS ?pubCount)
    WHERE {
      ?pub a co:Publication .
      ?pub co:submittedBy ?author .
      ?author co:isPerformedBy ?agent .
      ?agent co:worksInDepartment ?dept .
      ?dept co:departmentOf ?college .
      ?college co:collegeOf ?university .
      ?university co:atState ?state .
    }
    GROUP BY ?state ?university
  }
  # Determine the maximum count per state
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt)
    WHERE {
      SELECT ?state ?university (COUNT(?pub) AS ?cnt)
      WHERE {
        ?pub a co:Publication .
        ?pub co:submittedBy ?author .
        ?author co:isPerformedBy ?agent .
        ?agent co:worksInDepartment ?dept .
        ?dept co:departmentOf ?college .
        ?college co:collegeOf ?university .
        ?university co:atState ?state .
      }
      GROUP BY ?state ?university
    }
    GROUP BY ?state
  }
  FILTER(?pubCount = ?maxCnt)
}
ORDER BY ?state

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?pubType (AVG(?days) AS ?avgDays)
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:hasPublicationType ?pubType ;
       coress-ont:dateOfSubmission ?subDate ;
       coress-ont:dateOfPublication ?pubDate .
  BIND (xsd:dateTime(?subDate) AS ?subDT)
  BIND (xsd:dateTime(?pubDate) AS ?pubDT)
  BIND ((?pubDT - ?subDT) / xsd:dayTimeDuration("P1D") AS ?days)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDays)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?author ?advisor ?field
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor ;
          coress-ont:submits ?pub .
  ?pub   coress-ont:associatedFieldOfStudy ?field .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?dept ?missingCount WHERE {
  # Count missing family names per department
  {
    SELECT ?dept (COUNT(?agent) AS ?missingCount) WHERE {
      ?dept a coress-ont:Department .
      ?dept coress-ont:hasAgent ?agent .
      FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
    } GROUP BY ?dept
  }
  # Retrieve the maximum count across all departments
  {
    SELECT (MAX(?cnt) AS ?maxCount) WHERE {
      SELECT (COUNT(?a) AS ?cnt) WHERE {
        ?d a coress-ont:Department .
        ?d coress-ont:hasAgent ?a .
        FILTER NOT EXISTS { ?a coress-ont:hasFamilyName ?fn2 }
      } GROUP BY ?d
    }
  }
  FILTER(?missingCount = ?maxCount)
} ORDER BY DESC(?missingCount)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazard
  ?name
  ?type
  ?startDate
  ?endDate
  ?affectedArea
  ?damageCrops
  ?damageInfrastructure
  ?deaths
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
}
ORDER BY ?startDate

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
