PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute
WHERE {
  ?attribute a owl:DatatypeProperty .
  ?place a kwgl-ont:Place ;
         ?attribute ?value .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazard ?totalCount WHERE {
  # Sub‑query to compute the total number of distinct earthquake hazard types
  {
    SELECT (COUNT(DISTINCT ?h) AS ?totalCount) WHERE {
      ?h rdf:type kwgl-ont:HazardType .
      FILTER(CONTAINS(LCASE(STR(?h)), "earthquake"))
    }
  }

  # Retrieve each individual earthquake hazard type
  OPTIONAL {
    ?hazard rdf:type kwgl-ont:HazardType .
    FILTER(CONTAINS(LCASE(STR(?hazard)), "earthquake"))
  }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?totalCount
WHERE {
  {
    SELECT (COUNT(DISTINCT ?a) AS ?totalCount)
    WHERE {
      ?a rdf:type owl:DatatypeProperty .
      ?place a kwgl-ont:Place ;
             ?a ?val .
      FILTER(CONTAINS(LCASE(STR(?a)), "tornado"))
    }
  }
  ?attribute rdf:type owl:DatatypeProperty .
  ?place a kwgl-ont:Place ;
          ?attribute ?value .
  FILTER(CONTAINS(LCASE(STR(?attribute)), "tornado"))
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  OPTIONAL { ?attribute rdfs:range ?range . }
  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?range
  ?parentAttribute
  ?parentRange
WHERE {
  ?attribute a owl:DatatypeProperty .
  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  FILTER (CONTAINS(LCASE(STR(?attribute)), "flood"))
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:range ?parentRange . }
  }
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazardEvent ?hazardName ?startDate ?endDate
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType kwglr:earthquake .
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate   ?endDate . }
}
ORDER BY ?hazardEvent

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?event ?property ?value
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .
  VALUES ?property { 
    kwgl-ont:affectedAreaInAcres 
    kwgl-ont:damageToCropsInDollars 
    kwgl-ont:damageToInfrastructureInDollars 
    kwgl-ont:numberOfDeaths
  }
  ?event ?property ?value .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?hazardEvent
  ?place
  ?startDate
  ?endDate
  ?damageToCrops
  ?damageToInfrastructure
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType kwglr:tornado ;
               kwgl-ont:hasImpacted ?place ;
               kwgl-ont:hasStartDate ?startDate .

  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
}
ORDER BY ?startDate

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?title ?typeString
WHERE {
  ?publication a coresr-ont:Publication .
  OPTIONAL { ?publication coresr-ont:hasTitle ?title . }
  ?publication coresr-ont:hasPublicationType ?pubType .
  ?pubType coresr-ont:typeAsString ?typeString .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?fieldOfStudy ?publication ?title
WHERE {
  ?publication a coresr-ont:Publication .
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
  OPTIONAL { ?publication coresr-ont:hasTitle ?title . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?city ?college
WHERE {
  ?college a coresr-ont:College ;
           coresr-ont:partOf ?university .
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .
  ?location coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?state ?university (COUNT(DISTINCT ?pub) AS ?pubCount)
WHERE {
  # Count publications per university per state
  {
    SELECT ?state ?university (COUNT(DISTINCT ?pub) AS ?cnt) WHERE {
      ?pub a coresr-ont:Publication .
      ?pub coresr-ont:submittedBy ?authorRole .
      ?agent coresr-ont:performsRole ?authorRole .
      ?agent coresr-ont:associatedWith ?dept .
      ?dept coresr-ont:partOf ?college .
      ?college coresr-ont:partOf ?university .
      ?university a coresr-ont:University .
      ?university coresr-ont:locatedAt ?loc .
      ?loc coresr-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  # Determine the maximum count per state
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt) WHERE {
      SELECT ?state (COUNT(DISTINCT ?pub2) AS ?cnt) WHERE {
        ?pub2 a coresr-ont:Publication .
        ?pub2 coresr-ont:submittedBy ?authorRole2 .
        ?agent2 coresr-ont:performsRole ?authorRole2 .
        ?agent2 coresr-ont:associatedWith ?dept2 .
        ?dept2 coresr-ont:partOf ?college2 .
        ?college2 coresr-ont:partOf ?university2 .
        ?university2 a coresr-ont:University .
        ?university2 coresr-ont:locatedAt ?loc2 .
        ?loc2 coresr-ont:atState ?state .
      }
      GROUP BY ?state
    }
    GROUP BY ?state
  }
  FILTER(?cnt = ?maxCnt)
}
GROUP BY ?state ?university ?pubCount
ORDER BY ?state ?university

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pub ?title WHERE {
  ?pub a coresr-ont:Publication .
  OPTIONAL { ?pub coresr-ont:hasTitle ?title . }

  {
    # Authors
    ?pub coresr-ont:submittedBy ?author .
    ?author a coresr-ont:Author .
    ?agent coresr-ont:performsRole ?author ;
           coresr-ont:associatedWith ?dept .
  } UNION {
    # Contributors
    ?contrib coresr-ont:contributedTo ?pub .
    ?contrib a coresr-ont:Contributor .
    ?agent coresr-ont:performsRole ?contrib ;
           coresr-ont:associatedWith ?dept .
  }

  FILTER EXISTS { ?dept a coresr-ont:Department . }
}
GROUP BY ?pub ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?typeString (AVG(?duration) AS ?avgDuration)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate ;
       coresr-ont:hasPublicationType ?ptype .

  ?ptype coresr-ont:typeAsString ?typeString .

  BIND ( xsd:dateTime(?pubDate) - xsd:dateTime(?subDate) AS ?duration )
}
GROUP BY ?typeString
ORDER BY DESC(?avgDuration)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author ?field
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .

  ?pub a coresr-ont:Publication ;
       coresr-ont:submittedBy ?author ;
       coresr-ont:associatedFieldOfStudy ?field .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?ci .
    ?ci a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)
LIMIT 1

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?hazardType ?time ?detailProp ?detailVal
WHERE {
  # all hazard instances
  ?hazard a kwg-ont:Hazard .

  # concrete type (sub‑class of Hazard)
  OPTIONAL { 
    ?hazard rdf:type ?hazardType .
    FILTER(?hazardType != kwg-ont:Hazard) 
  }

  # when it happened
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time . }

  # any additional details (excluding type and temporal scope)
  OPTIONAL {
    ?hazard ?detailProp ?detailVal .
    FILTER(?detailProp NOT IN (rdf:type, kwg-ont:hasTemporalScope))
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place rdfs:label        ?name . }
  OPTIONAL { ?place kwg-ont:hasName   ?name . }
  FILTER (BOUND(?name))
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?healthAttribute
WHERE {
  # observations that capture health‑related information
  VALUES ?obsClass { 
      kwg-ont:PublicHealthObservation 
      kwg-ont:ImpactObservation 
      kwg-ont:VulnerabilityObservation 
  }

  ?obs a ?obsClass ;
       sosa:observedProperty ?healthAttribute ;
       sosa:hasFeatureOfInterest ?place .

  # restrict the feature of interest to geographical places
  ?place a geo:Feature .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?earthquake
       ?temporalScope
       ?geometry
       ?defaultGeometry
       ?s2Cell
       ?adminRegion
WHERE {
  # Earthquake hazards
  ?earthquake a kwg-ont:Earthquake .

  # Temporal scope (instant)
  OPTIONAL { ?earthquake kwg-ont:hasTemporalScope ?temporalScope . }

  # Geometry information
  OPTIONAL { ?earthquake kwg-ont:hasGeometry        ?geometry       . }
  OPTIONAL { ?earthquake geo:hasDefaultGeometry    ?defaultGeometry. }

  # Spatial relations – S2 cell and administrative region
  OPTIONAL {
    ?earthquake kwg-ont:sfWithin ?s2Cell .
    FILTER EXISTS { ?s2Cell a kwg-ont:S2Cell }
  }
  OPTIONAL {
    ?earthquake kwg-ont:sfWithin ?adminRegion .
    FILTER EXISTS { ?adminRegion a kwg-ont:AdministrativeRegion_3 }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardEvent ?impactProperty ?impactValue
WHERE {
  # Hazard events (NOAA hazard events)
  ?hazardEvent a kwg-ont:NOAAHazardEvent .

  # Impact observations linked to the hazard event
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazardEvent ;
       sosa:observedProperty ?impactProperty ;
       sosa:hasSimpleResult   ?impactValue .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?damageDetail WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?damageDetail ;
       sosa:hasFeatureOfInterest ?hazard .

  ?hazard a kwg-ont:Hazard .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT
       ?hurricane
       ?geom
       ?tempScope
       ?impactProp
       ?impactValue
       ?impactTime
WHERE {
  # Hurricane events (NOAA hurricane hazard)
  ?hurricane a kwg-ont:NOAAHurricane .

  # Geometry / spatial attributes related to the place
  OPTIONAL { ?hurricane kwg-ont:hasGeometry ?geom . }
  OPTIONAL { ?hurricane geo:hasDefaultGeometry ?geom . }

  # Temporal scope of the hurricane event (if present)
  OPTIONAL { ?hurricane kwg-ont:hasTemporalScope ?tempScope . }

  # Damage impact observations linked to this hurricane
  ?impactCol a kwg-ont:ImpactObservationCollection ;
             sosa:hasFeatureOfInterest ?hurricane ;
             sosa:hasMember ?impactObs .

  ?impactObs a kwg-ont:ImpactObservation ;
            sosa:observedProperty ?impactProp ;
            sosa:hasSimpleResult   ?impactValue .

  # Temporal information of the impact observation (if available)
  OPTIONAL { ?impactObs sosa:phenomenonTime ?impactTime . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?damageDetail ?hazard ?place ?timeEntity
WHERE {
  # Impact observations that record damage details
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasSimpleResult ?damageDetail ;
       sosa:hasFeatureOfInterest ?hazard .

  # The hazard must be a tornado event
  ?hazard a kwg-ont:NOAATornado ;
          kwg-ont:spatialRelation ?place .

  # Optional temporal scope of the tornado hazard
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?timeEntity . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?place ?time ?damageProp ?damageValue
WHERE {
  # impact (damage) observations
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?damageProp ;
       sosa:hasSimpleResult   ?damageValue ;
       sosa:hasFeatureOfInterest ?hazard .

  # hazard must be a storm‑related NOAA hazard event
  VALUES ?stormHazard {
    kwg-ont:NOAAHurricane
    kwg-ont:NOAATornado
    kwg-ont:NOAAStormSurgeTide
    kwg-ont:NOAAFlashFlood
    kwg-ont:NOAAHeavyRain
    kwg-ont:NOAAHighWind
    kwg-ont:NOAAWinterStorm
  }
  ?hazard a ?stormHazard .

  # temporal extent of the hazard
  ?hazard kwg-ont:hasTemporalScope ?time .

  # geographic place related to the hazard (spatial relation)
  OPTIONAL { ?hazard kwg-ont:spatialRelation ?place . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?type ?label ?temporalScope ?beginning ?end
WHERE {
  ?hazard a kwg-ont:Hazard .

  # Specific hazard type (exclude the generic class)
  OPTIONAL {
    ?hazard a ?type .
    FILTER(?type != kwg-ont:Hazard)
  }

  # Human‑readable label, if present
  OPTIONAL { ?hazard rdfs:label ?label . }

  # Temporal information
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?temporalScope .
    OPTIONAL { ?temporalScope time:hasBeginning ?beginning . }
    OPTIONAL { ?temporalScope time:hasEnd       ?end . }
  }
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?place ?name WHERE {
  ?place a ?type .
  ?type rdfs:subClassOf* geo:Feature .
  ?place geo:hasGeometry ?geom .
  { ?place rdfs:label ?name }
  UNION
  { ?place kwg-ont:hospitalName ?name }
  UNION
  { ?place kwg-ont:siteName ?name }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?healthAttr
WHERE {
  ?obs a kwg-ont:PublicHealthObservation ;
       sosa:observedProperty ?healthAttr ;
       sosa:hasFeatureOfInterest ?place .
  ?healthAttr rdfs:subClassOf kwg-ont:PublicHealthObservableProperty .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?attribute
WHERE {
  # Census observations that report demographic values
  ?obs a kwg-ont:CensusACS5YearEstimatesObservation ;
       sosa:observedProperty ?attribute ;
       sosa:hasFeatureOfInterest ?place .

  # Attribute must be a (sub)class of the census observable property hierarchy
  ?attribute rdfs:subClassOf* kwg-ont:CensusObservableProperty .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?earthquake ?total WHERE {
  { SELECT (COUNT(DISTINCT ?e) AS ?total)
    WHERE { ?e a kwg-ont:Earthquake . }
  }
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?attribute ?totalCount WHERE {
  ?t a kwg-ont:NOAATornado ;
     ?attribute ?value .
  FILTER(?attribute != rdf:type)

  {
    SELECT (COUNT(DISTINCT ?attr) AS ?totalCount) WHERE {
      ?t2 a kwg-ont:NOAATornado ;
          ?attr ?val .
      FILTER(?attr != rdf:type)
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?stormFeature ?property ?label ?geometry
WHERE {
  # Storm track observation collection linked to a storm feature (geographical place)
  ?obsColl a kwg-ont:StormTrackObservationCollection ;
           sosa:hasFeatureOfInterest ?stormFeature ;
           sosa:hasMember ?observation .

  # The observed property represents a storm‑specific hazard attribute
  ?observation sosa:observedProperty ?property .

  OPTIONAL { ?property rdfs:label ?label . }
  OPTIONAL { ?stormFeature geo:hasGeometry ?geometry . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?climateAttribute WHERE {
  ?climateAttribute rdfs:subClassOf kwg-ont:ClimateObservableProperty .
  ?collection a kwg-ont:ClimateDivisionPropertyObservationCollection ;
              sosa:observedProperty ?climateAttribute ;
              sosa:hasMember ?obs .
  ?obs a kwg-ont:ClimateObservation ;
       sosa:hasFeatureOfInterest ?place .
  ?place a geo:Feature .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earthquake ?typeLabel ?geometry ?defaultGeometry ?temporalScope
WHERE {
  ?earthquake a kwg-ont:Earthquake .

  OPTIONAL { ?earthquake rdfs:label ?typeLabel . }
  OPTIONAL { ?earthquake geo:hasGeometry ?geometry . }
  OPTIONAL { ?earthquake geo:hasDefaultGeometry ?defaultGeometry . }
  OPTIONAL { ?earthquake kwg-ont:hasTemporalScope ?temporalScope . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazardEvent ?impactProperty ?value
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazardEvent ;
       sosa:observedProperty    ?impactProperty ;
       sosa:hasSimpleResult     ?value .

  ?hazardEvent a kwg-ont:NOAAHazardEvent .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?damageDetail
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?damageDetail ;
       sosa:hasFeatureOfInterest ?hazard .

  ?hazard a kwg-ont:Hazard .

  # Ensure the property is an impact observable (optional but clarifies intent)
  FILTER EXISTS { ?damageDetail rdfs:subClassOf kwg-ont:ImpactObservableProperty }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricane ?place ?property ?value ?time
WHERE {
  # Hurricane events
  ?hurricane a kwg-ont:NOAAHurricane .
  OPTIONAL { ?hurricane kwg-ont:spatialRelation ?place . }

  {
    # Hazard‑specific observations linked to the hurricane (e.g., magnitude, storm track)
    ?obs sosa:hasFeatureOfInterest ?hurricane ;
         sosa:observedProperty   ?property .
    OPTIONAL { ?obs sosa:hasSimpleResult ?value . }
    OPTIONAL {
      ?obs sosa:phenomenonTime ?tNode .
      ?tNode time:hasBeginning|time:inXSDDateTime ?time .
    }
  } UNION {
    # Impact observations (damage, deaths, injuries) linked to the same hurricane
    ?impactObs a kwg-ont:ImpactObservation ;
               sosa:hasFeatureOfInterest ?hurricane ;
               sosa:observedProperty   ?property .
    OPTIONAL { ?impactObs sosa:hasSimpleResult ?value . }
    OPTIONAL {
      ?impactObs sosa:phenomenonTime ?tNode .
      ?tNode time:hasBeginning|time:inXSDDateTime ?time .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?place ?damageDetail ?property ?start ?end
WHERE {
  # Tornado‑specific hazard
  ?hazard a kwg-ont:NOAATornado .

  # Geographic place linked to the hazard
  ?hazard kwg-ont:spatialRelation ?place .

  # Damage details from impact observations
  ?impactObs a kwg-ont:ImpactObservation ;
             sosa:hasFeatureOfInterest ?hazard ;
             sosa:observedProperty   ?property ;
             sosa:hasSimpleResult    ?damageDetail .

  # Property must be a kind of impact observable (e.g., damageCrop, deathDirect)
  ?property rdfs:subClassOf kwg-ont:ImpactObservableProperty .

  # Temporal extent of the hazard (optional – include if present)
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?temp .
    OPTIONAL { ?temp time:hasBeginning ?b . ?b time:inXSDDateTime ?start . }
    OPTIONAL { ?temp time:hasEnd       ?e . ?e time:inXSDDateTime ?end   . }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?damageProp ?damageValue ?hazard ?place ?begin ?end
WHERE {
  # Impact observation that records a damage metric
  ?impactObs a kwg-ont:ImpactObservation ;
             sosa:hasFeatureOfInterest ?hazard ;
             sosa:observedProperty   ?damageProp ;
             sosa:hasSimpleResult    ?damageValue .

  # Damage properties are subclasses of the generic impact observable property
  ?damageProp rdfs:subClassOf kwg-ont:ImpactObservableProperty .

  # Hazard must be a storm‑related NOAA hazard event (e.g., tornado, hail, etc.)
  ?hazard a ?hazardType .
  ?hazardType rdfs:subClassOf kwg-ont:NOAAHazardEvent .

  # Temporal extent of the hazard
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?tempEntity .
    ?tempEntity time:hasBeginning ?begin ;
                time:hasEnd       ?end .
  }

  # Geographic place related to the hazard
  OPTIONAL {
    ?hazard kwg-ont:spatialRelation ?place .
    ?place a geo:Feature .
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doi
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasIdentifier ?doiNode .
  ?doiNode coresr-ont:doiAsString ?doi .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
  ?advisor a coresr-ont:Advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent a coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
