SELECT ?state ?univ ?pubCount
WHERE {
  {
    SELECT ?state ?univ (COUNT(DISTINCT ?pub) AS ?pubCount)
    WHERE {
      ?pub a coress-ont:Publication ;
           coress-ont:submittedBy ?author .
      ?author coress-ont:worksInDepartment ?dept .
      ?dept   coress-ont:departmentOf     ?college .
      ?college coress-ont:collegeOf       ?univ .
      ?univ   coress-ont:atState          ?state .
    }
    GROUP BY ?state ?univ
  }
  {
    SELECT ?state (MAX(?cnt) AS ?maxCount)
    WHERE {
      {
        SELECT ?state ?univ (COUNT(DISTINCT ?pub) AS ?cnt)
        WHERE {
          ?pub a coress-ont:Publication ;
               coress-ont:submittedBy ?author .
          ?author coress-ont:worksInDepartment ?dept .
          ?dept   coress-ont:departmentOf     ?college .
          ?college coress-ont:collegeOf       ?univ .
          ?univ   coress-ont:atState          ?state .
        }
        GROUP BY ?state ?univ
      }
    }
    GROUP BY ?state
  }
  FILTER (?pubCount = ?maxCount)
}
ORDER BY ?state

