SELECT ?hazard ?type ?label ?time
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { 
    ?hazard a ?type .
    FILTER ( ?type != kwg-ont:Hazard )
  }
  OPTIONAL { ?hazard rdfs:label ?label . }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place kwg-ont:hasName                     ?name . }
  OPTIONAL { ?place rdfs:label                         ?name . }
  OPTIONAL { ?place kwg-ont:hospitalName                 ?name . }
  OPTIONAL { ?place kwg-ont:siteName                     ?name . }
  OPTIONAL { ?place kwg-ont:publicHealthDepartmentName   ?name . }
  FILTER (BOUND(?name))
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?placeLabel
                ?hospitalName ?hospitalType
                ?pharmacyName ?pharmType
                ?prop ?value
WHERE {
  # all geographic places (administrative regions at level 3)
  ?place a kwg-ont:AdministrativeRegion_3 .
  OPTIONAL { ?place rdfs:label ?placeLabel . }

  # hospitals located in the place and their health‑related attributes
  OPTIONAL {
    ?hospital a kwg-ont:Hospital ;
              kwg-ont:sfWithin ?place ;
              rdfs:label ?hospitalName .
    OPTIONAL { ?hospital kwg-ont:hospitalType ?hospitalType . }
  }

  # pharmacies located in the place and their health‑related attributes
  OPTIONAL {
    ?pharmacy a kwg-ont:Pharmacy ;
              kwg-ont:sfWithin ?place ;
              rdfs:label ?pharmacyName .
    OPTIONAL { ?pharmacy kwg-ont:pharmacyType ?pharmType . }
  }

  # public‑health observations that concern the place
  OPTIONAL {
    ?obsColl a sosa:ObservationCollection ;
             sosa:hasFeatureOfInterest ?place ;
             sosa:hasMember ?obs .
    ?obs sosa:observedProperty ?prop .
    FILTER ( ?prop rdf:type kwg-ont:PublicHealthObservableProperty )
    OPTIONAL {
      ?obs sosa:hasResult ?result .
      OPTIONAL { ?result <http://qudt.org/2.1/schema/qudt#numericValue> ?value . }
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?earthquake ?totalCount WHERE {
  { SELECT (COUNT(DISTINCT ?e) AS ?totalCount)
    WHERE { ?e a kwg-ont:Earthquake . }
  }
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX qudt: <http://qudt.org/1.1/schema/qudt#>

SELECT DISTINCT 
       ?hazard          # the storm hazard instance
       ?hazardLabel     # its label (e.g., Hurricane, Tropical Storm)
       ?placeLabel      # name of the geographic place it affects
       ?attribute       # name of the attribute (magnitude or impact property)
       ?value           # numeric value of that attribute (if available)

WHERE {
  # --- storm‑specific hazard instances ---
  ?hazard a kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?hazard rdfs:label ?hazardLabel . }

  # --- geographic places associated with the hazard (AdministrativeRegion or S2Cell) ---
  OPTIONAL {
    ?hazard kwg-ont:sfWithin|kwg-ont:hasPart ?place .
    OPTIONAL { ?place rdfs:label ?placeLabel . }
  }

  # --- retrieve any magnitude‑related attributes ---
  {
    ?magCol a kwg-ont:MagnitudeObservationCollection ;
            sosa:hasFeatureOfInterest ?hazard ;
            sosa:hasMember          ?obs .

    ?obs sosa:observedProperty ?prop .
    OPTIONAL { ?prop rdfs:label ?attribute . }

    ?obs sosa:hasResult ?res .
    OPTIONAL { ?res qudt:numericValue ?value . }
  } UNION {
    # --- retrieve any impact‑related attributes ---
    ?impCol a kwg-ont:ImpactObservationCollection ;
            sosa:hasFeatureOfInterest ?hazard ;
            sosa:hasMember          ?obs .

    ?obs sosa:observedProperty ?prop .
    OPTIONAL { ?prop rdfs:label ?attribute . }

    ?obs sosa:hasResult ?res .
    OPTIONAL { ?res qudt:numericValue ?value . }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?flood ?property ?value
WHERE {
  ?flood a ?type .
  ?type rdfs:subClassOf* kwg-ont:NOAAFlood .
  OPTIONAL { ?flood ?property ?value . }
}
ORDER BY ?flood

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?attribute
WHERE {
  ?obsColl a kwg-ont:ClimateDivisionObservationCollection ;
           sosa:hasFeatureOfInterest ?place ;
           sosa:hasMember ?obs .
  ?obs sosa:observedProperty ?attribute .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?earthquake ?type ?magValue ?depthValue
WHERE {
  # Earthquake hazard instances
  ?earthquake a kwg-ont:Earthquake .

  # Additional RDF types that classify the earthquake (e.g., specific sub‑classes)
  OPTIONAL { 
    ?earthquake a ?type .
    FILTER(?type != kwg-ont:Earthquake)   # exclude the generic class itself
  }

  # Magnitude (if reported as an EarthquakeObservation)
  OPTIONAL {
    ?magObs a sosa:EarthquakeObservation ;
            sosa:hasFeatureOfInterest ?earthquake ;
            sosa:observedProperty kwgr:earthquakeObservableProperty.mag ;
            sosa:hasResult ?magValue .
  }

  # Depth (if reported as an EarthquakeObservation)
  OPTIONAL {
    ?depthObs a sosa:EarthquakeObservation ;
              sosa:hasFeatureOfInterest ?earthquake ;
              sosa:observedProperty kwgr:earthquakeObservableProperty.depth ;
              sosa:hasResult ?depthValue .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardEvent ?impactProperty ?result
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazardEvent ;
       sosa:observedProperty ?impactProperty ;
       sosa:hasResult ?result .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?damageDetail ?label WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       kwg-ont:affectedBy ?hazard ;
       sosa:observedProperty ?damageDetail .
  OPTIONAL { ?damageDetail rdfs:label ?label . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX qudt: <http://qudt.org/1.1/schema/qudt#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT
       ?hurricane               # the hurricane instance
       ?attrProp                # hurricane‑specific attribute (e.g., wind, pressure)
       ?attrValue               # numeric value of that attribute
       ?attrUnit                # unit of the attribute (if any)
       ?impactProp              # damage/impact property (e.g., damageCrop, deathDirect)
       ?impactValue             # numeric impact value
       ?impactUnit              # unit of the impact value (if any)
       ?timeStart               # start of the temporal extent for the impact observation
       ?timeEnd                 # end   of the temporal extent for the impact observation
WHERE {
  #################################################################
  # 1️⃣  Hurricane instances (NOAA hurricane events)                #
  #################################################################
  ?hurricane a kwg-ont:NOAAHurricane .

  #################################################################
  # 2️⃣  Hurricane‑specific attributes (magnitude observations)     #
  #################################################################
  OPTIONAL {
    ?magColl a kwg-ont:MagnitudeObservationCollection ;
             sosa:hasFeatureOfInterest ?hurricane ;
             sosa:hasMember ?magObs .
    ?magObs sosa:observedProperty ?attrProp ;
            sosa:hasResult        ?magRes .
    ?magRes qudt:numericValue   ?attrValue .
    OPTIONAL { ?magRes qudt:unit ?attrUnit . }
  }

  #################################################################
  # 3️⃣  Damage / impact details (impact observations)               #
  #################################################################
  OPTIONAL {
    ?impColl a kwg-ont:ImpactObservationCollection ;
             sosa:hasFeatureOfInterest ?hurricane ;
             sosa:hasMember           ?impObs .
    ?impObs sosa:observedProperty ?impactProp ;
            sosa:hasResult        ?impRes .
    ?impRes qudt:numericValue   ?impactValue .
    OPTIONAL { ?impRes qudt:unit ?impactUnit . }

    # Temporal information attached to the collection (if present)
    OPTIONAL {
      ?impColl sosa:phenomenonTime ?timeEnt .
      OPTIONAL { ?timeEnt time:hasBeginning ?timeStart . }
      OPTIONAL { ?timeEnt time:hasEnd       ?timeEnd   . }
    }
  }

  #################################################################
  # Optional geographic linking (place‑related) – any place that the
  # hurricane is spatially related to (AdministrativeRegion_3 or S2Cell)
  #################################################################
  OPTIONAL {
    ?hurricane kwg-ont:sfWithin|kwg-ont:spatialRelation ?place .
    FILTER( STRSTARTS(STR(?place), "http://stko-kwg.geog.ucsb.edu/lod/ontology/AdministrativeRegion_3")
         || STRSTARTS(STR(?place), "http://stko-kwg.geog.ucsb.edu/lod/ontology/S2Cell") )
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?tornado ?damageProp ?value ?place ?timeEntity
WHERE {
  # Tornado hazards
  ?tornado a kwg-ont:NOAATornado .

  # Spatial relation to a place (e.g., an administrative region)
  OPTIONAL {
    ?tornado kwg-ont:sfWithin ?place .
    ?place a kwg-ont:AdministrativeRegion .
  }

  # Temporal scope of the tornado event
  OPTIONAL {
    ?tornado kwg-ont:hasTemporalScope ?timeEntity .
    ?timeEntity a time:TemporalEntity .
  }

  # Impact observations linked to this tornado
  ?impactColl a kwg-ont:ImpactObservationCollection ;
              sosa:hasFeatureOfInterest ?tornado ;
              sosa:hasMember ?obs .

  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?damageProp .

  # Damage value (simple result literal, if present)
  OPTIONAL { ?obs sosa:hasSimpleResult ?value . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication .
  OPTIONAL { ?publication coresr-ont:dateOfSubmission ?submissionDate . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
  ?advisor a coresr-ont:Advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?pubType ?typeLabel
WHERE {
  ?publication a coresr-ont:Publication .
  ?publication coresr-ont:hasPublicationType ?pubType .
  OPTIONAL { ?pubType coresr-ont:typeAsString ?typeLabel . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?agent ?department
WHERE {
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?college ?university ?city
WHERE {
  ?college a coresr-ont:College ;
           coresr-ont:partOf ?university .
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .
  ?location a coresr-ont:Location ;
            coresr-ont:atState ?state .
  ?state a coresr-ont:State ;
         coresr-ont:inCity ?city .
  ?city a coresr-ont:City .
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?typeString (AVG(?duration) AS ?avgDuration)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate ;
       coresr-ont:hasPublicationType ?ptype .
  ?ptype coresr-ont:typeAsString ?typeString .
  BIND (xsd:dateTime(?pubDate) AS ?pubDT)
  BIND (xsd:dateTime(?subDate) AS ?subDT)
  BIND (?pubDT - ?subDT AS ?duration)
}
GROUP BY ?typeString
ORDER BY DESC(?avgDuration)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department (COUNT(DISTINCT ?agent) AS ?missingFamilyNameCount)
WHERE {
  ?department a coresr-ont:Department .
  ?department coresr-ont:hasAssociatedAgent ?agent .
  FILTER NOT EXISTS { 
    ?agent coresr-ont:hasContactInformation ?fn .
    ?fn a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)
LIMIT 1

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?publication ?dateOfSubmission
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?dateOfSubmission .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?university ?city
WHERE {
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?loc .
  ?loc       coresr-ont:atState   ?state .
  ?state     coresr-ont:inCity    ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author ?advisor
WHERE {
  { 
    ?author a coresr-ont:Author ;
            coresr-ont:advisedBy ?advisor .
    ?advisor a coresr-ont:Advisor .
  }
  UNION
  {
    ?advisor a coresr-ont:Advisor ;
             coresr-ont:advises ?author .
    ?author a coresr-ont:Author .
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?typeLabel
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasPublicationType ?ptype .
  OPTIONAL { ?ptype coresr-ont:typeAsString ?typeLabel . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?agent ?department WHERE {
  ?agent a coresr-ont:Agent .
  { ?agent coresr-ont:associatedWith ?department . }
  UNION
  { ?department coresr-ont:hasAssociatedAgent ?agent . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?fieldOfStudy ?fieldLabel ?publication ?pubTitle
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
  OPTIONAL { ?fieldOfStudy coresr-ont:nameAsString ?fieldLabel . }
  OPTIONAL { ?publication coresr-ont:hasTitle ?pubTitle . }
}
ORDER BY ?fieldOfStudy ?publication

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?city ?college
WHERE {
  ?college a coresr-ont:College .
  ?college coresr-ont:partOf ?university .
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .

  ?location a coresr-ont:Location ;
            coresr-ont:atState ?state .

  ?state a coresr-ont:State ;
         coresr-ont:inCity ?city .

  ?city a coresr-ont:City .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pub ?title (COUNT(DISTINCT ?dept) AS ?deptCount)
WHERE {
  ?pub a coresr-ont:Publication .
  OPTIONAL { ?pub coresr-ont:hasTitle ?title . }

  {
    ?pub coresr-ont:submittedBy ?role .
  } UNION {
    ?pub coresr-ont:hasContributor ?role .
  }

  ?role a coresr-ont:Role ;
        coresr-ont:isPerformedBy ?agent .

  ?agent coresr-ont:associatedWith ?dept .
}
GROUP BY ?pub ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX cr: <http://example.org/coresr-ont#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?typeStr (AVG(?daysDiff) AS ?avgDays)
WHERE {
  ?pub a cr:Publication ;
       cr:dateOfSubmission ?subDate ;
       cr:dateOfPublication ?pubDate ;
       cr:hasPublicationType ?ptype .

  ?ptype cr:typeAsString ?typeStr .

  BIND( (?pubDate - ?subDate) / xsd:dayTimeDuration("P1D") AS ?daysDiff )
}
GROUP BY ?typeStr
ORDER BY DESC(?avgDays)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author ?field
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor ;
          coresr-ont:submits ?pub .

  ?pub   coresr-ont:associatedFieldOfStudy ?field .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?dept (COUNT(?agent) AS ?missingCount)
WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?dept .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?ci .
    ?ci a coresr-ont:FamilyName .
  }
}
GROUP BY ?dept
ORDER BY DESC(?missingCount)
LIMIT 1

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?hazardType ?temporal ?property ?value
WHERE {
  ?hazard a ?hazardType .
  ?hazardType rdfs:subClassOf* kwg-ont:Hazard .
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporal . }
  OPTIONAL {
    ?hazard ?property ?value .
    FILTER(?property != rdf:type && ?property != kwg-ont:hasTemporalScope)
  }
}
ORDER BY ?hazard

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?property
WHERE {
  {   # Direct observations linked to a place
    ?obs a kwg-ont:PublicHealthObservation ;
         sosa:observedProperty ?property .
    OPTIONAL { ?obs sosa:hasFeatureOfInterest ?place . }
  }
  UNION
  {   # Observations accessed via a collection that has a place as feature of interest
    ?col a kwg-ont:PublicHealthObservationCollection ;
         sosa:hasMember ?obs ;
         sosa:hasFeatureOfInterest ?place .
    ?obs sosa:observedProperty ?property .
  }
  # Ensure the place is a geographical entity
  FILTER EXISTS { ?place a geo:Feature }
}
ORDER BY ?place ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquakeType (?total AS ?count)
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  FILTER(?earthquakeType != kwg-ont:Earthquake) .
  {
    SELECT (COUNT(DISTINCT ?t) AS ?total)
    WHERE {
      ?t rdfs:subClassOf* kwg-ont:Earthquake .
      FILTER(?t != kwg-ont:Earthquake)
    }
  }
}
ORDER BY ?earthquakeType

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?place ?attribute (COUNT(?obs) AS ?count)
WHERE {
  ?obs a kwg-ont:MagnitudeObservation ;
       sosa:hasFeatureOfInterest ?hazard ;
       sosa:observedProperty ?attribute .
  ?hazard a kwg-ont:NOAATornado ;
          kwg-ont:spatialRelation ?place .
}
GROUP BY ?place ?attribute
ORDER BY ?place ?attribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?stormAttribute ?superClass ?property ?value
WHERE {
  { 
    ?stormAttribute rdfs:subClassOf* kwg-ont:StormTrackObservableProperty .
    OPTIONAL { ?stormAttribute rdfs:subClassOf ?superClass . }
    OPTIONAL { ?stormAttribute ?property ?value . }
  } UNION {
    ?stormAttribute rdfs:subClassOf* kwg-ont:StormTrackletObservableProperty .
    OPTIONAL { ?stormAttribute rdfs:subClassOf ?superClass . }
    OPTIONAL { ?stormAttribute ?property ?value . }
  }
}
ORDER BY ?stormAttribute ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?floodType ?property ?value
WHERE {
  ?floodType rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  FILTER regex(str(?floodType), "Flood", "i") .
  OPTIONAL { ?floodType ?property ?value . }
}
ORDER BY ?floodType ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?property
WHERE {
  # climate‑specific attributes (observable properties)
  ?property rdfs:subClassOf kwg-ont:ClimateObservableProperty .

  OPTIONAL {
    # link to any geographical feature that has an observation using this attribute
    ?obsColl a kwg-ont:ClimateDivisionPropertyObservationCollection ;
             sosa:observedProperty ?property ;
             sosa:hasMember ?climateObs .
    ?climateObs sosa:hasResult ?result .
    ?result sosa:hasFeatureOfInterest ?place .
  }
}
ORDER BY ?property ?place

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?eqType ?superType ?property ?value
WHERE {
  ?eqType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?eqType rdfs:subClassOf ?superType . }
  OPTIONAL { ?eqType ?property ?value . }
}
ORDER BY ?eqType ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardEvent ?impactObs ?property ?value
WHERE {
  ?impactObs a kwg-ont:ImpactObservation .
  ?impactObs sosa:hasFeatureOfInterest ?hazardEvent .
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?impactObs sosa:observedProperty ?property . }
  OPTIONAL { ?impactObs sosa:hasSimpleResult ?value . }
}
ORDER BY ?hazardEvent ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?damageDetail
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?damageDetail ;
       sosa:hasFeatureOfInterest ?hazard .
  ?hazard a kwg-ont:Hazard .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricane ?geom ?place ?impactProp ?damageValue ?impactTime
WHERE {
  # Hurricane hazard instances
  ?hurricane a kwg-ont:NOAAHurricane .
  OPTIONAL { ?hurricane geo:hasGeometry ?geom . }
  OPTIONAL { ?hurricane kwg-ont:spatialRelation ?place . }

  # Impact observations linked to the hurricane
  ?impactObs a kwg-ont:ImpactObservation ;
            sosa:hasFeatureOfInterest ?hurricane ;
            sosa:observedProperty ?impactProp ;
            sosa:hasSimpleResult ?damageValue .
  OPTIONAL { ?impactObs sosa:phenomenonTime ?impactTime . }
}
ORDER BY ?hurricane ?impactProp

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?tornadoEvent ?damageProp ?value ?place ?begin ?end
WHERE {
  # Tornado-specific hazard events
  ?tornadoEvent a kwg-ont:NOAATornado .

  # Impact observations linked to the tornado event
  ?impactObs a kwg-ont:ImpactObservation ;
             sosa:hasFeatureOfInterest ?tornadoEvent ;
             sosa:observedProperty   ?damageProp ;
             sosa:hasSimpleResult    ?value .

  # Ensure the observed property is a damage‑related ImpactObservableProperty
  ?damageProp rdfs:subClassOf kwg-ont:ImpactObservableProperty .

  # Spatial relation of the tornado to a place (e.g., S2Cell)
  OPTIONAL {
    ?tornadoEvent kwg-ont:spatialRelation ?place .
  }

  # Temporal extent of the tornado event
  OPTIONAL {
    ?tornadoEvent kwg-ont:hasTemporalScope ?temporal .
    OPTIONAL { ?temporal time:hasBeginning ?begin . }
    OPTIONAL { ?temporal time:hasEnd       ?end   . }
  }
}
ORDER BY ?tornadoEvent ?damageProp

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?damageProp ?damageValue ?hazard ?stormTrack ?geom ?tempBegin ?tempEnd
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent .
  ?stormTrack kwg-ont:hasStormTrack ?hazard .
  ?impactObs sosa:hasFeatureOfInterest ?hazard ;
              sosa:observedProperty ?damageProp ;
              sosa:hasSimpleResult ?damageValue .

  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?tempEntity .
    OPTIONAL { 
      ?tempEntity time:hasBeginning ?beginInst .
      ?beginInst time:inXSDDateTime ?tempBegin .
    }
    OPTIONAL { 
      ?tempEntity time:hasEnd ?endInst .
      ?endInst time:inXSDDateTime ?tempEnd .
    }
  }

  OPTIONAL { ?stormTrack geo:hasGeometry ?geom . }
}
ORDER BY ?damageProp

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?author
WHERE {
  ?author a coress-ont:Author .
}

