SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication .
  OPTIONAL { ?publication coress-ont:dateOfSubmission ?submissionDate . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city
WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author ?advisor
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?type
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?type .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?agent ?firstName ?familyName ?department
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  OPTIONAL { ?agent coress-ont:hasFirstName ?firstName . }
  OPTIONAL { ?agent coress-ont:hasFamilyName ?familyName . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT DISTINCT ?college ?university ?city
WHERE {
  ?college a coress-ont:College ;
           coress-ont:collegeOf ?university .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?univ ?pubCount
WHERE {
  # Count publications per university
  {
    SELECT ?state ?univ (COUNT(?pub) AS ?pubCount)
    WHERE {
      ?univ a coress-ont:University ;
            coress-ont:atState ?state .
      ?pub a coress-ont:Publication ;
           coress-ont:submittedBy ?author .
      ?author a coress-ont:Author .
      ?agent coress-ont:performsRole ?author ;
             coress-ont:worksInDepartment ?dept .
      ?dept coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?univ .
    }
    GROUP BY ?state ?univ
  }
  # Determine the maximum publication count per state
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt)
    WHERE {
      SELECT ?state ?univ (COUNT(?pub) AS ?cnt)
      WHERE {
        ?univ a coress-ont:University ;
              coress-ont:atState ?state .
        ?pub a coress-ont:Publication ;
             coress-ont:submittedBy ?author .
        ?author a coress-ont:Author .
        ?agent coress-ont:performsRole ?author ;
               coress-ont:worksInDepartment ?dept .
        ?dept coress-ont:departmentOf ?college .
        ?college coress-ont:collegeOf ?univ .
      }
      GROUP BY ?state ?univ
    } GROUP BY ?state
  }
  FILTER (?pubCount = ?maxCnt)
}
ORDER BY ?state ?univ

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?pubType (AVG(?duration) AS ?avgDuration)
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasPublicationType ?pubType ;
               coress-ont:dateOfSubmission ?subDate ;
               coress-ont:dateOfPublication ?pubDate .

  BIND ( xsd:dateTime(?pubDate) AS ?pubDT )
  BIND ( xsd:dateTime(?subDate) AS ?subDT )
  BIND ( (?pubDT - ?subDT) AS ?duration )
}
GROUP BY ?pubType
ORDER BY DESC(?avgDuration)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)
LIMIT 1

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?property ?value ?time
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard ?property ?value . FILTER(?property != rdf:type) }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time . }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a ?type .
  ?type rdfs:subClassOf* geo:Feature .
  OPTIONAL { ?place rdfs:label ?name . }
  OPTIONAL { ?place kwg-ont:hasName ?name . }
}
ORDER BY ?place

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?property
WHERE {
  ?obs a sosa:Observation .
  ?obs sosa:observedProperty ?property .
  ?obs sosa:hasFeatureOfInterest ?place .
  { ?property rdfs:subClassOf* kwg-ont:PublicHealthObservableProperty }
  UNION
  { ?property rdfs:subClassOf* kwg-ont:ImpactObservableProperty }
}
ORDER BY ?place ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?earthquakeHazard ?totalCount
WHERE {
  {
    SELECT (COUNT(DISTINCT ?h) AS ?totalCount)
    WHERE { ?h rdfs:subClassOf* kwg-ont:Earthquake . }
  }
  ?earthquakeHazard rdfs:subClassOf* kwg-ont:Earthquake .
}
ORDER BY ?earthquakeHazard

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?property (COUNT(DISTINCT ?tornado) AS ?tornadoCount)
WHERE {
  ?tornado a kwg-ont:NOAATornado ;
           ?property ?value .
}
GROUP BY ?property
ORDER BY ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?stormType ?superType ?property ?value
WHERE {
  ?stormType rdfs:subClassOf* kwg-ont:StormTrack .
  OPTIONAL { ?stormType rdfs:subClassOf ?superType . }
  OPTIONAL { ?stormType ?property ?value . }
}
ORDER BY ?stormType ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?floodHazard ?property ?value
WHERE {
  ?floodHazard rdfs:subClassOf* kwg-ont:NOAAFlood .
  OPTIONAL { ?floodHazard ?property ?value . }
}
ORDER BY ?floodHazard

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?climateAttribute
WHERE {
  ?obs a kwg-ont:ClimateObservation ;
       sosa:observedProperty ?climateAttribute ;
       sosa:hasFeatureOfInterest ?place .
  ?place a geo:Feature .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?hurricane ?attribute ?attrValue ?impactProp ?temporal
WHERE {
  # Hurricane events (NOAA hurricanes) linked to a geographic place
  ?hurricane a kwg-ont:NOAAHurricane ;
             kwg-ont:spatialRelation ?place .
  ?place a geo:Feature .

  # All available hazard attributes for the hurricane
  OPTIONAL {
    ?hurricane ?attribute ?attrValue .
    FILTER(?attribute != rdf:type)
  }

  # Damage impact details (impact observations) and their temporal data, if any
  OPTIONAL {
    ?col a kwg-ont:ImpactObservationCollection ;
         sosa:hasFeatureOfInterest ?hurricane ;
         sosa:hasMember ?obs .
    ?obs sosa:observedProperty ?impactProp .
    OPTIONAL { ?col sosa:phenomenonTime ?temporal . }
  }
}
ORDER BY ?hurricane ?attribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?tornado ?damageProp ?value ?place ?time
WHERE {
  # tornado‑specific hazard
  ?tornado a kwg-ont:NOAATornado .

  # place related to the tornado (any spatial relation)
  OPTIONAL { ?tornado kwg-ont:sfWithin|kwg-ont:spatialRelation ?place . }

  # temporal extent of the tornado, if recorded
  OPTIONAL { ?tornado kwg-ont:hasTemporalScope ?time . }

  # impact observations linked to this tornado
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?tornado ;
       sosa:observedProperty ?damageProp .

  # we are interested only in damage‑related observable properties
  ?damageProp a kwg-ont:ImpactObservableProperty .

  # retrieve the reported damage value (if any)
  OPTIONAL { ?obs ?damageProp ?value . }
}
ORDER BY ?tornado ?damageProp

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?place ?damageProp ?damageValue ?time
WHERE {
  ?impact a kwg-ont:ImpactObservation ;
          sosa:observedProperty ?damageProp ;
          sosa:hasFeatureOfInterest ?hazard .
  OPTIONAL { ?impact sosa:hasResult ?damageValue . }

  ?hazard a kwg-ont:NOAAHazardEvent ;
          kwg-ont:sfWithin ?place .
  ?place a geo:Feature .

  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time . }
}
ORDER BY ?hazard ?damageProp

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?type ?property ?value ?time
WHERE {
  ?hazard a ?type .
  ?type rdfs:subClassOf* kwg-ont:Hazard .

  OPTIONAL { 
    ?hazard ?property ?value .
    FILTER(?property != rdf:type)
  }

  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?time .
  }
}
ORDER BY ?hazard ?property

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place rdfs:label ?name . }
  OPTIONAL { ?place kwg-ont:hasName ?name . }
}
ORDER BY ?place

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?healthAttribute
WHERE {
  ?collection a kwg-ont:PublicHealthObservationCollection .
  ?collection sosa:hasFeatureOfInterest ?place .
  OPTIONAL {
    ?collection sosa:hasMember ?obs .
    ?obs sosa:observedProperty ?healthAttribute .
  }
}
ORDER BY ?place ?healthAttribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?attribute
WHERE {
  ?obs a kwg-ont:CensusACS5YearEstimatesObservation ;
       sosa:observedProperty ?attribute ;
       sosa:hasFeatureOfInterest ?place .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquakeHazard ?total
WHERE {
  ?earthquakeHazard rdfs:subClassOf* kwg-ont:Earthquake .
  {
    SELECT (COUNT(DISTINCT ?h) AS ?total)
    WHERE { ?h rdfs:subClassOf* kwg-ont:Earthquake . }
  }
}
ORDER BY ?earthquakeHazard

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?attribute (COUNT(?obs) AS ?occurrences)
WHERE {
  ?obs a sosa:Observation ;
       sosa:observedProperty ?attribute ;
       sosa:hasFeatureOfInterest ?tornado .
  ?tornado a kwg-ont:NOAATornado .
}
GROUP BY ?attribute
ORDER BY ?attribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?storm ?geom ?obs ?property ?value
WHERE {
  ?storm a kwg-ont:StormTrack .
  OPTIONAL { ?storm kwg-ont:hasGeometry ?geom . }
  OPTIONAL {
    ?obs a kwg-ont:StormTrackObservation ;
         sosa:observedProperty ?property ;
         sosa:hasFeatureOfInterest ?storm .
    OPTIONAL { ?obs sosa:hasResult ?value . }
  }
}
ORDER BY ?storm ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?floodClass ?superClass ?property ?value
WHERE {
  ?floodClass rdfs:subClassOf* kwg-ont:Hazard .
  FILTER regex(str(?floodClass), "Flood") .
  OPTIONAL { ?floodClass rdfs:subClassOf ?superClass . }
  OPTIONAL { ?floodClass ?property ?value . }
}
ORDER BY ?floodClass ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?climateAttr
WHERE {
  ?obs a kwg-ont:ClimateObservation ;
       sosa:observedProperty ?climateAttr ;
       sosa:hasFeatureOfInterest ?place .
  ?place a geo:Feature .
}
ORDER BY ?climateAttr

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?damageDetail
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?damageDetail .
  ?col a kwg-ont:ImpactObservationCollection ;
       sosa:hasMember ?obs ;
       sosa:hasFeatureOfInterest ?hazard .
  ?hazard a kwg-ont:Hazard .
  ?damageDetail a kwg-ont:ImpactObservableProperty .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricane ?hazProp ?hazVal ?damageProp ?damageVal ?time
WHERE {
  # Hurricane instances (NOAA hurricane events)
  ?hurricane a kwg-ont:NOAAHurricane .

  # All available hazard attributes for the hurricane (excluding type statements)
  OPTIONAL {
    ?hurricane ?hazProp ?hazVal .
    FILTER(?hazProp != rdf:type && ?hazProp != rdfs:label)
  }

  # Link to impact observation collection tied to this hurricane
  ?impactColl a kwg-ont:ImpactObservationCollection ;
              sosa:hasFeatureOfInterest ?hurricane ;
              sosa:hasMember ?impactObs .

  # Temporal scope of the impact observations (if present)
  OPTIONAL { ?impactColl sosa:phenomenonTime ?time . }

  # Damage impact details
  ?impactObs a kwg-ont:ImpactObservation ;
             sosa:observedProperty ?damageProp .

  # Values associated with each damage observation (excluding type statements)
  OPTIONAL {
    ?impactObs ?dp ?damageVal .
    FILTER(?dp != rdf:type && ?dp != sosa:observedProperty)
  }
}
ORDER BY ?hurricane ?hazProp ?damageProp

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?tornado ?damageProp ?resultValue ?place ?time
WHERE {
  ?tornado a kwg-ont:NOAATornado .

  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?tornado ;
       sosa:observedProperty ?damageProp ;
       sosa:hasResult ?result .

  OPTIONAL { 
    ?result ?valPred ?resultValue .
    FILTER(isLiteral(?resultValue))
  }

  OPTIONAL { ?tornado kwg-ont:sfWithin ?place . }
  OPTIONAL { ?tornado kwg-ont:hasTemporalScope ?time . }
}
ORDER BY ?tornado ?damageProp

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazard ?damageDetail ?timeExtent
WHERE {
  # Storm‑specific hazard (StormTrack or its subclasses)
  ?hazard a kwg-ont:StormTrack .

  # Temporal extent of the hazard, if available
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?timeExtent . }

  # Impact observations that record damage details and are linked to this hazard
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazard ;
       sosa:observedProperty ?damageDetail .
}
ORDER BY ?hazard ?damageDetail

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazard
                ?name
                ?type
                ?startDate
                ?endDate
                ?deaths
                ?damageCrops
                ?damageInfrastructure
                ?affectedArea
WHERE {
  # any individual that is a HazardEvent or subclass thereof
  ?hazard rdf:type ?class .
  ?class rdfs:subClassOf* kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName               ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate          ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate            ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths        ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars      ?damageCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres   ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType         ?type . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?place ?name
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?name .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?attribute ?value
WHERE {
  ?place a kwgl-ont:Place .
  VALUES ?attribute { kwgl-ont:percentDiabetic kwgl-ont:percentObese kwgl-ont:percentBelowPovertyLine }
  ?place ?attribute ?value .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?population ?households ?poverty ?diabetic ?obese
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?poverty . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic . }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?earthquakeHazard ?totalCount WHERE {
  # total number of distinct earthquake hazard events
  {
    SELECT (COUNT(DISTINCT ?e) AS ?totalCount)
    WHERE {
      ?e a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType kwglr:earthquake .
    }
  }
  # list each earthquake hazard event
  ?earthquakeHazard a kwgl-ont:HazardEvent ;
                    kwgl-ont:hasHazardType kwglr:earthquake .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?placeName ?hazardType ?eventName ?startDate ?endDate 
                ?affectedArea ?damageToCrops ?deaths
WHERE {
  # Hazard events that impact places
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasImpacted ?place ;
         kwgl-ont:hasHazardType ?hazardType ;
         kwgl-ont:hasName ?eventName .

  # Optional event details
  OPTIONAL { ?event kwgl-ont:hasStartDate   ?startDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate     ?endDate . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres      ?affectedArea . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars   ?damageToCrops . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths          ?deaths . }

  # Place name
  ?place kwgl-ont:hasName ?placeName .

  # Restrict to storm‑related hazard types
  VALUES ?hazardType {
    kwglr:hurricane
    kwglr:blizzard
    kwglr:heavySnow
    kwglr:highWind
    kwglr:iceStorm
    kwglr:lake-EffectSnow
    kwglr:stormSurgeTide
    kwglr:strongWind
    kwglr:thunderstormWind
    kwglr:tornado
    kwglr:tropicalDepression
    kwglr:tropicalStorm
    kwglr:waterspout
    kwglr:winterStorm
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute
WHERE {
  kwgl-ont:Place ?attribute ?value .
  FILTER regex(str(?attribute), "(Cooling|Heating|Temperature)", "i")
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard
       ?name
       ?startDate
       ?endDate
       ?affectedArea
       ?damageCrops
       ?damageInfrastructure
       ?deaths
       ?type
WHERE {
  # Earthquake hazard events
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType kwglr:earthquake .

  OPTIONAL { ?hazard kwgl-ont:hasName               ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate           ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate             ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres    ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths        ?deaths . }

  BIND(kwglr:earthquake AS ?type)
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event ?name ?affectedArea ?damageCrops ?damageInfrastructure ?deaths
WHERE {
  ?event a kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:hasName ?name . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?damageToCrops ?damageToInfrastructure
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  FILTER (BOUND(?damageToCrops) || BOUND(?damageToInfrastructure))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?place
       ?hazardEvent
       ?affectedArea
       ?damageCrops
       ?damageInfra
       ?deaths
       ?startDate
       ?endDate
       ?dollarDamagePlace
       ?dollarDamage2018
       ?dollarDamage2019
       ?dollarDamage2020
       ?dollarDamage2021
       ?dollarDamage2022
       ?numHurricanes
       ?numHurricanes2018
       ?numHurricanes2019
       ?numHurricanes2020
       ?numHurricanes2021
       ?numHurricanes2022
WHERE {
  # Hurricane events linked to places
  ?hazardEvent a kwgl-ont:Hurricane .
  ?hazardEvent kwgl-ont:hasImpacted ?place .

  # Hazard‑specific attributes (optional)
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres               ?affectedArea . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars           ?damageCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars   ?damageInfra . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths                   ?deaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate                     ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate                       ?endDate . }

  # Damage impact details at the place level (optional)
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace      ?dollarDamagePlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?dollarDamage2018 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?dollarDamage2019 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?dollarDamage2020 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?dollarDamage2021 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?dollarDamage2022 . }

  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace      ?numHurricanes . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2018 ?numHurricanes2018 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2019 ?numHurricanes2019 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2020 ?numHurricanes2020 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2021 ?numHurricanes2021 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2022 ?numHurricanes2022 . }
}
ORDER BY ?place ?hazardEvent

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?event ?placeName ?startDate ?endDate ?cropDamage ?infraDamage
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType kwglr:tornado ;
         kwgl-ont:hasImpacted ?place ;
         kwgl-ont:hasStartDate ?startDate ;
         kwgl-ont:hasEndDate ?endDate .
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  ?place kwgl-ont:hasName ?placeName .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazard ?hazardType ?place ?damageToCrops ?damageToInfrastructure ?startDate ?endDate
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?hazardType ;
          kwgl-ont:impactedBy ?place ;
          kwgl-ont:hasStartDate ?startDate .
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  FILTER (?hazardType IN (
    kwglr:hurricane,
    kwglr:tornado,
    kwglr:stormSurgeTide,
    kwglr:thunderstormWind,
    kwglr:highWind,
    kwglr:strongWind,
    kwglr:marineHighWind,
    kwglr:marineStrongWind,
    kwglr:marineTropicalStorm,
    kwglr:tropicalStorm,
    kwglr:tropicalDepression
  ))
}

