LIMIT 1

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?hazardClass ?label ?timeValue
WHERE {
  # any individual that is a Hazard (or subclass thereof)
  ?hazard a kwg-ont:Hazard .

  # the most specific class of the hazard (optional, to give its type)
  OPTIONAL { 
    ?hazard a ?hazardClass .
    FILTER(?hazardClass != kwg-ont:Hazard) 
  }

  # optional human‑readable label
  OPTIONAL { ?hazard rdfs:label ?label . }

  # optional temporal information (via hasTemporalScope → Instant/Interval)
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?timeEntity .
    OPTIONAL { ?timeEntity time:inXSDDateTime ?timeValue . }
    OPTIONAL { ?timeEntity time:inXSDDate ?dateValue . BIND(str(?dateValue) AS ?timeValue) }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?attr ?val WHERE {
  { # Hospitals and their health‑related attributes
    ?hospital a kwg-ont:Hospital ;
              kwg-ont:sfWithin ?place .

    OPTIONAL {
      ?hospital kwg-ont:hospitalStatus ?status .
      BIND(kwg-ont:hospitalStatus AS ?attr)
      BIND(?status AS ?val)
    }
    OPTIONAL {
      ?hospital kwg-ont:hospitalType ?type .
      BIND(kwg-ont:hospitalType AS ?attr)
      BIND(?type AS ?val)
    }
    OPTIONAL {
      ?hospital kwg-ont:helipadAvailability ?ha .
      BIND(kwg-ont:helipadAvailability AS ?attr)
      BIND(?ha AS ?val)
    }
    OPTIONAL {
      ?hospital kwg-ont:noHospitalBeds ?beds .
      BIND(kwg-ont:noHospitalBeds AS ?attr)
      BIND(?beds AS ?val)
    }
    FILTER (BOUND(?val))
  } UNION {
    # Pharmacies and their type
    ?pharmacy a kwg-ont:Pharmacy ;
              kwg-ont:sfWithin ?place .

    OPTIONAL {
      ?pharmacy kwg-ont:pharmacyType ?ptype .
      BIND(kwg-ont:pharmacyType AS ?attr)
      BIND(?ptype AS ?val)
    }
    FILTER (BOUND(?val))
  } UNION {
    # Public health departments and their name
    ?phd a kwg-ont:PublicHealthDepartment ;
         kwg-ont:sfWithin ?place .

    OPTIONAL {
      ?phd kwg-ont:publicHealthDepartmentName ?pname .
      BIND(kwg-ont:publicHealthDepartmentName AS ?attr)
      BIND(?pname AS ?val)
    }
    FILTER (BOUND(?val))
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?propertyLabel
WHERE {
  # Geographical places (e.g., Metropolitan/Micropolitan Statistical Areas)
  ?place a kwg-ont:USCensusMSA .

  # Census observation collection linked to the place
  ?obsColl a kwg-ont:CensusACS5YearEstimatesObservationCollection ;
           sosa:hasFeatureOfInterest ?place ;
           sosa:hasMember ?obs .

  # Each observation provides an observable property (demographic attribute)
  ?obs sosa:observedProperty ?prop .
  OPTIONAL { ?prop rdfs:label ?propertyLabel . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?earthquake ?totalCount WHERE {
  ?earthquake a kwg-ont:Earthquake .
  {
    SELECT (COUNT(DISTINCT ?eq) AS ?totalCount)
    WHERE { ?eq a kwg-ont:Earthquake . }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT
       ?hazard               # the storm hazard instance
       ?hazType              # its specific class (hurricane, tropical‑storm, tornado …)
       ?hazLabel             # human readable label
       ?time                 # temporal scope of the event
       ?geom                 # geometry (default) of the event
       ?magProp              # magnitude property observed (e.g., wind speed, pressure)
       ?magValue             # numeric value of that magnitude (if available)
WHERE {
  # --- storm‑specific hazard instances ---------------------------------
  ?hazard a ?hazType .
  FILTER ( ?hazType IN (kwg-ont:NOAAHurricane,
                        kwg-ont:NOAATropicalStorm,
                        kwg-ont:NOAATornado) )

  OPTIONAL { ?hazard rdfs:label ?hazLabel . }

  # temporal scope (instant or interval)
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time . }

  # geometry of the hazard
  OPTIONAL { ?hazard geo:hasDefaultGeometry ?geom . }

  # --- magnitude observations linked to this hazard --------------------
  OPTIONAL {
    ?magColl a kwg-ont:MagnitudeObservationCollection ;
             sosa:hasFeatureOfInterest ?hazard ;
             sosa:hasMember ?magObs .
    ?magObs a kwg-ont:MagnitudeObservation ;
            sosa:observedProperty ?magProp ;
            sosa:result ?magResult .
    OPTIONAL {
      ?magResult <http://qudt.org/2.1/schema/qudt#numericValue> ?magValue .
    }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?flood ?class ?property ?value
WHERE {
  VALUES ?class { kwg-ont:NOAAFlood kwg-ont:NOAACoastalFlood kwg-ont:NOAALakeshoreFlood }
  ?flood a ?class .
  ?flood ?property ?value .
  FILTER(?property != rdf:type)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?climateAttribute
WHERE {
  ?obs a kwg-ont:ClimateObservation ;
       sosa:observedProperty ?climateAttribute .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?earthquake ?label ?specificType ?wktGeometry
WHERE {
  # All earthquake hazard instances
  ?earthquake a kwg-ont:Earthquake .

  # Optional human‑readable label
  OPTIONAL { ?earthquake rdfs:label ?label . }

  # Any more specific type (subclass) the instance may have, excluding the generic classes
  OPTIONAL {
    ?earthquake rdf:type ?specificType .
    FILTER(?specificType != kwg-ont:Earthquake && ?specificType != kwg-ont:Hazard)
  }

  # Optional geometry of the earthquake (as WKT)
  OPTIONAL {
    ?earthquake geo:hasGeometry/geo:asWKT ?wktGeometry .
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazard ?propertyLabel ?value
WHERE {
  # Impact observation collections are linked to hazard events
  ?obsColl a kwg-ont:ImpactObservationCollection ;
           sosa:hasFeatureOfInterest ?hazard ;
           sosa:hasMember ?obs .

  # Each impact observation has an observable property (the “impact factor”)
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?property .

  # Optional result/value of the observation
  OPTIONAL {
    ?obs sosa:hasResult ?result .
    # The value may be expressed via a QUDT quantity or a literal
    { ?result <http://qudt.org/2.1/schema/qudt#numericValue> ?value }
    UNION
    { ?result ?anyProp ?value FILTER(isLiteral(?value)) }
  }

  # Human‑readable label for the property (if available)
  OPTIONAL { ?property rdfs:label ?propertyLabel . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?damageDetail WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?damageDetail .
  ?col a sosa:ObservationCollection ;
        sosa:hasMember ?obs ;
        sosa:hasFeatureOfInterest ?hazard .
  ?hazard a kwg-ont:Hazard .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT
       ?hurricane
       ?place
       ?attribute
       ?value
       ?time
WHERE {
  # Hurricane instances
  ?hurricane a kwg-ont:NOAAHurricane .

  # Geographical place the hurricane is associated with (if any)
  OPTIONAL { ?hurricane kwg-ont:sfWithin ?place . }

  # -------------------------------------------------
  # 1) Hurricane‑specific hazard attributes (e.g., magnitude, wind speed, pressure)
  # -------------------------------------------------
  {
    ?magColl a kwg-ont:MagnitudeObservationCollection ;
             sosa:hasFeatureOfInterest ?hurricane ;
             sosa:hasMember ?magObs .
    ?magObs a kwg-ont:MagnitudeObservation ;
            sosa:observedProperty ?attribute .

    OPTIONAL { ?magObs sosa:resultTime ?time . }

    # Retrieve the observed value (if present)
    OPTIONAL {
      ?magObs sosa:hasResult ?res .
      ?res ?valPred ?value .
    }
  }
  UNION
  # -------------------------------------------------
  # 2) Damage impact details (e.g., damageCrop, deathDirect, injuryIndirect, …)
  # -------------------------------------------------
  {
    ?impColl a kwg-ont:ImpactObservationCollection ;
             sosa:hasFeatureOfInterest ?hurricane ;
             sosa:hasMember ?impactObs .
    ?impactObs a kwg-ont:ImpactObservation ;
               sosa:observedProperty ?attribute .

    OPTIONAL { ?impactObs sosa:resultTime ?time . }

    # Retrieve the impact value (if present)
    OPTIONAL {
      ?impactObs sosa:hasResult ?res2 .
      ?res2 ?valPred2 ?value .
    }
  }
}

