PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?city ?college
WHERE {
  ?college a coress-ont:College ;
           coress-ont:collegeOf ?university .
  ?university a coress-ont:University ;
              coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?university ?pubCount
WHERE {
  # Count publications per university per state
  {
    SELECT ?state ?university (COUNT(?pub) AS ?pubCount)
    WHERE {
      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?dept .
      ?dept coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  # Determine the maximum count per state
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt)
    WHERE {
      SELECT ?state ?university (COUNT(?pub) AS ?cnt)
      WHERE {
        ?pub a coress-ont:Publication .
        ?pub coress-ont:submittedBy ?author .
        ?author coress-ont:isPerformedBy ?agent .
        ?agent coress-ont:worksInDepartment ?dept .
        ?dept coress-ont:departmentOf ?college .
        ?college coress-ont:collegeOf ?university .
        ?university coress-ont:atState ?state .
      }
      GROUP BY ?state ?university
    }
    GROUP BY ?state
  }
  FILTER(?pubCount = ?maxCnt)
}
ORDER BY ?state

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?title
WHERE {
  ?publication a coress-ont:Publication .
  OPTIONAL { ?publication coress-ont:hasTitle ?title . }

  ?author a coress-ont:Author ;
          coress-ont:isPerformedBy ?agent .
  ?publication coress-ont:submittedBy ?author .
  ?agent coress-ont:worksInDepartment ?dept .
}
GROUP BY ?publication ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?author ?advisor ?field
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor ;
          coress-ont:submits ?pub .
  ?pub   coress-ont:associatedFieldOfStudy ?field .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department (COUNT(?agent) AS ?missingCount)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
}
GROUP BY ?department
ORDER BY DESC(?missingCount)
LIMIT 1

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?doiValue
WHERE {
  ?publication a coresr-ont:Publication .
  OPTIONAL {
    ?publication coresr-ont:hasIdentifier ?doi .
    ?doi coresr-ont:doiAsString ?doiValue .
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication .
  OPTIONAL { ?publication coresr-ont:dateOfSubmission ?submissionDate . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?university ?city
WHERE {
  ?university a coresr-ont:University .
  OPTIONAL {
    ?university coresr-ont:locatedAt ?location .
    ?location   coresr-ont:atState   ?state .
    ?state      coresr-ont:inCity    ?city .
    ?city       a                  coresr-ont:City .
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
  ?advisor a coresr-ont:Advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?typeLabel (AVG(?duration) AS ?avgDuration)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?submissionDate ;
       coresr-ont:dateOfPublication ?publicationDate ;
       coresr-ont:hasPublicationType ?ptype .
  ?ptype coresr-ont:typeAsString ?typeLabel .
  BIND(?publicationDate - ?submissionDate AS ?duration)
}
GROUP BY ?typeLabel
ORDER BY DESC(?avgDuration)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?ci .
    ?ci a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT
  ?hazard
  ?name
  ?startDate
  ?endDate
  ?deaths
  ?damageInfra
  ?damageCrops
  ?affectedArea
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
}
ORDER BY ?startDate

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}
ORDER BY ?place

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?place
  ?percentDiabetic
  ?percentObese
  ?percentBelowPovertyLine
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?percentDiabetic . }
  OPTIONAL { ?place kwgl-ont:percentObese ?percentObese . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?percentBelowPovertyLine . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?earthquake ?totalCount WHERE {
  { SELECT (COUNT(DISTINCT ?e) AS ?totalCount)
    WHERE { ?e a kwgl-ont:Earthquake . }
  }
  ?earthquake a kwgl-ont:Earthquake .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?attribute ?totalCount WHERE {
  { SELECT (COUNT(DISTINCT ?a) AS ?totalCount) WHERE {
      ?a a owl:DatatypeProperty .
      FILTER(CONTAINS(LCASE(STR(?a)), "tornado"))
    }
  }
  ?attribute a owl:DatatypeProperty .
  FILTER(CONTAINS(LCASE(STR(?attribute)), "tornado"))
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range ?domain
WHERE {
  ?attribute a owl:DatatypeProperty .
  OPTIONAL { ?attribute rdfs:label ?label . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:domain ?domain . }
  FILTER (
    regex(lcase(str(?attribute)), "storm|hurricane|tornado") ||
    (bound(?label) && regex(lcase(str(?label)), "storm|hurricane|tornado"))
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?domain
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:domain ?domain . FILTER(?domain = kwgl-ont:Place) }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?earthquake
  ?name
  ?startDate
  ?endDate
  ?deaths
  ?affectedArea
  ?damageInfra
  ?hazardType
WHERE {
  ?earthquake rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?earthquake kwgl-ont:hasName ?name . }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?damageInfra . }
  OPTIONAL { ?earthquake kwgl-ont:hasHazardType ?hazardType . }
}
ORDER BY ?earthquake

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazardEvent ?eventName ?deaths ?cropDamage ?infrastructureDamage
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?eventName . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage . }
}
ORDER BY ?hazardEvent

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?place
  ?attribute
  ?value
  ?startDate
  ?endDate
WHERE {
  ?place a kwgl-ont:Place .
  ?place ?attribute ?value .
  FILTER (CONTAINS(LCASE(STR(?attribute)), "hurricane"))

  OPTIONAL {
    ?event a kwgl-ont:Hurricane ;
           kwgl-ont:impactedBy ?place .
    OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
    OPTIONAL { ?event kwgl-ont:hasEndDate   ?endDate   . }
  }
}
ORDER BY ?place ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?tornadoEvent
  ?place
  ?damageAmount
  ?startDate
  ?endDate
WHERE {
  ?tornadoEvent rdf:type kwgl-ont:Tornado .
  OPTIONAL { ?tornadoEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?tornadoEvent kwgl-ont:hasEndDate   ?endDate   . }
  ?tornadoEvent kwgl-ont:impactedBy ?place .
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageAmount . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?hazard ?hazardType ?damageProp ?damageValue ?startDate ?endDate
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?hazardType .
  FILTER regex(lcase(str(?hazardType)), "storm|hurricane|tornado|tropical") .

  ?place kwgl-ont:impactedBy ?hazard .

  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate   ?endDate   . }

  {
    ?place  ?damageProp ?damageValue .
  } UNION {
    ?hazard ?damageProp ?damageValue .
  }
  FILTER regex(lcase(str(?damageProp)), "damage")
}
ORDER BY ?place ?hazard

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT DISTINCT ?author ?firstName ?familyName
WHERE {
  ?author a coress-ont:Author .
  OPTIONAL { ?author coress-ont:hasFirstName ?firstName . }
  OPTIONAL { ?author coress-ont:hasFamilyName ?familyName . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication .
  OPTIONAL { ?publication coress-ont:hasDOI ?doi . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city WHERE {
  ?university a coress-ont:University .
  OPTIONAL { ?university coress-ont:atCity ?city . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?author ?advisor
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?pubType
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasPublicationType ?pubType .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?agent ?firstName ?familyName ?department WHERE {
  ?agent a coress-ont:Agent .
  OPTIONAL { ?agent coress-ont:hasFirstName ?firstName . }
  OPTIONAL { ?agent coress-ont:hasFamilyName ?familyName . }
  { ?agent coress-ont:worksInDepartment ?department . }
  UNION
  { ?department coress-ont:hasAgent ?agent . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT DISTINCT ?city ?college
WHERE {
  ?univ a coress-ont:University ;
        coress-ont:atCity ?city .
  ?college a coress-ont:College ;
           coress-ont:collegeOf ?univ .
}
ORDER BY ?city ?college

PREFIX co: <http://example.org/coress-ont#>

SELECT ?state ?university ?pubCount
WHERE {
  # Count publications per university and state
  {
    SELECT ?state ?university (COUNT(?pub) AS ?pubCount)
    WHERE {
      ?pub a co:Publication .
      ?pub co:submittedBy ?author .
      ?author a co:Author .
      ?author co:isPerformedBy ?agent .
      ?agent co:worksInDepartment ?dept .
      ?dept co:departmentOf ?college .
      ?college co:collegeOf ?university .
      ?university co:atState ?state .
    }
    GROUP BY ?state ?university
  }

  # Determine the maximum count per state
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt)
    WHERE {
      SELECT ?state ?uni (COUNT(?p) AS ?cnt)
      WHERE {
        ?p a co:Publication .
        ?p co:submittedBy ?auth .
        ?auth a co:Author .
        ?auth co:isPerformedBy ?ag .
        ?ag co:worksInDepartment ?dp .
        ?dp co:departmentOf ?col .
        ?col co:collegeOf ?uni .
        ?uni co:atState ?state .
      }
      GROUP BY ?state ?uni
    }
    GROUP BY ?state
  }

  FILTER(?pubCount = ?maxCnt)
}
ORDER BY ?state

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX co: <http://example.org/coress-ont#>

SELECT ?pubType (AVG(?duration) AS ?avgDuration)
WHERE {
  ?pub a co:Publication ;
       co:hasPublicationType ?pubType ;
       co:dateOfSubmission ?subDate ;
       co:dateOfPublication ?pubDate .
  BIND ((?pubDate - ?subDate) AS ?duration)   # xsd:dayTimeDuration
}
GROUP BY ?pubType
ORDER BY DESC(?avgDuration)
LIMIT 1

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?author ?advisor ?publication ?field
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor ;
          coress-ont:submits ?publication .

  ?publication coress-ont:associatedFieldOfStudy ?field .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(?agent) AS ?missingCount)
WHERE {
  ?agent a coress-ont:Agent ;
         coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
}
GROUP BY ?department
ORDER BY DESC(?missingCount)
LIMIT 1

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
