PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?earthquake ?total
WHERE {
  { SELECT (COUNT(DISTINCT ?e) AS ?total)
    WHERE { ?e a kwgl-ont:Earthquake . }
  }
  ?earthquake a kwgl-ont:Earthquake .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?attribute ?totalCount
WHERE {
  ?attribute a owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .
  FILTER(CONTAINS(LCASE(STR(?attribute)), "tornado"))

  {
    SELECT (COUNT(DISTINCT ?a) AS ?totalCount)
    WHERE {
      ?a a owl:DatatypeProperty ;
         rdfs:domain kwgl-ont:Place .
      FILTER(CONTAINS(LCASE(STR(?a)), "tornado"))
    }
  }
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?domain
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:domain ?domain . FILTER(?domain = kwgl-ont:Place) }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "storm")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?earthquakeEvent
  ?eventName
  ?startDate
  ?endDate
  ?numDeaths
  ?infrastructureDamage
  ?hazardType
WHERE {
  ?earthquakeEvent a kwgl-ont:Earthquake .

  OPTIONAL { ?earthquakeEvent kwgl-ont:hasName ?eventName . }
  OPTIONAL { ?earthquakeEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?earthquakeEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?earthquakeEvent kwgl-ont:numberOfDeaths ?numDeaths . }
  OPTIONAL { ?earthquakeEvent kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage . }
  OPTIONAL { ?earthquakeEvent kwgl-ont:hasHazardType ?hazardType . }
}
ORDER BY ?earthquakeEvent

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?damageProp
WHERE {
  { 
    ?hazard a kwgl-ont:HazardEvent .
    ?place kwgl-ont:impactedBy ?hazard ;
           ?damageProp ?value .
  }
  UNION
  {
    ?hazard a kwgl-ont:HazardEvent ;
            ?damageProp ?value .
  }
  FILTER(CONTAINS(LCASE(STR(?damageProp)), "damage"))
}
ORDER BY ?damageProp

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?place ?startDate ?endDate ?infraDamage ?tornadoDamage
WHERE {
  ?hazard rdf:type kwgl-ont:Tornado .
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  { ?hazard kwgl-ont:hasImpacted ?place } UNION { ?place kwgl-ont:impactedBy ?hazard }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDamage . }
}
ORDER BY ?hazard

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?type ?time ?property ?value
WHERE {
  ?hazard a ?type .
  ?type rdfs:subClassOf* kwg-ont:Hazard .

  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time . }
  OPTIONAL {
    ?hazard ?property ?value .
    FILTER(?property != kwg-ont:hasTemporalScope)
  }
}
ORDER BY ?hazard ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place rdfs:label ?name . }
}
ORDER BY ?place

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?healthAttr ?superType ?property ?value
WHERE {
  ?healthAttr rdfs:subClassOf* kwg-ont:PublicHealthObservableProperty .
  OPTIONAL { ?healthAttr rdfs:subClassOf ?superType . }
  OPTIONAL { ?healthAttr ?property ?value . }
}
ORDER BY ?healthAttr ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?place ?attribute
WHERE {
  ?obs a kwg-ont:CensusACS5YearEstimatesObservation ;
       sosa:observedProperty ?attribute ;
       sosa:hasFeatureOfInterest ?place .
  ?attribute a kwg-ont:CensusObservableProperty .
  ?place a kwg-ont:USCensusMSA .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?eqType ?total
WHERE {
  {
    SELECT (COUNT(DISTINCT ?t) AS ?total)
    WHERE { 
      ?t rdfs:subClassOf* kwg-ont:Earthquake .
    }
  }
  ?eqType rdfs:subClassOf* kwg-ont:Earthquake .
}
ORDER BY ?eqType

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?storm ?attribute ?value
WHERE {
  { ?storm a kwg-ont:StormTrack . }
  UNION
  { ?storm a kwg-ont:StormTracklet . }
  OPTIONAL { ?storm ?attribute ?value .
             FILTER(?attribute != rdf:type) }
}
ORDER BY ?storm ?attribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?floodClass ?property ?value
WHERE {
  ?floodClass rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  FILTER regex(str(?floodClass), "Flood", "i")
  OPTIONAL { ?floodClass ?property ?value . }
}
ORDER BY ?floodClass ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?climateAttribute
WHERE {
  ?climateAttribute rdfs:subClassOf* kwg-ont:ClimateObservableProperty .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardEvent ?impactProperty ?value
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?impactProperty ;
       sosa:hasFeatureOfInterest ?hazardEvent .
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?obs sosa:hasSimpleResult ?value . }
}
ORDER BY ?hazardEvent ?impactProperty

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?damageDetail
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?damageDetail ;
       sosa:hasFeatureOfInterest ?hazard .
  ?hazard a kwg-ont:Hazard .
  ?damageDetail rdfs:subClassOf* kwg-ont:ImpactObservableProperty .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricane
                ?attribute ?attrValue
                ?impactProperty ?impactValue
                ?impactTime
WHERE {
  # Hurricane events (NOAA hurricane hazard)
  ?hurricane a kwg-ont:NOAAHurricane .

  # Any attribute/property of the hurricane (e.g., geometry, temporal scope, etc.)
  OPTIONAL { ?hurricane ?attribute ?attrValue . }

  # Damage impact observations linked to this hurricane
  OPTIONAL {
    ?impactObs a kwg-ont:ImpactObservation ;
               sosa:observedProperty ?impactProperty ;
               sosa:hasFeatureOfInterest ?hurricane .
    OPTIONAL { ?impactObs sosa:hasSimpleResult ?impactValue . }
    OPTIONAL { ?impactObs sosa:phenomenonTime ?impactTime . }
  }
}
ORDER BY ?hurricane ?attribute ?impactProperty

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?tornado ?place ?damageProp ?value ?time
WHERE {
  ?tornado a kwg-ont:NOAATornado .
  OPTIONAL { ?tornado kwg-ont:hasTemporalScope ?time . }
  OPTIONAL { ?tornado kwg-ont:spatialRelation ?place . }

  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?tornado ;
       sosa:observedProperty ?damageProp ;
       sosa:hasSimpleResult ?value .

  ?damageProp rdfs:subClassOf kwg-ont:ImpactObservableProperty .
}
ORDER BY ?tornado ?damageProp

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazard
  ?typeLabel
  ?name
  ?startDate
  ?endDate
  ?deaths
  ?affectedArea
  ?cropDamage
  ?infraDamage
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }

  OPTIONAL {
    ?hazard kwgl-ont:hasHazardType ?type .
    OPTIONAL { ?type rdfs:label ?typeLabel . }
  }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?totalCount WHERE {
  { SELECT DISTINCT ?hazard WHERE { ?hazard rdf:type kwgl-ont:Earthquake . } }
  { SELECT (COUNT(DISTINCT ?h) AS ?totalCount) WHERE { ?h rdf:type kwgl-ont:Earthquake . } }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?attr ?totalCount WHERE {
  # List all distinct tornado‑related attributes linked to places
  {
    SELECT DISTINCT ?attr WHERE {
      ?place a kwgl-ont:Place .
      ?place ?attr ?value .
      FILTER regex(str(?attr), "Tornado", "i")
    }
  }
  # Compute the total number of such attributes
  {
    SELECT (COUNT(DISTINCT ?a) AS ?totalCount) WHERE {
      ?p a kwgl-ont:Place .
      ?p ?a ?v .
      FILTER regex(str(?a), "Tornado", "i")
    }
  }
}
ORDER BY ?attr

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?earthquakeEvent
  ?eventName
  ?startDate
  ?endDate
  ?numberOfDeaths
  ?affectedAreaInAcres
  ?damageToCrops
  ?damageToInfrastructure
  ?hazardType
WHERE {
  ?earthquakeEvent rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?earthquakeEvent kwgl-ont:hasName          ?eventName . }
  OPTIONAL { ?earthquakeEvent kwgl-ont:hasStartDate     ?startDate . }
  OPTIONAL { ?earthquakeEvent kwgl-ont:hasEndDate       ?endDate . }
  OPTIONAL { ?earthquakeEvent kwgl-ont:numberOfDeaths   ?numberOfDeaths . }
  OPTIONAL { ?earthquakeEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?earthquakeEvent kwgl-ont:damageToCropsInDollars     ?damageToCrops . }
  OPTIONAL { ?earthquakeEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }

  OPTIONAL {
    ?earthquakeEvent kwgl-ont:hasHazardType ?hazardType .
  }
}
ORDER BY ?earthquakeEvent

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?hurricaneAttribute ?value ?hurricaneEvent ?startDate ?endDate
WHERE {
  # places in the KG
  ?place a kwgl-ont:Place .

  # hurricane‑specific attributes that apply to a place
  OPTIONAL {
    ?place ?hurricaneAttribute ?value .
    FILTER ( CONTAINS(LCASE(STR(?hurricaneAttribute)), "hurricane") )
  }

  # hurricane events that impacted the place, with temporal data if present
  OPTIONAL {
    ?place kwgl-ont:impactedBy ?hurricaneEvent .
    ?hurricaneEvent a kwgl-ont:Hurricane .
    OPTIONAL { ?hurricaneEvent kwgl-ont:hasStartDate ?startDate . }
    OPTIONAL { ?hurricaneEvent kwgl-ont:hasEndDate   ?endDate   . }
  }
}
ORDER BY ?place ?hurricaneAttribute ?hurricaneEvent

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?name
WHERE {
  # any individual that is a (direct or indirect) subclass of geo:Feature
  ?place a ?type .
  ?type rdfs:subClassOf* geo:Feature .

  # retrieve its label or explicit name, if present
  OPTIONAL { ?place rdfs:label      ?name . }
  OPTIONAL { ?place kwg-ont:hasName ?name . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?healthAttribute
WHERE {
  # Any observation that records a health‑related observable property
  ?obs a sosa:Observation ;
       sosa:hasFeatureOfInterest ?place ;
       sosa:observedProperty   ?healthAttribute .

  # The place must be a geographical feature (e.g., administrative region, etc.)
  ?place a geo:Feature .

  # Keep only health‑related observable properties
  FILTER (
    EXISTS { ?healthAttribute a kwg-ont:PublicHealthObservableProperty } ||
    EXISTS { ?healthAttribute a kwg-ont:ImpactObservableProperty }      ||
    EXISTS { ?healthAttribute a kwg-ont:VulnerabilityObservableProperty }
  )
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?attribute ?value
WHERE {
  # Census observations with demographic attributes
  ?obs a kwg-ont:CensusACS5YearEstimatesObservation ;
       sosa:observedProperty ?attribute ;
       sosa:hasSimpleResult   ?value .

  # Attribute must be a census observable property (population, household units, etc.)
  ?attribute rdfs:subClassOf kwg-ont:CensusObservableProperty .

  # Link observations to their geographic feature of interest
  ?collection a kwg-ont:CensusACS5YearEstimatesObservationCollection ;
              sosa:hasMember   ?obs ;
              sosa:hasFeatureOfInterest ?place .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?earthquake ?totalCount WHERE {
  { SELECT (COUNT(?e) AS ?totalCount)
    WHERE { ?e a kwg-ont:Earthquake . }
  }
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?storm ?attribute ?value ?place
WHERE {
  # Storm‑specific hazard instances
  ?storm a kwg-ont:StormTrack .

  # Retrieve the key storm attributes (temporal scope, geometry, default geometry,
  # and any linked tracklet)
  VALUES ?attribute { 
    kwg-ont:hasTemporalScope 
    kwg-ont:hasGeometry 
    geo:hasDefaultGeometry 
    kwg-ont:hasStormTracklet
  }
  OPTIONAL { ?storm ?attribute ?value }

  # Relate the storm to the geographical places it affects (via spatial relation)
  OPTIONAL { ?storm kwg-ont:spatialRelation ?place .
            FILTER(isIRI(?place) && ( ?place a geo:Feature || ?place a kwg-ont:AdministrativeRegion )) }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?hazardClass ?place ?geometry ?temporalScope
WHERE {
  ?hazard a ?hazardClass .
  FILTER ( ?hazardClass = kwg-ont:NOAAFlood ||
           ?hazardClass rdfs:subClassOf* kwg-ont:NOAAFlood )

  OPTIONAL { ?hazard kwg-ont:hasGeometry      ?geometry . }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalScope . }
  OPTIONAL {
    ?hazard kwg-ont:spatialRelation ?place .
    FILTER ( ?place a geo:Feature )
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?earthquake 
       (rdf:type(?earthquake) AS ?type)   # will be kwg-ont:Earthquake
       ?temporalScope
       ?geometry
WHERE {
  ?earthquake a kwg-ont:Earthquake .

  OPTIONAL { ?earthquake kwg-ont:hasTemporalScope ?temporalScope . }
  OPTIONAL { 
    # geometry may be stored via hasGeometry or the default geometry of the feature
    { ?earthquake kwg-ont:hasGeometry ?geometry . } UNION
    { ?earthquake geo:hasDefaultGeometry ?geometry . }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardEvent ?impactProperty ?value
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazardEvent ;
       sosa:observedProperty    ?impactProperty ;
       sosa:hasSimpleResult    ?value .

  ?hazardEvent a kwg-ont:NOAAHazardEvent .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hurricane
       ?geometry
       ?temporalScope
       ?place
       ?impactProperty
       ?impactValue
       ?impactTime
WHERE {
  # Hurricane events (NOAA hurricane hazard)
  ?hurricane a kwg-ont:NOAAHurricane .

  # Geometry of the hurricane (if present)
  OPTIONAL { ?hurricane kwg-ont:hasGeometry ?geometry . }

  # Temporal scope of the hurricane (if present)
  OPTIONAL { ?hurricane kwg-ont:hasTemporalScope ?temporalScope . }

  # Geographical place related to the hurricane via spatial relation
  OPTIONAL {
    ?hurricane kwg-ont:spatialRelation ?place .
    FILTER EXISTS { ?place a geo:Feature }
  }

  # Damage impact observations linked to this hurricane
  OPTIONAL {
    ?impactObs a kwg-ont:ImpactObservation ;
               sosa:hasFeatureOfInterest ?hurricane ;
               sosa:observedProperty   ?impactProperty ;
               sosa:hasSimpleResult    ?impactValue .
    OPTIONAL { ?impactObs sosa:phenomenonTime ?impactTime . }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?hazard ?place ?damageProp ?value ?time
WHERE {
  # tornado‑specific hazard
  ?hazard a kwg-ont:NOAATornado .

  # spatial relation to a geographic place (e.g., an AdministrativeRegion or any geo:Feature)
  ?hazard kwg-ont:spatialRelation ?place .
  ?place a geo:Feature .

  # temporal extent of the hazard (optional – include if present)
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time . }

  # damage observations linked to the tornado hazard
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazard ;
       sosa:observedProperty ?damageProp ;
       sosa:hasSimpleResult ?value .

  # ensure the observed property is a kind of impact (damage) observable
  FILTER EXISTS { ?damageProp rdfs:subClassOf kwg-ont:ImpactObservableProperty . }
}
ORDER BY ?hazard ?place ?damageProp

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?publication ?doiValue
WHERE {
  ?publication a coresr-ont:Publication .
  OPTIONAL {
    ?publication coresr-ont:hasIdentifier ?doi .
    ?doi coresr-ont:doiAsString ?doiValue .
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?university ?city
WHERE {
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?loc .
  ?loc coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?author ?advisor
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
  ?advisor a coresr-ont:Advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?pubType ?typeLabel WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasPublicationType ?pubType .
  OPTIONAL { ?pubType coresr-ont:typeAsString ?typeLabel . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?agent ?department
WHERE {
  ?agent a coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?fieldOfStudy ?publication ?title
WHERE {
  # each field of study
  ?fieldOfStudy a coresr-ont:FieldOfStudy .

  # publications linked to the field
  ?publication a coresr-ont:Publication ;
               coresr-ont:associatedFieldOfStudy ?fieldOfStudy .

  # optional title of the publication
  OPTIONAL { ?publication coresr-ont:hasTitle ?title . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?city ?college WHERE {
  ?univ a coresr-ont:University .
  ?college a coresr-ont:College ;
           coresr-ont:partOf ?univ .
  ?univ coresr-ont:locatedAt ?loc .
  ?loc coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pub ?title
WHERE {
  {
    ?pub a coresr-ont:Publication .
    OPTIONAL { ?pub coresr-ont:hasTitle ?title . }
    ?pub coresr-ont:submittedBy ?role .
    ?role a coresr-ont:Author ;
          coresr-ont:isPerformedBy ?agent .
    ?agent coresr-ont:associatedWith ?dept .
  } UNION {
    ?pub a coresr-ont:Publication .
    OPTIONAL { ?pub coresr-ont:hasTitle ?title . }
    ?pub coresr-ont:hasContributor ?role .
    ?role a coresr-ont:Contributor ;
          coresr-ont:isPerformedBy ?agent .
    ?agent coresr-ont:associatedWith ?dept .
  }
}
GROUP BY ?pub ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?type (AVG(?duration) AS ?averageDuration)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:hasPublicationType ?ptype ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate .
  ?ptype coresr-ont:typeAsString ?type .
  BIND (xsd:dateTime(?pubDate) - xsd:dateTime(?subDate) AS ?duration)
}
GROUP BY ?type
ORDER BY DESC(?averageDuration)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author ?field
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor ;
          coresr-ont:submits ?pub .
  ?pub   coresr-ont:associatedFieldOfStudy ?field .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .

  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?ci .
    ?ci a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)
LIMIT 1

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?author ?firstName ?familyName
WHERE {
  ?author a coress-ont:Author .
  OPTIONAL { ?author coress-ont:hasFirstName ?firstName . }
  OPTIONAL { ?author coress-ont:hasFamilyName ?familyName . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?university ?city WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author ?authorName ?advisor WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor .
  OPTIONAL {
    ?author coress-ont:hasFirstName ?fn ;
            coress-ont:hasFamilyName ?ln .
    BIND(CONCAT(?fn, " ", ?ln) AS ?authorName)
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?publication ?type
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasPublicationType ?type .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?agent ?department
WHERE {
  { 
    ?agent a coress-ont:Agent ;
           coress-ont:worksInDepartment ?department .
  }
  UNION
  {
    ?department a coress-ont:Department ;
                coress-ont:hasAgent ?agent .
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?university ?pubCount WHERE {
  {
    SELECT ?state ?university (COUNT(?pub) AS ?pubCount)
    WHERE {
      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?dept .
      ?dept  coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt)
    WHERE {
      {
        SELECT ?state ?university (COUNT(?pub) AS ?cnt)
        WHERE {
          ?pub a coress-ont:Publication .
          ?pub coress-ont:submittedBy ?author .
          ?author coress-ont:isPerformedBy ?agent .
          ?agent coress-ont:worksInDepartment ?dept .
          ?dept  coress-ont:departmentOf ?college .
          ?college coress-ont:collegeOf ?university .
          ?university coress-ont:atState ?state .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  FILTER(?pubCount = ?maxCnt)
}
ORDER BY ?state

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?pub ?title WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:hasTitle ?title .
  ?author a coress-ont:Author ;
          coress-ont:isPerformedBy ?agent .
  ?pub coress-ont:submittedBy ?author .
  ?agent coress-ont:worksInDepartment ?dept .
}
GROUP BY ?pub ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?pubType (AVG(?duration) AS ?avgDuration)
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:hasPublicationType ?pubType ;
       coress-ont:dateOfSubmission ?subDate ;
       coress-ont:dateOfPublication ?pubDate .
  BIND( (?pubDate - ?subDate) AS ?duration )
}
GROUP BY ?pubType
ORDER BY DESC(?avgDuration)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?author ?advisor ?fieldOfStudy
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor ;
          coress-ont:submits ?pub .

  ?pub   coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coress-ont:Agent ;
         coress-ont:worksInDepartment ?department .
  OPTIONAL { ?agent coress-ont:hasFamilyName ?familyName . }
  FILTER (!BOUND(?familyName))
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)
LIMIT 1

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?type ?property ?value ?time
WHERE {
  ?hazard a ?type .
  ?type rdfs:subClassOf* kwg-ont:Hazard .
  OPTIONAL { ?hazard ?property ?value . FILTER (!isBlank(?value)) }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time . }
}
ORDER BY ?hazard

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?healthProperty
WHERE {
  ?obsColl a kwg-ont:PublicHealthObservationCollection ;
           sosa:hasFeatureOfInterest ?place ;
           sosa:hasMember ?obs .
  ?obs a kwg-ont:PublicHealthObservation ;
       sosa:observedProperty ?healthProperty .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquake ?totalCount
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  { SELECT (COUNT(DISTINCT ?e) AS ?totalCount)
    WHERE { ?e a kwg-ont:Earthquake . }
  }
}
ORDER BY ?earthquake

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?prop (?total AS ?totalAttributes)
WHERE {
  { SELECT (COUNT(DISTINCT ?p) AS ?total) WHERE {
      ?t a kwg-ont:NOAATornado .
      ?t ?p ?v .
      FILTER(?p != rdf:type)
    }
  }
  ?t a kwg-ont:NOAATornado ;
     ?prop ?val .
  FILTER(?prop != rdf:type)
}
ORDER BY ?prop

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?place ?property ?value
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?hazard kwg-ont:sfWithin ?place . }
  OPTIONAL { ?hazard ?property ?value .
             FILTER(?property NOT IN (rdf:type, rdfs:label)) }
}
ORDER BY ?hazard ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?flood ?place ?property ?value
WHERE {
  ?flood a ?type .
  ?type rdfs:subClassOf* kwg-ont:NOAAFlood .
  OPTIONAL { ?flood kwg-ont:sfWithin|kwg-ont:spatialRelation ?place . }
  OPTIONAL { ?flood ?property ?value . FILTER (!isBlank(?value)) }
}
ORDER BY ?flood

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?property ?mean ?anomaly ?rank
WHERE {
  ?obsColl a kwg-ont:ClimateDivisionObservationCollection ;
           sosa:hasFeatureOfInterest ?place ;
           sosa:hasMember ?propColl .
  ?propColl a kwg-ont:ClimateDivisionPropertyObservationCollection ;
            sosa:observedProperty ?property ;
            sosa:hasMember ?obs .
  ?obs sosa:hasResult ?result .
  OPTIONAL { ?result kwg-ont:mean ?mean . }
  OPTIONAL { ?result kwg-ont:anomaly ?anomaly . }
  OPTIONAL { ?result kwg-ont:rank ?rank . }
}
ORDER BY ?place ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?earthquake ?property ?value ?type
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  OPTIONAL { ?earthquake ?property ?value . FILTER(?property != rdf:type) }
  OPTIONAL { ?earthquake a ?type . FILTER(?type != kwg-ont:Earthquake && ?type != rdf:Property) }
}
ORDER BY ?earthquake ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardEvent ?impactProperty ?result
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
  OPTIONAL {
    ?obs a kwg-ont:ImpactObservation ;
         sosa:observedProperty ?impactProperty ;
         sosa:hasFeatureOfInterest ?hazardEvent .
    OPTIONAL { ?obs sosa:hasResult ?result . }
  }
}
ORDER BY ?hazardEvent ?impactProperty

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?damageDetail
WHERE {
  ?hazard a kwg-ont:Hazard .
  ?obsColl a kwg-ont:ImpactObservationCollection ;
           sosa:hasFeatureOfInterest ?hazard ;
           sosa:hasMember ?obs .
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?damageDetail .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricane ?place ?tempScope
                ?magProp ?magVal ?magTime
                ?impProp ?impVal ?impTime
WHERE {
  # Hurricanes
  ?hurricane a kwg-ont:NOAAHurricane .

  # Temporal scope of the hurricane (if any)
  OPTIONAL { ?hurricane kwg-ont:hasTemporalScope ?tempScope . }

  # Geographical place related to the hurricane (administrative region or S2 cell)
  OPTIONAL {
    ?hurricane kwg-ont:sfWithin|kwg-ont:spatialRelation ?place .
    FILTER( ?place a kwg-ont:AdministrativeRegion_3 || ?place a kwg-ont:S2Cell )
  }

  # Magnitude (e.g., wind speed, pressure) observations linked to the hurricane
  OPTIONAL {
    ?magColl a kwg-ont:MagnitudeObservationCollection ;
             sosa:hasFeatureOfInterest ?hurricane ;
             sosa:hasMember ?magObs .
    ?magObs sosa:observedProperty ?magProp ;
            sosa:hasResult ?magRes .
    OPTIONAL { ?magRes sosa:hasSimpleResult ?magVal . }
    OPTIONAL { ?magObs sosa:phenomenonTime ?magTime . }
  }

  # Impact details (e.g., damage, injuries) linked to the hurricane
  OPTIONAL {
    ?impColl a kwg-ont:ImpactObservationCollection ;
             sosa:hasFeatureOfInterest ?hurricane ;
             sosa:hasMember ?impObs .
    ?impObs sosa:observedProperty ?impProp ;
            sosa:hasResult ?impRes .
    OPTIONAL { ?impRes sosa:hasSimpleResult ?impVal . }
    OPTIONAL { ?impObs sosa:phenomenonTime ?impTime . }
  }
}
ORDER BY ?hurricane

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?tornado ?property ?result ?place ?time
WHERE {
  ?tornado a kwg-ont:NOAATornado .
  OPTIONAL { ?tornado kwg-ont:sfWithin ?place . }
  OPTIONAL { ?tornado kwg-ont:hasTemporalScope ?time . }

  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?property ;
       sosa:hasResult ?result ;
       sosa:hasFeatureOfInterest ?tornado .

  FILTER(?property IN (
    kwgr:impactObservableProperty.damageCrop,
    kwgr:impactObservableProperty.damageProperty,
    kwgr:impactObservableProperty.deathDirect,
    kwgr:impactObservableProperty.deathIndirect,
    kwgr:impactObservableProperty.injuryDirect,
    kwgr:impactObservableProperty.injuryIndirect
  ))
}
ORDER BY ?tornado ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?place ?time ?damageProp ?damageLabel
WHERE {
  # storm‑specific hazards (subclasses of NOAAHazardEvent)
  ?hazard a kwg-ont:NOAAHazardEvent .

  # geographic location of the hazard
  ?hazard kwg-ont:sfWithin ?place .

  # temporal extent of the hazard
  ?hazard kwg-ont:hasTemporalScope ?time .

  # impact observations linked to this hazard
  ?col a kwg-ont:ImpactObservationCollection ;
       sosa:hasFeatureOfInterest ?hazard ;
       sosa:hasMember ?obs .
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?damageProp .

  OPTIONAL { ?damageProp rdfs:label ?damageLabel }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?type ?property ?value ?time
WHERE {
  ?hazard a ?type .
  ?type rdfs:subClassOf* kwg-ont:Hazard .

  OPTIONAL { 
    ?hazard ?property ?value .
    FILTER(?property != rdf:type)
  }

  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?temporal .
    BIND(?temporal AS ?time)
  }
}
ORDER BY ?hazard

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place rdfs:label ?name . }
  OPTIONAL { ?place kwg-ont:hasName ?name . }
}
ORDER BY ?place

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?healthAttribute ?value
WHERE {
  ?obs a kwg-ont:PublicHealthObservation ;
       sosa:hasFeatureOfInterest ?place ;
       sosa:observedProperty ?healthAttribute .
  OPTIONAL { ?obs sosa:hasSimpleResult ?value . }
}
ORDER BY ?place ?healthAttribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?earthquakeHazard ?totalCount
WHERE {
  { SELECT (COUNT(DISTINCT ?h) AS ?totalCount)
    WHERE { ?h rdfs:subClassOf* kwg-ont:Earthquake . }
  }
  ?earthquakeHazard rdfs:subClassOf* kwg-ont:Earthquake .
}
ORDER BY ?earthquakeHazard

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?attr ?value
WHERE {
  ?obs a kwg-ont:StormTrackObservation ;
       sosa:observedProperty ?attr ;
       sosa:hasFeatureOfInterest ?place .
  ?attr rdfs:subClassOf* kwg-ont:StormTrackObservableProperty .
  OPTIONAL { ?obs sosa:hasSimpleResult ?value . }
  ?place a geo:Feature .
}
ORDER BY ?place ?attr

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?flood ?geom ?temporalScope ?place
WHERE {
  ?flood a kwg-ont:NOAAFlood .
  OPTIONAL { ?flood geo:hasGeometry ?geom . }
  OPTIONAL { ?flood kwg-ont:hasTemporalScope ?temporalScope . }
  OPTIONAL {
    ?flood kwg-ont:spatialRelation ?place .
    FILTER(?place != ?flood)
  }
}
ORDER BY ?flood

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?damageDetail
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazard ;
       sosa:observedProperty ?damageDetail .
  ?hazard a kwg-ont:NOAAHazardEvent .
  ?damageDetail rdfs:subClassOf* kwg-ont:ImpactObservableProperty .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?entity ?property ?value ?time
WHERE {
  { # Hurricane hazard attributes linked to a place
    ?h a kwg-ont:NOAAHurricane .
    OPTIONAL { ?h geo:hasGeometry ?geom . }
    OPTIONAL { ?h kwg-ont:spatialRelation ?place . }
    FILTER (bound(?geom) || bound(?place))
    ?entity ?property ?value .
    FILTER (?entity = ?h)
  }
  UNION
  { # Damage impact details for hurricanes with temporal data
    ?impact a kwg-ont:ImpactObservation ;
            sosa:hasFeatureOfInterest ?h ;
            sosa:observedProperty ?property .
    ?h a kwg-ont:NOAAHurricane .
    OPTIONAL { ?impact sosa:hasSimpleResult ?value . }
    OPTIONAL { ?impact sosa:phenomenonTime ?time . }
    BIND(?impact AS ?entity)
  }
}
ORDER BY ?entity ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazard ?observation ?property ?value ?temporalScope ?geometry
WHERE {
  # Tornado‑specific hazard
  ?hazard a kwg-ont:NOAATornado .

  # Impact observation linked to the tornado hazard
  ?observation sosa:hasFeatureOfInterest ?hazard ;
               sosa:observedProperty   ?property ;
               sosa:hasSimpleResult    ?value .

  # Property must be a damage‑related impact observable property
  ?property rdfs:subClassOf* kwg-ont:ImpactObservableProperty .

  # Optional temporal extent of the hazard
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?temporalScope .
    ?temporalScope time:hasBeginning ?begin ;
                    time:hasEnd       ?end .
  }

  # Optional geometry/location of the hazard
  OPTIONAL { ?hazard geo:hasGeometry ?geometry . }
}
ORDER BY ?hazard ?observation

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazard ?name ?type ?startDate ?endDate ?deaths ?damageInfrastructure ?damageCrops ?affectedArea
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?name ?percentDiabetic ?percentObese ?percentBelowPovertyLine
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?percentDiabetic . }
  OPTIONAL { ?place kwgl-ont:percentObese ?percentObese . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?percentBelowPovertyLine . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?attribute ?value
WHERE {
  VALUES ?attribute {
    kwgl-ont:hasPopulation
    kwgl-ont:hasNumberOfHouseHolds
    kwgl-ont:percentBelowPovertyLine
    kwgl-ont:percentDiabetic
    kwgl-ont:percentObese
  }
  ?place ?attribute ?value .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazardType (COUNT(?event) AS ?count)
WHERE {
  ?event a kwgl-ont:Earthquake ;
         kwgl-ont:hasHazardType ?hazardType .
}
GROUP BY ?hazardType

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?attribute ?totalCount
WHERE {
  {
    SELECT DISTINCT ?attribute (COUNT(DISTINCT ?attribute) AS ?totalCount)
    WHERE {
      ?place a kwgl-ont:Place .
      ?place ?attribute ?value .
      FILTER regex(str(?attribute), "Tornado", "i")
    }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?attrName ?value WHERE {
  ?place a kwgl-ont:Place .
  VALUES (?pred ?attrName) {
    (kwgl-ont:numberOfStormSurgesImpactingPlace      "numberOfStormSurgesImpactingPlace")
    (kwgl-ont:dollarDamageOfStormSurgesImpactingPlace "dollarDamageOfStormSurgesImpactingPlace")
    (kwgl-ont:numberOfHurricanesImpactingPlace       "numberOfHurricanesImpactingPlace")
    (kwgl-ont:dollarDamageOfHurricanesImpactingPlace  "dollarDamageOfHurricanesImpactingPlace")
    (kwgl-ont:numberOfTornadoesImpactingPlace        "numberOfTornadoesImpactingPlace")
    (kwgl-ont:dollarDamageOfTornadoesImpactingPlace   "dollarDamageOfTornadoesImpactingPlace")
  }
  ?place ?pred ?value .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?place ?placeName ?numFloods ?damageFloods
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType kwglr:flood ;
         kwgl-ont:impactedBy ?place .

  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?numFloods . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damageFloods . }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazard
       ?name
       ?startDate
       ?endDate
       ?deaths
       ?damageToInfrastructure
       ?affectedArea
       ?type
WHERE {
  ?hazard a kwgl-ont:Earthquake .
  OPTIONAL { ?hazard kwgl-ont:hasName               ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate          ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate            ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths        ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres   ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType        ?type .
             FILTER(?type = kwglr:earthquake) }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event ?name ?deaths ?affectedArea ?cropDamage ?infraDamage
WHERE {
  ?event a kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:hasName ?name . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT 
       ?hurricane ?hName
       ?place ?pName
       ?startDate ?endDate
       ?numDeaths
       ?damageInfra
       ?damageCrops
       ?affectedArea
       ?damageProp ?dollarDamagePlace
WHERE {
  # Hurricane events
  ?hurricane a kwgl-ont:Hurricane .
  OPTIONAL { ?hurricane kwgl-ont:hasName ?hName . }
  OPTIONAL { ?hurricane kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hurricane kwgl-ont:hasEndDate   ?endDate . }
  OPTIONAL { ?hurricane kwgl-ont:numberOfDeaths ?numDeaths . }

  # Damage impact details on the hurricane itself
  OPTIONAL { ?hurricane kwgl-ont:damageToInfrastructureInDollars ?damageInfra . }
  OPTIONAL { ?hurricane kwgl-ont:damageToCropsInDollars          ?damageCrops . }
  OPTIONAL { ?hurricane kwgl-ont:affectedAreaInAcres            ?affectedArea . }

  # Places impacted by the hurricane
  OPTIONAL {
    ?hurricane kwgl-ont:impactedBy ?place .
    ?place a kwgl-ont:Place .
    OPTIONAL { ?place kwgl-ont:hasName ?pName . }

    # Hurricane‑specific damage attributes on the place (any year)
    OPTIONAL {
      ?place ?damageProp ?dollarDamagePlace .
      FILTER( STRSTARTS(STR(?damageProp), STR(k wgl-ont:dollarDamageOfHurricanesImpactingPlace)) )
    }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazard ?hazardName ?place ?placeName ?startDate ?endDate ?damageInfra ?damageCrops ?deaths ?dollarDamage
WHERE {
  ?hazard a kwgl-ont:Tornado .
  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  ?hazard kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamage . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?hazardName ?place ?placeName ?startDate ?endDate
       ?damageToInfrastructure ?damageToCrops
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?type ;
          kwgl-ont:impactedBy   ?place .

  FILTER ( ?type IN (kwglr:hurricane,
                     kwglr:tornado,
                     kwglr:tropicalStorm,
                     kwglr:tropicalDepression,
                     kwglr:stormSurgeTide,
                     kwglr:highWind,
                     kwglr:strongWind) )

  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?place  kwgl-ont:hasName ?placeName . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate   ?endDate . }

  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars           ?damageToCrops . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place kwg-ont:hasName ?name . }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?healthConcern WHERE {
  ?obs a sosa:Observation ;
       sosa:observedProperty ?healthConcern ;
       sosa:hasFeatureOfInterest ?place .
  ?place a geo:Feature .
  FILTER ( 
    ?healthConcern a kwg-ont:PublicHealthObservableProperty ||
    ?healthConcern a kwg-ont:ImpactObservableProperty ||
    ?healthConcern a kwg-ont:VulnerabilityObservableProperty
  )
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?attribute
WHERE {
  ?attribute a kwg-ont:CensusObservableProperty .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?earthquake ?total
WHERE {
  { SELECT (COUNT(?e) AS ?total)
    WHERE { ?e a kwg-ont:Earthquake }
  }
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?attribute ?value
WHERE {
  { # StormTrack observations
    ?obs a kwg-ont:StormTrackObservation ;
         sosa:observedProperty ?attribute ;
         sosa:hasResult          ?value ;
         sosa:hasFeatureOfInterest ?storm .
    ?storm a kwg-ont:StormTrack .
    ?storm kwg-ont:spatialRelation ?place .
    FILTER EXISTS { ?attribute a kwg-ont:StormTrackObservableProperty . }
  } UNION {
    # StormTracklet observations
    ?obs a kwg-ont:StormTrackletObservation ;
         sosa:observedProperty ?attribute ;
         sosa:hasResult          ?value ;
         sosa:hasFeatureOfInterest ?tracklet .
    ?tracklet a kwg-ont:StormTracklet .
    ?tracklet kwg-ont:spatialRelation ?place .
    FILTER EXISTS { ?attribute a kwg-ont:StormTrackletObservableProperty . }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazard ?type ?geometry ?temporalScope ?place
WHERE {
  VALUES ?type { kwg-ont:NOAAFlood kwg-ont:NOAAFlashFlood kwg-ont:NOAALakeshoreFlood }
  ?hazard a ?type .

  OPTIONAL { ?hazard kwg-ont:hasGeometry      ?geometry . }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalScope . }

  OPTIONAL {
    ?hazard kwg-ont:spatialRelation ?place .
    FILTER ( ?place a geo:Feature )
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?climateAttribute WHERE {
  ?obs a kwg-ont:ClimateObservation ;
       sosa:observedProperty ?climateAttribute ;
       sosa:hasFeatureOfInterest ?place .
  ?place a geo:Feature .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?earthquake ?type ?temporalScope ?geometry
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  BIND(kwg-ont:Earthquake AS ?type)

  OPTIONAL { ?earthquake kwg-ont:hasTemporalScope ?temporalScope . }
  OPTIONAL { ?earthquake kwg-ont:hasGeometry     ?geometry . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?hazardEvent ?impactObservableProperty
WHERE {
  ?collection a kwg-ont:ImpactObservationCollection ;
              sosa:hasFeatureOfInterest ?hazardEvent ;
              sosa:hasMember ?observation .

  ?observation a kwg-ont:ImpactObservation ;
               sosa:observedProperty ?impactObservableProperty .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hurricane
       ?temporalScope
       ?geometry
       ?place
       ?impactObs
       ?impactProp
       ?impactTemporal
WHERE {
  # Hurricane events (hazard)
  ?hurricane a kwg-ont:NOAAHurricane .

  OPTIONAL { ?hurricane kwg-ont:hasTemporalScope   ?temporalScope . }
  OPTIONAL { ?hurricane kwg-ont:hasGeometry        ?geometry      . }

  # Geographical place related to the hurricane
  OPTIONAL {
    ?hurricane (kwg-ont:sfWithin|kwg-ont:spatialRelation) ?place .
    FILTER( ?place a geo:Feature )
  }

  # Damage impact observations linked via an observation collection
  OPTIONAL {
    ?impactCol a kwg-ont:ImpactObservationCollection ;
               sosa:hasFeatureOfInterest ?hurricane ;
               sosa:hasMember          ?impactObs .

    OPTIONAL { ?impactCol sosa:phenomenonTime ?impactTemporal . }

    ?impactObs a kwg-ont:ImpactObservation ;
               sosa:observedProperty   ?impactProp .
  }
}
ORDER BY ?hurricane

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?tornadoHazard ?place ?damageProperty ?damageResult ?temporalScope
WHERE {
  # Tornado‑specific hazard
  ?tornadoHazard a kwg-ont:NOAATornado .

  # Hazard related to a geographical place (e.g., an administrative region)
  ?tornadoHazard kwg-ont:sfWithin ?place .
  ?place a kwg-ont:AdministrativeRegion .

  # Damage details recorded as impact observations linked to the tornado hazard
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?tornadoHazard ;
       sosa:observedProperty ?damageProperty ;
       sosa:result ?damageResult .

  # Optional temporal extent of the hazard
  OPTIONAL { ?tornadoHazard kwg-ont:hasTemporalScope ?temporalScope . }
}
ORDER BY ?tornadoHazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?hazard ?type ?property ?value
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { 
    ?hazard a ?type .
    FILTER(?type != kwg-ont:Hazard) 
  }
  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?value .
  }
  OPTIONAL {
    ?hazard ?property ?val .
    FILTER(?property NOT IN (rdf:type, rdfs:label))
    BIND(?val AS ?value)
  }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?place ?entity ?prop ?val
WHERE {
  ?place a kwg-ont:AdministrativeRegion_3 .
  { 
    ?entity a kwg-ont:Hospital ;
            kwg-ont:sfWithin ?place .
  } UNION {
    ?entity a kwg-ont:Pharmacy ;
            kwg-ont:sfWithin ?place .
  } UNION {
    ?entity a kwg-ont:PublicHealthDepartment ;
            kwg-ont:sfWithin ?place .
  }
  ?entity ?prop ?val .
  FILTER(?prop NOT IN (rdf:type, rdfs:label))
}
ORDER BY ?place ?entity ?prop

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquake (COUNT(DISTINCT ?e) AS ?totalCount)
WHERE {
  { SELECT ?e WHERE { ?e a kwg-ont:Earthquake . } }
  ?earthquake a kwg-ont:Earthquake .
}
GROUP BY ?earthquake
ORDER BY ?earthquake

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?property ?totalCount
WHERE {
  # Retrieve each distinct property used on a tornado hazard
  { SELECT DISTINCT ?property WHERE {
      ?tornado rdf:type kwg-ont:NOAATornado .
      ?tornado ?property ?value .
    }
  }
  # Compute the total number of distinct tornado‑specific properties
  { SELECT (COUNT(DISTINCT ?p) AS ?totalCount) WHERE {
      ?t rdf:type kwg-ont:NOAATornado .
      ?t ?p ?v .
    }
  }
}
ORDER BY ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?stormClass ?property ?value
WHERE {
  ?stormClass rdfs:subClassOf kwg-ont:NOAAHazardEvent .
  FILTER regex(str(?stormClass), "(Storm|Hurricane|Tropical)", "i") .
  OPTIONAL { ?stormClass ?property ?value . }
}
ORDER BY ?stormClass

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?climateProperty
WHERE {
  ?obsColl a kwg-ont:ClimateDivisionObservationCollection ;
           sosa:hasFeatureOfInterest ?place ;
           sosa:hasMember ?propObsColl .

  ?propObsColl a kwg-ont:ClimateDivisionPropertyObservationCollection ;
               sosa:hasMember ?climateObs .

  ?climateObs sosa:observedProperty ?climateProperty .
}
ORDER BY ?place ?climateProperty

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardEvent ?impactProperty ?result
WHERE {
  ?hazardEvent a kwg-ont:Hazard .
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?impactProperty ;
       sosa:hasFeatureOfInterest ?hazardEvent ;
       sosa:hasResult ?result .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazard ?property
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       kwg-ont:affectedBy ?hazard ;
       sosa:observedProperty ?property .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hurricane ?attr ?attrValue ?impactProp ?impactResult ?time
WHERE {
  # Hurricane events
  ?hurricane a kwg-ont:NOAAHurricane .

  # Relate hurricane to a geographic place (administrative region or S2 cell)
  { ?hurricane kwg-ont:sfWithin ?place . }
  UNION
  { ?hurricane kwg-ont:spatialRelation ?place . }
  FILTER EXISTS { ?place a kwg-ont:AdministrativeRegion }

  # Hurricane‑specific attributes (exclude type triples)
  OPTIONAL {
    ?hurricane ?attr ?attrValue .
    FILTER (?attr NOT IN (rdf:type, rdfs:label))
  }

  # Damage impact observations linked to the hurricane
  OPTIONAL {
    ?impactObs a kwg-ont:ImpactObservation ;
               sosa:observedProperty ?impactProp ;
               sosa:hasFeatureOfInterest ?hurricane ;
               sosa:result ?impactResult .

    # Temporal information for the impact observation, if available
    OPTIONAL {
      ?coll a kwg-ont:ImpactObservationCollection ;
            sosa:hasMember ?impactObs ;
            sosa:phenomenonTime ?time .
    }
  }
}
ORDER BY ?hurricane ?attr

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?tornado ?place ?damageProp ?damageValue ?time
WHERE {
  ?tornado a kwg-ont:NOAATornado .
  ?tornado kwg-ont:sfWithin ?place .
  OPTIONAL { ?tornado kwg-ont:hasTemporalScope ?time . }

  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?tornado ;
       sosa:observedProperty ?damageProp ;
       sosa:hasResult ?damageValue .
}
ORDER BY ?tornado ?place ?damageProp

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?place ?hazardType ?damageProp ?value
WHERE {
  # Impact observations that record damage details
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?damageProp ;
       sosa:hasResult ?value ;
       sosa:hasFeatureOfInterest ?hazard .

  # Restrict to storm‑specific hazards (e.g., hurricanes, tropical storms/depressions)
  ?hazard a ?hazardType .
  VALUES ?hazardType {
    kwg-ont:NOAAHurricane
    kwg-ont:NOAATropicalStorm
    kwg-ont:NOAATropicalDepression
    kwg-ont:NOAAWind
  }

  # The hazard must be related to a geographic place (any region)
  ?hazard kwg-ont:sfWithin ?place .

  # Temporal filter – hazards occurring within the desired time window
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?time .
    FILTER ( ?time >= "2020-01-01"^^xsd:date && ?time <= "2020-12-31"^^xsd:date )
  }
}
ORDER BY ?place ?hazardType ?damageProp

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?name ?type ?startDate ?endDate ?deaths ?affectedArea
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
}
ORDER BY ?startDate

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?name .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name ?percentDiabetic ?percentObese ?percentBelowPovertyLine
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?percentDiabetic . }
  OPTIONAL { ?place kwgl-ont:percentObese ?percentObese . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?percentBelowPovertyLine . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?property ?value
WHERE {
  ?place a kwgl-ont:Place .
  VALUES ?property { 
    kwgl-ont:hasPopulation 
    kwgl-ont:hasNumberOfHouseHolds 
    kwgl-ont:percentBelowPovertyLine 
    kwgl-ont:percentDiabetic 
    kwgl-ont:percentObese 
  }
  ?place ?property ?value .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?earthquakeEvent ?name (SELECT (COUNT(?e) AS ?totalEarthquakes)
                               WHERE { ?e a kwgl-ont:Earthquake })
WHERE {
  ?earthquakeEvent a kwgl-ont:Earthquake .
  OPTIONAL { ?earthquakeEvent kwgl-ont:hasName ?name }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?earthquake
                ?name
                ?startDate
                ?endDate
                ?deaths
                ?affectedArea
                ?cropDamage
                ?infraDamage
                ?type
WHERE {
  # Instances of the Earthquake hazard class
  ?earthquake a kwgl-ont:Earthquake .

  # Optional details about each earthquake event
  OPTIONAL { ?earthquake kwgl-ont:hasName            ?name . }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate       ?startDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate         ?endDate . }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths     ?deaths . }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars   ?cropDamage . }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }

  # The hazard type associated with the event (should be kwglr:earthquake)
  OPTIONAL { ?earthquake kwgl-ont:hasHazardType ?type . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazardEvent ?name ?deaths ?affectedArea ?cropDamage ?infraDamage
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?entity ?property ?value ?startDate ?endDate
WHERE {
  # Hurricane event attributes (e.g., dates, deaths, damage)
  {
    ?h a kwgl-ont:Hurricane .
    BIND(?h AS ?entity)

    OPTIONAL { ?h kwgl-ont:hasStartDate ?startDate }
    OPTIONAL { ?h kwgl-ont:hasEndDate   ?endDate }

    ?entity ?property ?value .
    FILTER EXISTS { ?property a owl:DatatypeProperty }
  }
  UNION
  # Place‑level attributes that are linked to a Hurricane (e.g., dollar damage, counts)
  {
    ?place a kwgl-ont:Place ;
           kwgl-ont:impactedBy ?h .

    ?h a kwgl-ont:Hurricane .
    BIND(?place AS ?entity)

    OPTIONAL { ?h kwgl-ont:hasStartDate ?startDate }
    OPTIONAL { ?h kwgl-ont:hasEndDate   ?endDate }

    ?entity ?property ?value .
    FILTER EXISTS { ?property a owl:DatatypeProperty }

    # Limit to properties that are hurricane‑specific or damage related
    FILTER ( regex(str(?property), "Hurricane", "i")
          || regex(str(?property), "damage",     "i")
          || regex(str(?property), "numberOf.*Hurricanes", "i") )
  }
}
ORDER BY ?entity ?property

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?event ?place 
       ?damageToCrops 
       ?damageToInfrastructure 
       ?tornadoDollarDamage
WHERE {
  # Tornado‑specific hazard events
  ?event a kwgl-ont:Tornado .

  # Temporal information (optional – ensures the event has dates)
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate   ?endDate   . }

  # Relationship to a geographical place
  ?event kwgl-ont:hasImpacted ?place .

  # Damage details attached to the event itself
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars       ?damageToCrops . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }

  # Dollar damage of tornadoes recorded on the impacted place
  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDollarDamage .
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?author ?advisor
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
  ?advisor a coresr-ont:Advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?typeLabel
WHERE {
  ?publication coresr-ont:hasPublicationType ?pubType .
  OPTIONAL { ?pubType coresr-ont:typeAsString ?typeLabel . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?agent ?department
WHERE {
  ?agent a coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?fieldOfStudy ?publication ?title
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
  OPTIONAL { ?publication coresr-ont:hasTitle ?title . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?city ?college
WHERE {
  ?college coresr-ont:partOf ?university .
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .
  ?location coresr-ont:atState ?state .
  ?state   coresr-ont:inCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication (COUNT(DISTINCT ?dept) AS ?numDepts)
WHERE {
  { ?publication coresr-ont:submittedBy ?role . }
  UNION
  { ?publication coresr-ont:hasContributor ?role . }
  ?role a coresr-ont:Role .
  ?role coresr-ont:isPerformedBy ?agent .
  ?agent coresr-ont:associatedWith ?dept .
  ?dept a coresr-ont:Department .
}
GROUP BY ?publication
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?typeLabel (AVG(?days) AS ?avgDays)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:hasPublicationType ?ptype ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate .
  ?ptype coresr-ont:typeAsString ?typeLabel .

  BIND ( xsd:dateTime(?pubDate) AS ?pubDT )
  BIND ( xsd:dateTime(?subDate) AS ?subDT )
  # duration between publication and submission
  BIND ( (?pubDT - ?subDT) / "PT1D"^^xsd:dayTimeDuration AS ?days )
}
GROUP BY ?typeLabel
ORDER BY DESC(?avgDays)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?department a coresr-ont:Department .
  ?department coresr-ont:hasAssociatedAgent ?agent .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?ci .
    ?ci a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)
LIMIT 1

