PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?city ?college
WHERE {
  ?university a coress-ont:University ;
              coress-ont:atCity ?city ;
              coress-ont:hasCollege ?college .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?university ?pubCount
WHERE {
  # Count publications per university and state
  {
    SELECT ?state ?university (COUNT(DISTINCT ?pub) AS ?pubCount)
    WHERE {
      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?dept .
      ?dept coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  # Determine the maximum count per state
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt)
    WHERE {
      {
        SELECT ?state ?university (COUNT(DISTINCT ?pub) AS ?cnt)
        WHERE {
          ?pub a coress-ont:Publication .
          ?pub coress-ont:submittedBy ?author .
          ?author coress-ont:isPerformedBy ?agent .
          ?agent coress-ont:worksInDepartment ?dept .
          ?dept coress-ont:departmentOf ?college .
          ?college coress-ont:collegeOf ?university .
          ?university coress-ont:atState ?state .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  FILTER(?pubCount = ?maxCnt)
}
ORDER BY ?state

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?pubType (AVG(?days) AS ?avgDays)
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:hasPublicationType ?pubType ;
       coress-ont:dateOfSubmission ?subDate ;
       coress-ont:dateOfPublication ?pubDate .
  BIND (xsd:dateTime(?pubDate) - xsd:dateTime(?subDate) AS ?duration)
  BIND (SECONDS(?duration) / 86400 AS ?days)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDays)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(?agent) AS ?missingCount)
WHERE {
  ?department a coress-ont:Department .
  ?department coress-ont:hasAgent ?agent .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName }
}
GROUP BY ?department
ORDER BY DESC(?missingCount)
LIMIT 1

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?name ?type ?startDate ?endDate ?deaths ?damageCrops ?damageInfra ?affectedArea WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?name .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?healthAttribute ?value
WHERE {
  ?place a kwgl-ont:Place .
  {
    ?place kwgl-ont:percentDiabetic ?value .
    BIND(kwgl-ont:percentDiabetic AS ?healthAttribute)
  } UNION {
    ?place kwgl-ont:percentObese ?value .
    BIND(kwgl-ont:percentObese AS ?healthAttribute)
  } UNION {
    ?place kwgl-ont:percentBelowPovertyLine ?value .
    BIND(kwgl-ont:percentBelowPovertyLine AS ?healthAttribute)
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?attrName ?value
WHERE {
  ?place a kwgl-ont:Place .

  VALUES (?prop ?attrName) {
    (kwgl-ont:hasPopulation           "population")
    (kwgl-ont:hasNumberOfHouseHolds   "households")
    (kwgl-ont:percentBelowPovertyLine "percentBelowPovertyLine")
    (kwgl-ont:percentDiabetic         "percentDiabetic")
    (kwgl-ont:percentObese            "percentObese")
  }

  ?place ?prop ?value .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?e ?name ?totalEarthquakes WHERE {
  # total count of distinct earthquake events
  { SELECT (COUNT(DISTINCT ?e2) AS ?totalEarthquakes)
    WHERE { ?e2 a kwgl-ont:Earthquake . } }

  # list each earthquake event
  ?e a kwgl-ont:Earthquake .
  OPTIONAL { ?e kwgl-ont:hasName ?name . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazard ?name ?startDate ?endDate ?deaths ?damageInfra ?affectedArea ?type WHERE {
  ?hazard a kwgl-ont:Earthquake .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?name ?deaths ?damageInfra ?damageCrops ?affectedArea
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?damageProperty WHERE {
  # Damage properties directly attached to hazard events
  { 
    ?hazard a kwgl-ont:HazardEvent ;
            ?damageProperty ?val .
    FILTER(?damageProperty IN (kwgl-ont:damageToInfrastructureInDollars,
                               kwgl-ont:damageToCropsInDollars))
  }
  UNION
  # Damage properties of places that are impacted by a hazard
  {
    ?place a kwgl-ont:Place ;
           kwgl-ont:impactedBy ?hazard ;
           ?damageProperty ?val .
    FILTER(STRSTARTS(STR(?damageProperty), STR(kwgl-ont:dollarDamageOf)))
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?attr ?value ?startDate ?endDate
WHERE {
  ?h a kwgl-ont:Hurricane .
  OPTIONAL { ?h kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?h kwgl-ont:hasEndDate   ?endDate . }
  ?place kwgl-ont:impactedBy ?h .
  ?place ?attr ?value .
  FILTER regex(str(?attr), "Hurricane")
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?tornadoEvent ?place 
       ?startDate ?endDate 
       ?infraDamage ?cropDamage ?deaths
WHERE {
  # Tornado-specific hazard events
  ?tornadoEvent a kwgl-ont:Tornado .

  # Relate to the impacted place
  ?tornadoEvent kwgl-ont:hasImpacted ?place .

  # Temporal information (optional but included if present)
  OPTIONAL { ?tornadoEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?tornadoEvent kwgl-ont:hasEndDate   ?endDate   . }

  # Damage details (if any)
  OPTIONAL { ?tornadoEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?tornadoEvent kwgl-ont:damageToCropsInDollars           ?cropDamage . }
  OPTIONAL { ?tornadoEvent kwgl-ont:numberOfDeaths                  ?deaths . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazard ?hazardName ?place ?placeName ?type ?startDate ?endDate ?infraDamage ?cropsDamage
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?type ;
          kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?hazard kwgl-ont:hasName            ?hazardName . }
  OPTIONAL { ?place  kwgl-ont:hasName            ?placeName  . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate       ?startDate  . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate         ?endDate    . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars        ?cropsDamage . }

  VALUES ?type {
    kwglr:hurricane
    kwglr:tornado
    kwglr:tropicalStorm
    kwglr:tropicalDepression
    kwglr:stormSurgeTide
    kwglr:highWind
    kwglr:strongWind
    kwglr:thunderstormWind
    kwglr:marineHighWind
    kwglr:marineStrongWind
    kwglr:marineTropicalStorm
    kwglr:marineTropicalDepression
    kwglr:hail
    kwglr:heavyRain
    kwglr:heavySnow
    kwglr:blizzard
    kwglr:winterStorm
    kwglr:flashFlood
    kwglr:flood
  }
}
ORDER BY ?startDate

