PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?city ?college
WHERE {
  ?college a coresr-ont:College ;
           coresr-ont:partOf ?univ .
  ?univ a coresr-ont:University ;
        coresr-ont:locatedAt ?loc .
  ?loc a coresr-ont:Location ;
       coresr-ont:atState ?state .
  ?state a coresr-ont:State ;
         coresr-ont:inCity ?city .
}

PREFIX core: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?stateLabel ?univ ?pubCount WHERE {
  # Count publications per university and state
  {
    SELECT ?univ ?state (COUNT(DISTINCT ?pub) AS ?pubCount) WHERE {
      ?pub a core:Publication .
      ?pub core:submittedBy ?author .
      ?author a core:Author .
      ?author core:isPerformedBy ?agent .
      ?agent core:associatedWith ?dept .
      ?dept core:partOf ?college .
      ?college core:partOf ?univ .
      ?univ core:locatedAt ?loc .
      ?loc core:atState ?state .
    }
    GROUP BY ?univ ?state
  }
  # Determine the maximum publication count per state
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt) WHERE {
      SELECT ?state (COUNT(DISTINCT ?pub2) AS ?cnt) WHERE {
        ?pub2 a core:Publication .
        ?pub2 core:submittedBy ?author2 .
        ?author2 a core:Author .
        ?author2 core:isPerformedBy ?agent2 .
        ?agent2 core:associatedWith ?dept2 .
        ?dept2 core:partOf ?college2 .
        ?college2 core:partOf ?univ2 .
        ?univ2 core:locatedAt ?loc2 .
        ?loc2 core:atState ?state .
      }
      GROUP BY ?state ?univ2
    }
    GROUP BY ?state
  }
  FILTER(?pubCount = ?maxCnt)
  OPTIONAL { ?state rdfs:label ?stateLabel . }
}
ORDER BY ?state

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pub ?title WHERE {
  ?pub a coresr-ont:Publication .
  OPTIONAL { ?pub coresr-ont:hasTitle ?title . }
  ?pub coresr-ont:hasContributor ?role .
  ?role coresr-ont:isPerformedBy ?person .
  ?person coresr-ont:associatedWith ?dept .
}
GROUP BY ?pub ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?typeLabel (AVG(?diff) AS ?avgDays)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:hasPublicationType ?ptype ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate .
  ?ptype coresr-ont:typeAsString ?typeLabel .
  BIND( (xsd:date(?pubDate) - xsd:date(?subDate)) AS ?diff )
}
GROUP BY ?typeLabel
ORDER BY DESC(?avgDays)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author ?field
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor ;
          coresr-ont:submits ?pub .
  ?pub   coresr-ont:associatedFieldOfStudy ?field .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department ?missingFamilyNameCount
WHERE {
  # Count agents per department that lack a family name
  {
    SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
    WHERE {
      ?agent a coresr-ont:Agent ;
             coresr-ont:associatedWith ?department .
      FILTER NOT EXISTS {
        ?agent coresr-ont:hasContactInformation ?ci .
        ?ci a coresr-ont:FamilyName .
      }
    } GROUP BY ?department
  }

  # Determine the maximum count across all departments
  {
    SELECT (MAX(?cnt) AS ?maxCount)
    WHERE {
      SELECT (COUNT(?ag) AS ?cnt)
      WHERE {
        ?ag a coresr-ont:Agent ;
            coresr-ont:associatedWith ?dept .
        FILTER NOT EXISTS {
          ?ag coresr-ont:hasContactInformation ?ci2 .
          ?ci2 a coresr-ont:FamilyName .
        }
      } GROUP BY ?dept
    }
  }

  # Keep only departments with the highest count
  FILTER(?missingFamilyNameCount = ?maxCount)
}
ORDER BY DESC(?missingFamilyNameCount)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

