        coresr-ont:hasPart ?college ;
        coresr-ont:locatedAt ?loc .
  ?college a coresr-ont:College .
  ?loc coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?state ?university ?pubCount WHERE {
  {
    SELECT ?state ?university (COUNT(?pub) AS ?pubCount)
    WHERE {
      ?pub a coresr-ont:Publication .
      ?pub coresr-ont:submittedBy ?authorRole .
      ?authorRole coresr-ont:isPerformedBy ?agent .
      ?agent coresr-ont:associatedWith ?dept .
      ?dept coresr-ont:partOf ?college .
      ?college coresr-ont:partOf ?university .
      ?university a coresr-ont:University .
      ?university coresr-ont:locatedAt ?loc .
      ?loc coresr-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt)
    WHERE {
      {
        SELECT ?state (COUNT(?pub2) AS ?cnt)
        WHERE {
          ?pub2 a coresr-ont:Publication .
          ?pub2 coresr-ont:submittedBy ?authorRole2 .
          ?authorRole2 coresr-ont:isPerformedBy ?agent2 .
          ?agent2 coresr-ont:associatedWith ?dept2 .
          ?dept2 coresr-ont:partOf ?college2 .
          ?college2 coresr-ont:partOf ?university2 .
          ?university2 a coresr-ont:University .
          ?university2 coresr-ont:locatedAt ?loc2 .
          ?loc2 coresr-ont:atState ?state .
        }
        GROUP BY ?state ?university2
      }
    }
    GROUP BY ?state
  }
  FILTER (?pubCount = ?maxCnt)
}
ORDER BY ?state

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?title
WHERE {
  ?publication a coresr-ont:Publication .
  OPTIONAL { ?publication coresr-ont:hasTitle ?title . }

  ?authorRole a coresr-ont:Author ;
              coresr-ont:isPerformedBy ?agent .

  ?publication coresr-ont:submittedBy ?authorRole .
  ?agent coresr-ont:associatedWith ?dept .
}
GROUP BY ?publication ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?typeLabel (AVG(?duration) AS ?averageDuration)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:hasPublicationType ?ptype ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate .

  ?ptype coresr-ont:typeAsString ?typeLabel .

  BIND ( (?pubDate - ?subDate) AS ?duration )
}
GROUP BY ?typeLabel
ORDER BY DESC(?averageDuration)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author ?field
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
  ?pub   coresr-ont:submittedBy ?author ;
         coresr-ont:associatedFieldOfStudy ?field .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department (COUNT(DISTINCT ?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?ci .
    ?ci a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)
LIMIT 1

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?type ?time ?geom ?label
WHERE {
  # any instance that is a Hazard (or subclass thereof)
  ?hazard a kwg-ont:Hazard .

  # its most specific type (excluding the generic kwg-ont:Hazard class)
  OPTIONAL {
    ?hazard a ?type .
    FILTER(?type != kwg-ont:Hazard)
  }

  # when it happened
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time . }

  # spatial details (geometry, if present)
  OPTIONAL { ?hazard kwg-ont:hasGeometry ?geom . }

  # human‑readable label or name, if available
  OPTIONAL { ?hazard rdfs:label ?label . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place kwg-ont:hospitalName   ?name . }
  OPTIONAL { ?place kwg-ont:siteName       ?name . }
  OPTIONAL { ?place kwg-ont:hasName        ?name . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?healthConcern
WHERE {
  ?obs a kwg-ont:PublicHealthObservation ;
       sosa:observedProperty ?healthConcern ;
       sosa:hasFeatureOfInterest ?place .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?attribute
WHERE {
  ?collection a kwg-ont:CensusACS5YearEstimatesObservationCollection ;
              sosa:hasFeatureOfInterest ?place ;
              sosa:hasMember ?obs .
  ?obs a kwg-ont:CensusACS5YearEstimatesObservation ;
       sosa:observedProperty ?attribute .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?earthquake ?total
WHERE {
  { SELECT (COUNT(DISTINCT ?e) AS ?total)
    WHERE { ?e a kwg-ont:Earthquake . }
  }
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?attribute (COUNT(DISTINCT ?tornado) AS ?tornadoCount)
WHERE {
  { 
    ?tornado a kwg-ont:NOAATornado .
    ?place   a geo:Feature .
    ?tornado ?attribute ?place .
  } UNION {
    ?tornado a kwg-ont:NOAATornado .
    ?place   a geo:Feature .
    ?place   ?attribute ?tornado .
  }
}
GROUP BY ?attribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?storm
                ?geom
                ?temporalScope
                ?observableProperty
WHERE {
  # Storm track entities (storm‑specific hazard)
  ?storm a kwg-ont:StormTrack .

  # Geometry of the storm (if available)
  OPTIONAL { ?storm kwg-ont:hasGeometry ?geom . }

  # Temporal scope of the storm (if recorded)
  OPTIONAL { ?storm kwg-ont:hasTemporalScope ?temporalScope . }

  # Observable properties linked via observations
  OPTIONAL {
    ?obs a kwg-ont:StormTrackObservation ;
         sosa:hasFeatureOfInterest ?storm ;
         sosa:observedProperty ?observableProperty .
  }
}
ORDER BY ?storm

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?floodEvent ?floodType ?geometry ?defaultGeometry ?temporalScope ?place
WHERE {
  VALUES ?floodClass { kwg-ont:NOAAFlood kwg-ont:NOAAFlashFlood kwg-ont:NOAALakeshoreFlood }
  ?floodEvent a ?floodClass .
  BIND (STRAFTER(STR(?floodClass), "#") AS ?floodType)

  OPTIONAL { ?floodEvent kwg-ont:hasGeometry ?geometry . }
  OPTIONAL { ?floodEvent geo:hasDefaultGeometry ?defaultGeometry . }
  OPTIONAL { ?floodEvent kwg-ont:hasTemporalScope ?temporalScope . }

  OPTIONAL {
    ?floodEvent kwg-ont:spatialRelation ?place .
    FILTER ( ?place a geo:Feature )
  }
}
ORDER BY ?floodEvent

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?climateAttribute
WHERE {
  ?obs a kwg-ont:ClimateObservation ;
       sosa:observedProperty ?climateAttribute ;
       sosa:hasFeatureOfInterest ?place .
  ?climateAttribute a kwg-ont:ClimateObservableProperty .
  ?place a geo:Feature .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?earthquake ?type ?temporalScope ?geometry
WHERE {
  # Earthquake hazards (instances of the Earthquake class)
  ?earthquake a kwg-ont:Earthquake .

  # Their concrete type(s) – include the Earthquake class itself and any subclass it may belong to
  OPTIONAL { ?earthquake a ?type . }

  # Optional details
  OPTIONAL { ?earthquake kwg-ont:hasTemporalScope ?temporalScope . }
  OPTIONAL { ?earthquake kwg-ont:hasGeometry      ?geometry . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardEvent ?impactProperty
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?impactProperty ;
       sosa:hasFeatureOfInterest ?hazardEvent .

  # Ensure the feature of interest is a hazard event (NOAAHazardEvent)
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?damageDetail
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?damageDetail ;
       sosa:hasFeatureOfInterest ?hazard .
  ?hazard a kwg-ont:NOAAHazardEvent .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT 
       ?hurricane
       ?place
       ?relation
       ?geom
       ?temporalScope
       ?impactObs
       ?impactProp
       ?impactTime
WHERE {
  # Hurricane events
  ?hurricane a kwg-ont:NOAAHurricane .

  # Relations to geographical places (AdministrativeRegion, S2Cell, etc.)
  { ?hurricane kwg-ont:sfWithin   ?place .
    BIND("sfWithin" AS ?relation) }
  UNION
  { ?hurricane kwg-ont:spatialRelation ?place .
    BIND("spatialRelation" AS ?relation) }

  # Optional geometry and temporal scope of the hurricane
  OPTIONAL { ?hurricane kwg-ont:hasGeometry      ?geom . }
  OPTIONAL { ?hurricane kwg-ont:hasTemporalScope ?temporalScope . }

  # Damage impact observations linked to the hurricane
  OPTIONAL {
    ?impactObs a kwg-ont:ImpactObservation ;
               sosa:hasFeatureOfInterest ?hurricane ;
               sosa:observedProperty   ?impactProp .
    OPTIONAL { ?impactObs sosa:resultTime ?impactTime . }
  }
}
ORDER BY ?hurricane

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?damageProp ?value ?hazard ?place ?time
WHERE {
  # Impact observations that record damage
  ?obs a kwg-ont:ImpactObservation ;
       sosa:observedProperty ?damageProp ;
       sosa:hasFeatureOfInterest ?hazard .

  # Restrict to storm‑related hazards (NOAA storm events)
  VALUES ?stormClass { 
      kwg-ont:NOAATornado
      kwg-ont:NOAAHurricane
      kwg-ont:NOAAFlashFlood
      kwg-ont:NOAAWinterStorm
      kwg-ont:NOAAStormSurgeTide
  }
  ?hazard a ?stormClass .

  # Spatial link to a geographic place
  ?hazard kwg-ont:spatialRelation ?place .
  ?place a geo:Feature .

  # Temporal extent (if recorded)
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time . }

  # Damage value, if a result node is attached
  OPTIONAL {
    ?obs sosa:hasResult ?res .
    ?res kwg-ont:value ?value .
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author
WHERE {
  ?author a coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication .
  OPTIONAL { ?publication coress-ont:hasDOI ?doi . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city
WHERE {
  ?university a coress-ont:University ;
              coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author ?advisor
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?type
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?type .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?agent ?department
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?city ?college
WHERE {
  ?univ a coress-ont:University ;
        coress-ont:atCity ?city ;
        coress-ont:hasCollege ?college .
  ?college a coress-ont:College .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publicationType (AVG(?duration) AS ?averageDuration)
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:hasPublicationType ?publicationType ;
       coress-ont:dateOfSubmission ?subDate ;
       coress-ont:dateOfPublication ?pubDate .
  BIND( (?pubDate - ?subDate) AS ?duration )
}
GROUP BY ?publicationType
ORDER BY DESC(?averageDuration)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department ?missingCount
WHERE {
  # Count agents without a family name per department
  {
    SELECT ?department (COUNT(?agent) AS ?missingCount)
    WHERE {
      ?department a coress-ont:Department .
      ?department coress-ont:hasAgent ?agent .
      FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
    }
    GROUP BY ?department
  }
  # Determine the maximum missing‑family‑name count across all departments
  {
    SELECT (MAX(?cnt) AS ?maxCount)
    WHERE {
      SELECT (COUNT(?a) AS ?cnt)
      WHERE {
        ?dept a coress-ont:Department .
        ?dept coress-ont:hasAgent ?a .
        FILTER NOT EXISTS { ?a coress-ont:hasFamilyName ?fn2 }
      }
    }
  }
  FILTER (?missingCount = ?maxCount)
}
ORDER BY DESC(?missingCount)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazard
  ?name
  ?type
  ?startDate
  ?endDate
  ?affectedArea
  ?damageCrops
  ?damageInfrastructure
