PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place
                ?percentBelowPovertyLine
                ?percentDiabetic
                ?percentObese
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?percentBelowPovertyLine . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?percentDiabetic . }
  OPTIONAL { ?place kwgl-ont:percentObese ?percentObese . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?range
  ?parentAttribute
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  ?attribute rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { 
    ?attribute rdfs:subPropertyOf ?parentAttribute .
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?event ?name ?startDate ?endDate ?affectedArea ?damageCrops ?damageInfrastructure ?deaths
WHERE {
  { ?event rdf:type kwgl-ont:Earthquake . }
  UNION
  { 
    ?event rdf:type kwgl-ont:HazardEvent ;
           kwgl-ont:hasHazardType kwglr:earthquake .
  }

  OPTIONAL { ?event kwgl-ont:hasName ?name . }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths . }
}
ORDER BY ?event

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazardEvent
  ?affectedAreaInAcres
  ?damageToCropsInDollars
  ?damageToInfrastructureInDollars
  ?numberOfDeaths
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres          ?affectedAreaInAcres . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars       ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths               ?numberOfDeaths . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?place
  ?placeName
  ?hazard
  ?startDate
  ?endDate
  ?damageAmount
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType kwglr:tornado ;
          kwgl-ont:hasImpacted ?place ;
          kwgl-ont:hasStartDate ?startDate ;
          kwgl-ont:hasEndDate ?endDate .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageAmount . }
}
ORDER BY ?place ?startDate

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazardEvent ?place ?hazardType ?damageToCrops ?damageToInfrastructure ?startDate ?endDate
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  ?hazardEvent kwgl-ont:hasHazardType ?hazardType .
  FILTER ( regex(lcase(str(?hazardType)), "storm") )

  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }

  ?hazardEvent kwgl-ont:hasImpacted ?place .
  ?place a kwgl-ont:Place .
}
ORDER BY ?hazardEvent

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazard
  ?hazardLabel
  ?type
  ?typeLabel
  ?startDate
  ?endDate
  ?affectedArea
  ?numDeaths
  ?damageCrops
  ?damageInfrastructure
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardLabel . }

  OPTIONAL {
    ?hazard kwgl-ont:hasHazardType ?type .
    OPTIONAL { ?type rdfs:label ?typeLabel . }
  }

  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate   ?endDate   . }

  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres          ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths                ?numDeaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars        ?damageCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
}
ORDER BY ?startDate

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}
ORDER BY ?place

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?totalCount
WHERE {
  # Sub‑query to compute the total number of tornado‑specific attributes for places
  {
    SELECT (COUNT(DISTINCT ?attr) AS ?totalCount)
    WHERE {
      ?attr rdf:type owl:DatatypeProperty ;
            rdfs:domain kwgl-ont:Place .
      OPTIONAL { ?attr rdfs:label ?attrLabel . }
      FILTER (
        CONTAINS(LCASE(STR(?attr)), "tornado") ||
        CONTAINS(LCASE(STR(?attrLabel)), "tornado")
      )
    }
  }

  # Retrieve each individual attribute
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .
  OPTIONAL { ?attribute rdfs:label ?label . }
  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "tornado") ||
    CONTAINS(LCASE(STR(?label)), "tornado")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  ?attribute rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    (BOUND(?attributeLabel) && CONTAINS(LCASE(STR(?attributeLabel)), "flood"))
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?attributeLabel ?range
WHERE {
  ?attribute a owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  FILTER (
    CONTAINS(LCASE(STR(?attributeLabel)), "average") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "temperature") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "cooling") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "heating") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "maximum") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "minimum")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?earthquake
  ?startDate
  ?endDate
  ?affectedArea
  ?deaths
  ?cropDamage
  ?infraDamage
  ?hazardType
  ?hazardTypeLabel
WHERE {
  ?earthquake rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate   ?endDate   . }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }

  OPTIONAL {
    ?earthquake kwgl-ont:hasHazardType ?hazardType .
    OPTIONAL { ?hazardType rdfs:label ?hazardTypeLabel . }
  }
}
ORDER BY ?earthquake

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
