PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?city ?college ?university
WHERE {
  ?university a coress-ont:University ;
              coress-ont:atCity ?city .
  ?college    a coress-ont:College ;
              coress-ont:collegeOf ?university .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?university ?pubCount WHERE {
  # Count publications per university (and its state)
  {
    SELECT ?university ?state (COUNT(?pub) AS ?pubCount) WHERE {
      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author coress-ont:worksInDepartment ?dept .
      ?dept   coress-ont:departmentOf    ?college .
      ?college coress-ont:collegeOf       ?university .
      ?university coress-ont:atState     ?state .
    }
    GROUP BY ?university ?state
  }

  # Retrieve the maximum publication count for each state
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt) WHERE {
      {
        SELECT ?university ?state (COUNT(?pub) AS ?cnt) WHERE {
          ?pub a coress-ont:Publication .
          ?pub coress-ont:submittedBy ?author .
          ?author coress-ont:worksInDepartment ?dept .
          ?dept   coress-ont:departmentOf    ?college .
          ?college coress-ont:collegeOf       ?university .
          ?university coress-ont:atState     ?state .
        }
        GROUP BY ?university ?state
      }
    } GROUP BY ?state
  }

  FILTER(?pubCount = ?maxCnt)
}
ORDER BY ?state DESC(?pubCount)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?pub ?title
WHERE {
  ?pub a coress-ont:Publication .
  OPTIONAL { ?pub coress-ont:hasTitle ?title . }
  ?pub coress-ont:submittedBy ?author .
  ?agent coress-ont:performsRole ?author ;
         coress-ont:worksInDepartment ?dept .
}
GROUP BY ?pub ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?pubType (AVG(?duration) AS ?avgDuration)
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:hasPublicationType ?pubType ;
       coress-ont:dateOfSubmission ?subDate ;
       coress-ont:dateOfPublication ?pubDate .
  BIND(?pubDate - ?subDate AS ?duration)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDuration)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?author ?advisor ?field ?title
