          coress-ont:submits ?pub .

  ?pub a coress-ont:Publication ;
       coress-ont:associatedFieldOfStudy ?field ;
       coress-ont:hasTitle ?title .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?department ?missingFamilyNameCount WHERE {
  # Count agents per department that lack a family name
  {
    SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount) WHERE {
      ?agent a coress-ont:Agent ;
             coress-ont:worksInDepartment ?department .
      FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
    } GROUP BY ?department
  }
  # Determine the maximum such count across all departments
  {
    SELECT (MAX(?cnt) AS ?maxCount) WHERE {
      SELECT (COUNT(?a) AS ?cnt) WHERE {
        ?a a coress-ont:Agent ;
           coress-ont:worksInDepartment ?d .
        FILTER NOT EXISTS { ?a coress-ont:hasFamilyName ?fn2 }
      } GROUP BY ?d
    }
  }
  # Keep only departments with the maximum count
  FILTER (?missingFamilyNameCount = ?maxCount)
}
ORDER BY DESC(?missingFamilyNameCount)

