PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?university ?pubCount WHERE {
  # Count publications per university
  {
    SELECT ?univ (COUNT(DISTINCT ?pub) AS ?pubCount) ?state WHERE {
      ?univ a coress-ont:University ;
            coress-ont:atState ?state .

      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent  coress-ont:worksInDepartment ?dept .
      ?dept   coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?univ .
    }
    GROUP BY ?univ ?state
  }

  # Determine the maximum publication count per state
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt) WHERE {
      ?univ a coress-ont:University ;
            coress-ont:atState ?state .

      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent  coress-ont:worksInDepartment ?dept .
      ?dept   coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?univ .

    }
    GROUP BY ?state
    BIND(COUNT(DISTINCT ?pub) AS ?cnt)
  }

  FILTER(?pubCount = ?maxCnt)

  BIND(?univ AS ?university)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?pub ?title WHERE {
  ?pub a coress-ont:Publication .
  OPTIONAL { ?pub coress-ont:hasTitle ?title . }
  ?pub coress-ont:submittedBy ?author .
  ?author coress-ont:isPerformedBy ?agent .
  ?agent coress-ont:worksInDepartment ?dept .
}
GROUP BY ?pub ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?type (AVG(?duration) AS ?avgDuration)
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:hasPublicationType ?type ;
       coress-ont:dateOfSubmission ?subDate ;
       coress-ont:dateOfPublication ?pubDate .
  BIND( (xsd:dateTime(CONCAT(STR(?pubDate), "T00:00:00")) -
         xsd:dateTime(CONCAT(STR(?subDate), "T00:00:00"))) AS ?duration )
}
GROUP BY ?type
ORDER BY DESC(?avgDuration)

