PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department ?missingCount
WHERE {
  # Sub‑query: compute the maximum missing‑family‑name count across departments
  {
    SELECT (MAX(?cnt) AS ?maxCnt)
    WHERE {
      SELECT ?dept (COUNT(?agent) AS ?cnt)
      WHERE {
        ?agent a coress-ont:Agent ;
               coress-ont:worksInDepartment ?dept .
        FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
      }
      GROUP BY ?dept
    }
  }

  # Main query: retrieve departments whose count equals the maximum
  SELECT ?department (COUNT(?a) AS ?missingCount)
  WHERE {
    ?a a coress-ont:Agent ;
       coress-ont:worksInDepartment ?department .
    FILTER NOT EXISTS { ?a coress-ont:hasFamilyName ?fn }
  }
  GROUP BY ?department
  HAVING (COUNT(?a) = ?maxCnt)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazard
  ?name
  ?type
  ?startDate
  ?endDate
  ?affectedArea
  ?deaths
  ?cropDamage
  ?infraDamage
WHERE {
  ?hazard a kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
}
ORDER BY ?startDate

