PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute a owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "hurricane")
  )

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?tornadoEvent
  ?impactedPlace
  ?startDate
  ?endDate
  ?damageToCrops
  ?damageToInfrastructure
  ?dollarDamageOnPlace
WHERE {
  ?tornadoEvent rdf:type kwgl-ont:Tornado .

  OPTIONAL { ?tornadoEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?tornadoEvent kwgl-ont:hasEndDate   ?endDate . }

  OPTIONAL { ?tornadoEvent kwgl-ont:damageToCropsInDollars        ?damageToCrops . }
  OPTIONAL { ?tornadoEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }

  ?tornadoEvent kwgl-ont:hasImpacted ?impactedPlace .

  OPTIONAL {
    ?impactedPlace kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageOnPlace .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?hazard
  ?hazardTypeLabel
  ?place
  ?placeName
  ?startDate
  ?endDate
  ?cropsDamage
  ?infraDamage
  ?deaths
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?type ;
          kwgl-ont:hasImpacted ?place .

  FILTER (?type IN (kwglr:hurricane,
                    kwglr:tornado,
                    kwglr:tropicalStorm,
                    kwglr:tropicalDepression,
                    kwglr:stormSurgeTide))

  OPTIONAL { ?type rdfs:label ?hazardTypeLabel . }
  OPTIONAL { ?place rdfs:label ?placeName . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate   ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars      ?cropsDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths               ?deaths . }
}
ORDER BY ?startDate

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author
WHERE {
  ?author a coresr-ont:Author .
}

