SELECT ?publication ?typeLabel
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasPublicationType ?pubType .
  OPTIONAL { ?pubType coresr-ont:typeAsString ?typeLabel . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent a coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?field ?publication
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?field .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?city ?college
WHERE {
  ?univ a coresr-ont:University ;
        coresr-ont:hasPart ?college ;
        coresr-ont:locatedAt ?loc .
  ?loc coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?state ?university (?cnt AS ?publicationCount)
WHERE {
  # Count publications per university and state
  {
    SELECT ?state ?university (COUNT(DISTINCT ?pub) AS ?cnt)
    WHERE {
      ?university a coresr-ont:University .
      ?university coresr-ont:locatedAt ?loc .
      ?loc coresr-ont:atState ?state .

      ?pub a coresr-ont:Publication ;
           coresr-ont:hasContributor ?contrib .
      ?contrib coresr-ont:isPerformedBy ?agent .
      ?agent coresr-ont:associatedWith ?dept .
      ?dept coresr-ont:partOf ?college .
      ?college coresr-ont:partOf ?university .
    }
    GROUP BY ?state ?university
  }

  # Determine the maximum count per state
  {
    SELECT ?state (MAX(?c) AS ?maxCnt)
    WHERE {
      SELECT ?state ?uni (COUNT(DISTINCT ?p) AS ?c)
      WHERE {
        ?uni a coresr-ont:University .
        ?uni coresr-ont:locatedAt ?l .
        ?l coresr-ont:atState ?state .

        ?p a coresr-ont:Publication ;
           coresr-ont:hasContributor ?contrib2 .
        ?contrib2 coresr-ont:isPerformedBy ?agent2 .
        ?agent2 coresr-ont:associatedWith ?dept2 .
        ?dept2 coresr-ont:partOf ?college2 .
        ?college2 coresr-ont:partOf ?uni .
      }
      GROUP BY ?state ?uni
    } GROUP BY ?state
  }

  FILTER (?cnt = ?maxCnt)
}
ORDER BY ?state

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?title
WHERE {
  ?publication a coresr-ont:Publication .
  OPTIONAL { ?publication coresr-ont:hasTitle ?title . }

  {
    ?contrib coresr-ont:contributedTo ?publication ;
             coresr-ont:isPerformedBy ?agent .
  } UNION {
    ?author coresr-ont:isPerformedBy ?agent ;
            coresr-ont:isPerformedBy ?agent .
    ?publication coresr-ont:submittedBy ?author .
  }

  ?agent coresr-ont:associatedWith ?dept .
}
GROUP BY ?publication ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?typeLabel (AVG(?duration) AS ?averageDuration)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:hasPublicationType ?ptype ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate .
  ?ptype coresr-ont:typeAsString ?typeLabel .
  BIND ( ?pubDate - ?subDate AS ?duration )
}
GROUP BY ?typeLabel
ORDER BY DESC(?averageDuration)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author ?advisor ?fieldOfStudy
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor ;
          coresr-ont:submits ?pub .
  ?pub   coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department (COUNT(?agent) AS ?missingCount)
WHERE {
  ?department coresr-ont:hasAssociatedAgent ?agent .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?name .
    ?name a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingCount)
LIMIT 1

