SELECT DISTINCT ?city ?university ?college
WHERE {
  ?university a coress-ont:University ;
              coress-ont:atCity ?city .
  ?college a coress-ont:College ;
           coress-ont:collegeOf ?university .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?university ?pubCount
WHERE {
  # Count publications per university
  {
    SELECT ?university ?state (COUNT(?pub) AS ?pubCount)
    WHERE {
      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author a coress-ont:Author .
      ?author coress-ont:worksInDepartment ?dept .
      ?dept   coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?university ?state
  }
  # Determine the maximum count per state
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt)
    WHERE {
      {
        SELECT ?university ?state (COUNT(?pub) AS ?cnt)
        WHERE {
          ?pub a coress-ont:Publication .
          ?pub coress-ont:submittedBy ?author .
          ?author a coress-ont:Author .
          ?author coress-ont:worksInDepartment ?dept .
          ?dept   coress-ont:departmentOf ?college .
          ?college coress-ont:collegeOf ?university .
          ?university coress-ont:atState ?state .
        }
        GROUP BY ?university ?state
      }
    }
    GROUP BY ?state
  }
  FILTER(?pubCount = ?maxCnt)
}
ORDER BY ?state ?university

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?title
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:submits ?publication .
  ?agent coress-ont:performsRole ?author ;
         coress-ont:worksInDepartment ?dept .
  OPTIONAL { ?publication coress-ont:hasTitle ?title . }
}
GROUP BY ?publication ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department ?missingCount WHERE {
  {
    SELECT ?department (COUNT(?agent) AS ?missingCount)
    WHERE {
      ?agent a coress-ont:Agent .
      ?agent coress-ont:worksInDepartment ?department .
      FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
    } GROUP BY ?department
  }
  {
    SELECT (MAX(?cnt) AS ?maxCount)
    WHERE {
      SELECT (COUNT(?a) AS ?cnt)
      WHERE {
        ?a a coress-ont:Agent .
        ?a coress-ont:worksInDepartment ?dept .
        FILTER NOT EXISTS { ?a coress-ont:hasFamilyName ?fn2 }
      } GROUP BY ?dept
    }
  }
  FILTER(?missingCount = ?maxCount)
}
ORDER BY DESC(?missingCount)

