PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?stateName ?universityName ?pubCount
WHERE {
  # Determine the maximum publication count per state
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt)
    WHERE {
      SELECT ?state (COUNT(?pub) AS ?cnt)
      WHERE {
        ?uni a coresr-ont:University .
        ?uni coresr-ont:hasPart ?pub .
        ?pub a coresr-ont:Publication .
        ?uni coresr-ont:locatedAt ?loc .
        ?loc coresr-ont:atState ?state .
      }
      GROUP BY ?state
    }
    GROUP BY ?state
  }

  # Count publications per university (grouped by state)
  {
    SELECT ?state ?universityName (COUNT(?pub) AS ?cnt)
    WHERE {
      ?uni a coresr-ont:University .
      ?uni coresr-ont:hasPart ?pub .
      ?pub a coresr-ont:Publication .
      ?uni coresr-ont:locatedAt ?loc .
      ?loc coresr-ont:atState ?state .
      OPTIONAL { ?uni rdfs:label ?universityName . }
    }
    GROUP BY ?state ?universityName
  }

  FILTER(?cnt = ?maxCnt)

  BIND(?cnt AS ?pubCount)
  OPTIONAL { ?state rdfs:label ?stateName . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pub ?title (COUNT(DISTINCT ?dept) AS ?deptCount)
WHERE {
  ?pub a coresr-ont:Publication .
  OPTIONAL { ?pub coresr-ont:hasTitle ?title . }

  {
    ?pub coresr-ont:submittedBy ?author .
    ?author a coresr-ont:Author .
    ?author coresr-ont:isPerformedBy ?agent .
  } UNION {
    ?pub coresr-ont:hasContributor ?contrib .
    ?contrib a coresr-ont:Contributor .
    ?contrib coresr-ont:isPerformedBy ?agent .
  }

  ?agent coresr-ont:associatedWith ?dept .
}
GROUP BY ?pub ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?typeLabel (AVG(?days) AS ?avgDays)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate ;
       coresr-ont:hasPublicationType ?ptype .
  ?ptype coresr-ont:typeAsString ?typeLabel .

  BIND ( xsd:dateTime(?subDate) AS ?subDT )
  BIND ( xsd:dateTime(?pubDate) AS ?pubDT )
  BIND ( (?pubDT - ?subDT) / "P1D"^^xsd:dayTimeDuration AS ?days )
}
GROUP BY ?typeLabel
ORDER BY DESC(?avgDays)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author ?advisor ?fieldOfStudy
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor ;
          coresr-ont:submits ?pub .

  ?pub   coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?dept (COUNT(DISTINCT ?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?dept .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?fn .
    ?fn a coresr-ont:FamilyName .
  }
}
GROUP BY ?dept
ORDER BY DESC(?missingFamilyNameCount)
LIMIT 1

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT DISTINCT ?author
WHERE {
  ?author a coress-ont:Author .
}

