PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT DISTINCT ?city ?college
WHERE {
  ?college a coress-ont:College .
  ?college coress-ont:collegeOf ?univ .
  ?univ a coress-ont:University ;
        coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?university (COUNT(?pub) AS ?pubCount)
WHERE {
  # Count publications per university
  {
    SELECT ?state ?university (COUNT(?pub) AS ?cnt)
    WHERE {
      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?dept .
      ?dept  coress-ont:departmentOf   ?college .
      ?college coress-ont:collegeOf    ?university .
      ?university coress-ont:atState   ?state .
    }
    GROUP BY ?state ?university
  }
  # Determine the maximum count per state
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt)
    WHERE {
      SELECT ?state ?univTmp (COUNT(?pubTmp) AS ?cnt)
      WHERE {
        ?pubTmp a coress-ont:Publication .
        ?pubTmp coress-ont:submittedBy ?authorTmp .
        ?authorTmp coress-ont:isPerformedBy ?agentTmp .
        ?agentTmp coress-ont:worksInDepartment ?deptTmp .
        ?deptTmp  coress-ont:departmentOf   ?collegeTmp .
        ?collegeTmp coress-ont:collegeOf    ?univTmp .
        ?univTmp coress-ont:atState          ?state .
      }
      GROUP BY ?state ?univTmp
    } 
    GROUP BY ?state
  }
  FILTER (?cnt = ?maxCnt)
}
GROUP BY ?state ?university ?pubCount
ORDER BY ?state DESC(?pubCount)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?pubType (AVG(?duration) AS ?avgDuration)
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:hasPublicationType ?pubType ;
       coress-ont:dateOfSubmission ?subDate ;
       coress-ont:dateOfPublication ?pubDate .
  BIND ( (?pubDate - ?subDate) AS ?duration )
}
GROUP BY ?pubType
ORDER BY DESC(?avgDuration)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)
LIMIT 1
